type GearConfig = typeof DEFAULT_GEAR;

/** 专武映射（角色 → 专武 id + 约定叠影；2026-10 与用户确认的回退规则） */
const SIG_LIGHTCONES: Record<string, { id: string; refinement: number }> = {
  jingyuan: { id: '23010', refinement: 1 },
  sunday: { id: '23034', refinement: 1 },
  qingge: { id: '24005', refinement: 5 },
  tenghuang: { id: '24002', refinement: 1 },
  aglaea: { id: '23036', refinement: 1 },
};

/** 按成员光锥字段解析配装数值（2026-10 用户裁定「现在参数化」）：
 *  - 无 lightconeId/空串（旧档/未填）→ DEFAULT 约定值回退（晴歌叠5、其余叠1，零回归）；
 *  - 光锥 = 专武 → 按存档叠影查 lightcone-data 覆写（缺数据回落约定值）；
 *  - 光锥 ≠ 专武 → 该光锥来源效果置 0 禁用（使用点按 >0 守卫；遗器/位面条款照旧生效）。 */
function resolveGear(members: {
  id: string;
  lightconeId?: string;
  refinement?: number;
}[]): GearConfig {
  const g: GearConfig = {
    jingyuan: { ...DEFAULT_GEAR.jingyuan },
    sunday: { ...DEFAULT_GEAR.sunday },
    qingge: { ...DEFAULT_GEAR.qingge },
    tenghuang: { ...DEFAULT_GEAR.tenghuang },
    aglaea: { ...DEFAULT_GEAR.aglaea },
  };
  for (const m of members) {
    const sig = SIG_LIGHTCONES[m.id];
    if (!sig || !m.lightconeId) continue;
    if (m.lightconeId !== sig.id) {
      if (m.id === 'jingyuan') {
        g.jingyuan.dawnSkillUlt = 0;
        g.jingyuan.dawnFollowUp = 0;
      } else if (m.id === 'sunday') {
        g.sunday.flightEnergy = 0;
        g.sunday.hymnDamage = 0;
        g.sunday.spEveryActions = 0;
      } else if (m.id === 'qingge') {
        g.qingge.memNotFadeDamage = 0;
        g.qingge.memNotFadeDuration = 0;
      } else if (m.id === 'aglaea') {
        g.aglaea.zhijinMax = 0;
        g.aglaea.zhijinCritDmg = 0;
        g.aglaea.zhijinBasic = 0;
      }
      continue;
    }
    const p = lcParams(m.lightconeId, m.refinement ?? sig.refinement);
    if (!p) continue;
    if (m.id === 'jingyuan') {
      // #1 暴伤为面板值（游戏显示面板含光锥），引擎不重复吃
      g.jingyuan.dawnSkillUlt = p[1];
      g.jingyuan.dawnFollowUp = p[2];
    } else if (m.id === 'sunday') {
      g.sunday.flightEnergy = p[0];
      g.sunday.hymnDamage = p[1];
      g.sunday.hymnMax = p[2];
      g.sunday.hymnDuration = p[3];
      g.sunday.spEveryActions = p[4];
    } else if (m.id === 'qingge') {
      g.qingge.memNotFadeDamage = p[1];
      g.qingge.memNotFadeDuration = p[2];
    } else if (m.id === 'aglaea') {
      // #1 基础速度计入面板最终速度，引擎不单独结算
      g.aglaea.zhijinMax = p[1];
      g.aglaea.zhijinBasic = p[2];
      g.aglaea.zhijinCritDmg = p[3];
    }
  }
  return g;
}

