  const memberOf = (id: CharId): CombatMember => {
    const m = members.find((x) => x.id === id);
    if (!m) throw new Error(`队伍中没有角色：${id}`);
    return m;
  };
  const panelOf = (id: CharId): MemberPanel => memberOf(id).panel;
  /**
   * 基础攻击力（2026-11-07 用户裁定 A）：攻击力% 只乘基础攻击力，不再放大面板 attack 里已含的遗器%。
   * 未填 `baseAttack` 时退化为面板攻击力 → 与旧口径完全一致（向后兼容）。
   */
  const baseAtkOf = (id: CharId): number => {
    // 只对「队员」取面板：召唤物/敌方单位的 owner 可能不在队里（panelOf 会抛）
    const m = members.find((x) => x.id === id);
    if (!m) return 0;
    const b = m.panel.baseAttack;
    return b && b > 0 ? b : m.panel.attack;
  };
  /** 当前攻击力（2026-11-07 裁定 A）：有 baseAttack 时攻击% 只乘基础攻击力，否则旧口径 */
  const atkNowOf = (
    owner: CharId,
    holder: { buffs: { key: string; value: number; stacks: number }[] },
  ): number => {
    const p = panelOf(owner);
    const flat = buffSum(holder.buffs as never, 'atkFlat');
    const pct = buffSum(holder.buffs as never, 'atkPct');
    return usesBaseAtk(owner) ? p.attack + baseAtkOf(owner) * pct + flat : (p.attack + flat) * (1 + pct);
  };
  /** 是否按「裁定 A」口径计算（面板声明了 baseAttack → 攻击% 只乘基础攻击力） */
  const usesBaseAtk = (id: CharId): boolean => {
    const b = members.find((x) => x.id === id)?.panel.baseAttack;
    return !!b && b > 0;
  };

  /** 按当前晴歌面板刷新忆灵面板快照（召唤/状态改变时调用；已有 buff 不动） */
  const snapshotMemoPanel = (): void => {
    const p = panelOf('qingge');
    memoPanel = { ...p, elementDmg: p.elementDmg ? { ...p.elementDmg } : undefined };
  };
  /** 能量恢复效率的 buff 项（holderMap 声明后绑定；init 期早调回落 0，防 TDZ） */
  let energyRegenBuffOf: (id: CharId) => number = () => 0;
  const errMul = (id: CharId): number =>
    1 +
    panelOf(id).energyRegen +
    // 专武23054【上上签】：装备者自身能量恢复效率 +R%（持签期间动态）
    (lc54SignLeft > 0 && id === lc54Wear ? LC23054.err : 0) +
    // 专武23058：能量上限>120 每超10点额外充能效率（init 一次算死；基础err已烘面板不双计）
    (lc58ErrByWearer.get(id) ?? 0) +
    // energyRegen buff（同谐开拓者E2 等；光锥/面板来源已计不双计）
    energyRegenBuffOf(id);
  /** 技能等级 = 面板设定 + 星魂 E3/E5 提高（按上限封顶；星魂缺省 0 零回归） */
  const levelsOf = (id: CharId): SkillLevels => {
    const base: SkillLevels = { ...DEFAULT_LEVELS, ...memberOf(id).skillLevels };
    const up = EIDOLON_SKILL_UP[id];
    const e = memberOf(id).eidolonLevel ?? 0;
    if (!up || e < 3) return base;
    const out = { ...base };
    const add = (bonus?: Partial<Record<keyof SkillLevels, number>>): void => {
      if (!bonus) return;
      for (const k of Object.keys(bonus) as (keyof SkillLevels)[]) {
        out[k] = Math.min(SKILL_LEVEL_CAP[k], out[k] + (bonus[k] ?? 0));
      }
    };
    add(up.e3);
    if (e >= 5) add(up.e5);
    return out;
  };

    const techniques = config.techniques ?? true;
