  // ===== 智识 1201 青雀 helpers =====
  function qingqueEidolon(): number {
    return ids.has('qingque') ? (memberOf('qingque').eidolonLevel ?? 0) : 0;
  }
  /** 抽牌：3 花色等概率；鱼牌（花色 1）锁定，优先替换非鱼牌 */
  function qingqueDraw(n: number, notes: string[]): void {
    if (!ids.has('qingque') || n <= 0) return;
    for (let i = 0; i < n; i++) {
      const suit = Math.floor(rand01() * 3);
      if (qingqueHand.length < TRACE.qingque.handMax) {
        qingqueHand.push(suit);
      } else {
        const nonFish: number[] = [];
        for (let idx = 0; idx < qingqueHand.length; idx++) {
          if (qingqueHand[idx] !== 1) nonFish.push(idx);
        }
        if (nonFish.length > 0) {
          const idx = nonFish[Math.min(nonFish.length - 1, Math.floor(rand01() * nonFish.length))];
          qingqueHand[idx] = suit;
        }
      }
      if (qingqueEidolon() >= 2) gainEnergy('qingque', TRACE.qingque.eidolon2EnergyPerDraw);
    }
    notes.push('qingqueDraw');
  }
  /** 回合开始：4 张同花色 → 暗杠（消耗手牌、ATK+72%） */
  /** 普通普攻：使用 1 张当前花色最少的琼玉牌（120101 实读） */
  function qingqueConsumeLowestTile(): void {
    if (!ids.has('qingque') || qingqueHand.length === 0) return;
    const counts = [0, 0, 0];
    for (const suit of qingqueHand) counts[suit] += 1;
    let lowest = 0;
    for (let suit = 1; suit < counts.length; suit++) {
      if (counts[suit] < counts[lowest]) lowest = suit;
    }
    const idx = qingqueHand.indexOf(lowest);
    if (idx >= 0) qingqueHand.splice(idx, 1);
  }
  function qingqueTryDarkKong(notes: string[]): void {
    if (!ids.has('qingque') || qingqueDarkKong) return;
    if (qingqueHand.length < TRACE.qingque.handMax) return;
    const first = qingqueHand[0];
    if (!qingqueHand.every((s) => s === first)) return;
    qingqueHand = [];
    qingqueDarkKong = true;
    addBuff(holderOf('qingque'), {
      key: 'atkPct',
      value: TRACE.qingque.darkKongAtk,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'qingque',
      labelKey: 'qingqueDarkKong',
    });
    notes.push('qingqueDarkKong');
  }
  /** 本回合结束（普攻/强化普攻）：清战技层数/不求人/暗杠 */
  function qingqueEndTurn(): void {
    qingqueSkillStacks = 0;
    qingqueE4Active = false;
    qingqueExtraPending = false;
    qingqueInExtraAction = false;
    if (qingqueDarkKong) {
      qingqueDarkKong = false;
      removeBuffInstance(holderOf('qingque'), {
        key: 'atkPct',
        source: 'qingque',
        labelKey: 'qingqueDarkKong',
      });
    }
  }
  function qingqueSkillDmgBonus(): number {
    if (!ids.has('qingque') || qingqueSkillStacks <= 0) return 0;
    return (
      qingqueSkillStacks *
      (TRACE.qingque.skillDmgPerStack + TRACE.qingque.point07DmgPerStack)
    );
  }
  /** E4 追击：本次普攻/强化普攻主段倍率的 100% */
  function qingqueE4Seq(target: MonsterId, multiplier: number): number[] {
    if (!ids.has('qingque') || !qingqueE4Active) return [];
    const p = panelOf('qingque');
    return dealAttack({
      source: 'qingque',
      skillCode: 'qingque.e4',
      element: 'Quantum',
      level: p.level,
      statValue: p.attack,
      multiplier: multiplier * TRACE.qingque.eidolon4FollowupRatio,
      damageBonusExtra: 0,
      critRate: p.critRate,
      critDmg: p.critDmg,
      stance: 0,
      attackerBuffs: holderOf('qingque'),
      target,
      attackKind: 'followup',
    });
  }

