  function rinEidolon(): number {
    return ids.has('rin') ? (memberOf('rin').eidolonLevel ?? 0) : 0;
  }
  /** 我方每消耗/恢复 1 点 SP：行动者暴伤 +70%·2 回合；凛 +1 宝石 */
  function rinTalentOnSp(actor: CharId, n: number): void {
    if (!ids.has('rin') || n <= 0) return;
    const holder = holderOf(actor);
    const cur = findBuffInstance(holder, { key: 'critDmg', source: 'rin', labelKey: 'rinTalent' });
    const stackCap = actor === 'rin' && rinEidolon() >= 4 ? TRACE.rin.eidolon4MaxStacks : 1;
    const stacks = Math.min(stackCap, (cur?.stacks ?? 0) + n);
    addBuff(holder, {
      key: 'critDmg',
      value: TRACE.rin.talentCritDmg,
      stacks,
      duration: TRACE.rin.talentTurns,
      tick: 'holderEnd',
      source: 'rin',
      labelKey: 'rinTalent',
    });
    rinGem = Math.min(TRACE.rin.talentGemCap, rinGem + n);
  }
  function rinEnhancedReady(): boolean {
    return (
      ids.has('rin') &&
      (rinShadowGems > 0 || rinGem >= TRACE.rin.enhanceGemThreshold || sp >= TRACE.rin.enhanceSpThreshold)
    );
  }

