  /** 缇宝天赋追击（140304：AoE 全体生命倍率量子伤害；skillCode='tibao.talent' 防递归） */
  function tibaoTalentFollow(dmgBonusExtra = 0): number[] {
    const p = skillParams('140304', levelsOf('tibao').talent);
    const panel = panelOf('tibao');
    const seqs: number[] = [];
    relicFollowupStart('tibao');
    try {
      for (const t of aliveMonsters()) {
        seqs.push(
          ...dealAttack({
            source: 'tibao',
            skillCode: 'tibao.talent',
            element: panel.element,
            level: panel.level,
            statValue: tibaoHp(),
            hpBased: true,
            multiplier: p[0],
            damageBonusExtra: dmgBonusExtra,
            critRate: panel.critRate,
            critDmg: panel.critDmg,
            stance: 0,
            attackerBuffs: attackerHolder('tibao'),
            target: t,
          }),
        );
      }
    } finally {
      relicFollowupEnd();
    }
    return seqs;
  }
