  let memE4Resonance = false;
  /** 【声援】持有者及剩余回合（1800707 目标获得，持续3回合；
   * 真伤比例=1800707参数 + point08能量上限溢出加成 + E4加成） */
  const memResonance: Partial<Record<CharId, number>> = {};

  /** 花火星魂等级（function 声明提升，init/zoneSnapshot 早期可调用） */
  function huahuoEidolon(): number {
    return members.find((x) => x.id === 'huahuo')?.eidolonLevel ?? 0;
  }
  /** 人造花免耗查询（defaultPolicy 闭包引用；决策时点 state 已初始化） */
  function hh2IsFree(): boolean {
    return hh2FreeSkill;
  }
  /** 幻相层数 */
  function hh2FigCount(): number {
    return hh2Figs.length;
  }
  /** 幻相合计易伤 = Σ(天赋每层% + 谜诡层额外%) */
  function hh2FigVuln(): number {
    const t = skillParams('130604', levelsOf('huahuo').talent)[1];
    const extra = skillParams('130603', levelsOf('huahuo').ult)[2];
    let s = 0;
    for (const f of hh2Figs) s += t + (f.cipher ? extra : 0);
    return s;
  }
  /** 目标是否持有【谜诡】（marker=damageBonus value0 不影响增伤和；labelKey 区分） */
  function hh2HasCipher(id: CombatUnitId): boolean {
    return !!findBuffInstance(holderOf(id), {
      key: 'damageBonus',
      source: 'huahuo',
      labelKey: 'hh2Cipher',
    });
  }
  /** 目标是否持有战技【谜诡】暴伤 buff（岁时记/夜想曲条件） */
  function hh2HoldsCd(id: CombatUnitId): boolean {
    return !!findBuffInstance(holderOf(id), { key: 'critDmg', source: 'huahuo', labelKey: 'hh2Cd' });
  }
  /** 专武 23021 彩焰：每次恢复 SP +base 层（溢出丢失的恢复也计）；满层清零刷新假面 */
  function lc21GainFlames(base: number): void {
    if (!lc21Wear || base <= 0) return;
    lc21Flames = Math.min(LC23021.flameMax, lc21Flames + base);
    if (lc21Flames >= LC23021.flameMax) {
      lc21Flames = 0;
      lc21MaskLeft = LC23021.maskTurns;
      lc21MaskSkip = true;
      syncLc21Mask();
    }
  }
  /** 专武 23021 假面队友 buff 同步（假面在→队友 critRate/critDmg permanent；不在→定点移除） */
  function syncLc21Mask(): void {
    if (!lc21Wear) return;
    for (const m of members) {
      if (m.id === lc21Wear) continue;
      const h = holderOf(m.id);
      if (lc21MaskLeft > 0) {
        addBuff(h, {
          key: 'critRate',
          source: 'lightcone',
          labelKey: 'lc21Mask',
          value: LC23021.maskCritRate,
          stacks: 1,
          duration: -1,
          tick: 'permanent',
        });
        addBuff(h, {
          key: 'critDmg',
          source: 'lightcone',
          labelKey: 'lc21Mask',
          value: LC23021.maskCritDmg,
          stacks: 1,
          duration: -1,
          tick: 'permanent',
        });
      } else {
        removeBuffInstance(h, { key: 'critRate', source: 'lightcone', labelKey: 'lc21Mask' });
        removeBuffInstance(h, { key: 'critDmg', source: 'lightcone', labelKey: 'lc21Mask' });
      }
    }
  }
  /** 花火速度同步（E1 +15% 乘区；tl.speedChange 传绝对速度） */
  function syncHuahuoSpeed(): void {
    if (!ids.has('huahuo') || !tl.has('huahuo')) return;
    tl.speedChange(
      'huahuo',
      panelOf('huahuo').speed * (hh2E1Speed ? 1 + TRACE.huahuo.eidolon1SpeedPct : 1),
    );
  }
  /** E1 速度+15%（开战/施放战技触发；覆盖刷新 2 回合、当次行动免递减） */
  function hh2GrantE1Speed(notes: string[]): void {
    if (huahuoEidolon() < 1 || !ids.has('huahuo')) return;
    if (!hh2E1Speed) {
      hh2E1Speed = true;
      syncHuahuoSpeed();
    }
    hh2E1SpeedLeft = TRACE.huahuo.eidolon1Turns;
    hh2E1SpeedSkip = true;
    notes.push('hh2E1');
  }
  /** SP 消耗逐点钩子（天赋幻相+层 / 人造花阈值计数 / 岁时记回能；actor=消费者）。
   * 火花爆点抵扣视为消耗战技点 → hhSpendSp 同样调入（用户裁定④） */
  function onSpConsumed(actor: CharId, n: number): void {
    if (n <= 0) return;
    // 米沙天赋131204：我方每消耗 1 战技点 → 下次终结技段数 +1、恢复 2 能量
    if (ids.has('misha') && !isDead('misha')) {
      mishaAddHits(n * TRACE.misha.talentHits);
      gainEnergy('misha', n * TRACE.misha.talentEnergy);
    }
    if (!ids.has('huahuo') || isDead('huahuo')) return;
    hh2TurnSpend[actor] = (hh2TurnSpend[actor] ?? 0) + n;
    if (!hh2FreeSkill && hh2TurnSpend[actor]! >= TRACE.huahuo.point07SpendThreshold) {
      hh2FreeSkill = true;
      hh2Notes.push('hh2P07');
    }
    const tal = skillParams('130604', levelsOf('huahuo').talent);
    const cipher = hh2HasCipher(actor);
    for (let i = 0; i < n && hh2Figs.length < tal[3]; i++) {
      hh2Figs.push({ cipher, left: Math.round(tal[0]), skip: true });
    }
    if (hh2Figs.length > 0) hh2Notes.push('hh2Talent');
    // 岁时记：持战技暴伤 buff 者消耗 SP → 花火 +1 能量/点（gainEnergy 内部×充能）
    if (hh2HoldsCd(actor)) gainEnergy('huahuo', TRACE.huahuo.point06SpEnergy * n);
  }
  /** 大招恢复 SP（溢出入池——仅此来源；彩焰照计） */
  function hh2UltRecoverSp(base: number): void {
    if (base <= 0) return;
    const before = sp;
    sp = Math.min(maxSp(), sp + base);
    const overflow = Math.max(0, before + base - maxSp());
    if (overflow > 0) {
      hh2Overflow = Math.min(TRACE.huahuo.overflowPoolMax, hh2Overflow + overflow);
    }
    lc21GainFlames(base);
    // Archer 1015 point08：大招恢复 SP 也算「获得战技点」
    if (sp > before) archerCheckP08();
  }
  /** 回合结束溢出池补 SP（我方成员行动后 SP<上限 → 从池扣差额补满；池内消耗也算恢复→彩焰） */
  function hh2OverflowRefill(): void {
    if (!ids.has('huahuo') || isDead('huahuo') || hh2Overflow <= 0 || sp >= maxSp()) return;
    const take = Math.min(maxSp() - sp, hh2Overflow);
    hh2Overflow -= take;
    sp += take;
    lc21GainFlames(take);
  }
  /** 挂战技暴伤 buff（hh2Cd+夜想曲抗穿同 duration 捆绑；E6 扩散复用） */
  function hh2ApplyCd(target: CharId, value: number, duration: number): void {
    const h = holderOf(target);
    addBuff(h, {
      key: 'critDmg',
      source: 'huahuo',
      labelKey: 'hh2Cd',
      value,
      stacks: 1,
      duration,
      tick: 'holderEnd',
    });
    addBuff(h, {
      key: 'resPenetration',
      source: 'huahuo',
      labelKey: 'hh2Res',
      value: TRACE.huahuo.point08ResPen,
      stacks: 1,
      duration,
      tick: 'holderEnd',
    });
  }
  /** SP 恢复中心化（专武 23021 彩焰计数含溢出；大招溢出入池走 hh2UltRecoverSp 不经此） */
  function gainSp(base: number, actor?: CharId): void {
    if (base <= 0) return;
    const before = sp;
    sp = Math.min(maxSp(), sp + base);
    const gained = sp - before;
    // 远坂凛天赋：实际恢复的每 1 点 SP → 行动者暴伤 +70%、凛 +1 宝石
    if (gained > 0 && ids.has('rin')) {
      const who = actor ?? spActor;
      if (who) rinTalentOnSp(who, gained);
      else rinGem = Math.min(TRACE.rin.talentGemCap, rinGem + gained);
    }
    lc21GainFlames(base);
    // Archer 1015 point08「守护者」：获得战技点后当前 SP ≥4 → 暴伤 +120%（1 回合）
    if (gained > 0) archerCheckP08();
  }

