  const qyE1ResApplied = new Set<MonsterId>();
  /** 千冶散落备注（record 并入下一事件——kafkaPendingNotes 同款） */
  let qyPendingNotes: string[] = [];
  /** 秘技150707「十方无赦」自身减伤剩余回合（memberDamageReduction 消费） */
  let qyTechDrTurns = 0;
  // ===== 毁灭最终批 1008 阿兰 状态 =====
  /** 阿兰：E4 免死剩余自身行动次数（进战=2；触发即清零） */
  let arlanE4Turns = 0;
  // ===== 毁灭最终批 1109 虎克 状态 =====
  /** 虎克：终结技后下一次战技强化标记（仅战技消耗；重复终结技只刷新） */
  let hookEnhancedSkill = false;
  // ===== 毁灭最终批 8001/8002 毁灭开拓者 状态 =====
  /** 天赋【牵制盗垒】层数（任意我方击破/E6 击杀叠层，上限 2、永久） */
  const tbdTalentStacks = new Map<CharId, number>();
  /** E1 本次终结技是否已回能（每次终结技最多 1 次） */
  const tbdE1Given = new Set<CharId>();
  // ===== 毁灭最终批 1213 丹恒•饮月 状态 =====
  /** 【亢心】层数（每段攻击后 +1；上限 6，E1 上限 10 且每段额外 +1） */
  let dnTalentStacks = 0;
  /** 【叱咤】层数（暴伤 +12%/层，上限 4） */
  let dnChichaStacks = 0;
  /** E4：叱咤是否已延长到下一自身回合结束 */
  let dnChichaCarry = false;
  /** 【逆鳞】层数（上限 3，可抵扣战技点） */
  let dnScales = 0;
  /** E6：下一次盘拏耀跃的虚数抗性穿透层数（上限 3） */
  let dnE6Stacks = 0;
  /** E2：终结技后待结算的 100% 行动提前（等本次行动 finishAction 后再拉，避免被重置） */
  let dnE2Advance = false;
  /** EX星魂开关与全队累计战技点消耗（满 5 触发，余数保留） */
  let dnExOn = false;
  let dnExSpent = 0;
  // ===== 毁灭最终批 1408 白厄 状态（完整变身裁定） =====
  /** 【火种】独立资源（0~12 激活，可溢出；energy 仅展示映射） */
  let phainonSeed = 0;
  /** 是否处于卡厄斯兰那变身 */
  let phainonForm = false;
  /** 【毁伤】点数（变身开始时 +4，上限 7） */
  let phainonDamage = 0;
  /** 剩余额外回合数（8 起；最后 1 个开始时打最后一击） */
  let phainonExtraLeft = 0;
  /** 【弑魂之炽】层数（140809 获得；反击后清空） */
  let phainonSoulfire = 0;
  /** 本次 140809 需要等待的敌方行动数 / 已结算数 */
  let phainonSoulfireExpected = 0;
  let phainonSoulfireSeen = 0;
  /** 140805 致命抵抗（每次变身仅 1 次） */
  let phainonFatalUsed = false;
  /** 致命触发后待执行的最后一击（在主循环顶部结算） */
  let phainonFatalPending = false;
  /** point08 攻击 +50% 层数（入战/变身结束，最多 2） */
  let phainonP08Stacks = 0;
  /** point07 单回合触发限制（记录最近触发轮次） */
  let phainonP07Turn = -1;
  /** E1 击杀数（每击杀 +1.5% 额外回合速度，上限 84%） */
  let phainonKillCount = 0;
  /** 变身期间离场单位的 av/order/speed 快照 */
  const phainonSavedUnits = new Map<CharId, { av: number; order: number; speed: number }>();
  /** 变身期间敌方弱点快照（结束后恢复） */
  const phainonSavedWeak = new Map<MonsterId, Set<Element>>();
  /** 【永续的燃烧】是否已由昔涟忆灵技 1141521「献予「负世」之诗」授予（整场，变身时生效） */
  let phainonBurn = false;
  /** 1141521 lv 实读参数：[0]暴击率 [1]每回合耗当前生命% [2]附伤次数 [3]每次附伤攻击力%
   *  [4]火种阈值 [5]每超出1点暴伤% [6]暴伤上限 [7]施放时火种 [8]刷新时毁伤 */
  let phainonBurnP: number[] = [];
  // ===== 毁灭第一批 1205 刃 / 1212 镜流 / 1404 万敌 状态 =====
  /** 刃：累计损失生命（以当前生命上限的 90% 封顶；终结技后清 50%） */
  let bladeLostHp = 0;
  /** 刃：【充能】层数（实际损失生命+1；上限 5，E6=4） */
  let bladeCharge = 0;
  /** 刃：充能满层待触发天赋追击 */
  let bladeFollowupPending = false;
  /** 刃：E4 已叠加的生命上限次数（最多 2） */
  let bladeE4Stacks = 0;
  /** 刃：战技后待立即行动（地狱变额外回合） */
  let bladeExtraPending = false;
  /** 刃：敌方单次攻击内的掉血去重（attackKey|target） */
  const bladeLossSeen = new Set<string>();
  /** 镜流：【朔望】层数 */
  let jingliuSyzygy = 0;
  /** 镜流：是否处于【转魄】 */
  let jingliuInTranscend = false;
  /** 镜流：【月色】层数 */
  let jingliuMoon = 0;
  /** 镜流：损失生命计数（满 20 层 +1 朔望） */
  let jingliuHpLossCount = 0;
  /** 镜流：point08 下一次攻击无视 25% 防御 */
  let jingliuP08Pending = false;
  /** 镜流：E2 下一次强化战技 +80% 伤害 */
  let jingliuE2Pending = false;
  /** 镜流：月色/20 次计数的 attackKey|target 去重 */
  const jingliuMoonSeen = new Set<string>();
  const jingliuCountSeen = new Set<string>();
  /** 万敌：【充能】点数（0~200） */
  let mydeiCharge = 0;
  /** 万敌：血仇状态 */
  let mydeiBloodFeud = false;
  /** 万敌：point06 已消耗的免死次数（前 3 次不退血仇，第 4 次退出） */
  let mydeiFatalUsed = 0;
  /** 万敌：血仇满充能待立即行动 */
  let mydeiExtraTurnPending = false;
  /** 万敌：本次立即行动是否施放弑神登神 */
  let mydeiGodExtraReady = false;
  /** 万敌：弑神登神优先主目标 */
  let mydeiGodTarget: MonsterId | undefined;
  /** 万敌：point08 由开局生命上限换算的暴率/充能/受疗加成 */
  let mydeiP08Crit = 0;
  let mydeiP08ChargeMult = 0;
  let mydeiP08Heal = 0;
  /** 万敌：E2 本次行动已由治疗转化的充能点数（上限 40） */
  let mydeiHealChargeUsed = 0;
  /** 万敌：弑神登神期间不获得充能 */
  let mydeiNoCharge = false;
  /** 献予「纷争」之诗（1141516）：本次【弑神登神】的暴伤加成（用完清零） */
  let mydeiPoemGodCritDmg = 0;
  /** Saber：炉心共鸣层数 / 溢出能量 / 强制强化普攻 / 魔力放出 / P08 层数 / 终结技计数 */
  let saberResonance = 0;
  let saberOverflow = 0;
  let saberForcedEnhanced = false;
  let saberManaRelease = false;
  let saberP08Stacks = 0;
  let saberUltCount = 0;
  let saberExtraPending = false;
  let saberP06Extra = false;
  let saberE2DefStacks = 0;
  let saberJointUltReady = false;
  /** 吉尔伽美什：兴致 / 累计兴致 / 来兴致了 / 初始普攻 / 连携计数 / 黄金律 */
  let gilgameshZing = 0;
  let gilgameshZingTotal = 0;
  let gilgameshInMood = false;
  let gilgameshAutoBasicUsed = false;
  let gilgameshJointCount = 0;
  let gilgameshE6Golden = 0;
  let gilgameshSpeedMult = 1;
  /** 米沙：下一次终结技段数 / E6 增伤 */
  let mishaUltHits: number = TRACE.misha.ultBaseHits;
  let mishaE6Buff = false;
  /** 毁灭三人散落备注（record 并入下一事件） */
  let warriorPendingNotes: string[] = [];
  let fireflyCombustion = false;
  let fireflyE2Used = false;
  let fireflyExtraPending = false;
  let fireflySkillAdvancePending = false;
  let fireflyP06Used = 0;
  const fireflyWeaknessTurns = new Map<MonsterId, number>();
  const fireflyAddedWeak = new Set<MonsterId>();

  const fireflyEidolon = (): number =>
    members.find((m) => m.id === 'firefly')?.eidolonLevel ?? 0;

  const fireflyAttackNow = (): number => {
    const p = panelOf('firefly');
    const h = holderOf('firefly');
    // 2026-11-06 用户裁定（录像反算）：γ模组-过载核心 的攻击力快照**不计同袍（丹恒 traceShenXiu）flat**。
    // 录像：γ=126.4% ⇔ (入战面板 3901 − 同袍 521 − 1800) × 0.0008；同袍一旦计入会虚高约 45.6pp 击破特攻。
    const tongpaoFlat = h.buffs.reduce(
      (s, b) => (b.key === 'atkFlat' && b.labelKey === 'traceShenXiu' ? s + b.value * b.stacks : s),
      0,
    );
    return (
      // 2026-11-07 裁定 A：攻击% 只乘基础攻击力（未填 baseAttack 时保持旧口径）
      usesBaseAtk('firefly')
        ? p.attack + baseAtkOf('firefly') * buffSum(h.buffs, 'atkPct') + buffSum(h.buffs, 'atkFlat') - tongpaoFlat
        : (p.attack + buffSum(h.buffs, 'atkFlat') - tongpaoFlat) * (1 + buffSum(h.buffs, 'atkPct'))
    );
  };

  const fireflyRefreshP08 = (): void => {
    if (!ids.has('firefly') || isDead('firefly')) return;
    const h = holderOf('firefly');
    removeBuffInstance(h, { key: 'breakEffect', source: 'firefly', labelKey: 'fireflyP08' });
    const steps = Math.floor((fireflyAttackNow() - TRACE.firefly.p08Atk) / TRACE.firefly.p08Step);
    const extra = Math.max(0, steps) * TRACE.firefly.p08Be;
    if (extra <= 0) return;
    addBuff(h, {
      key: 'breakEffect',
      value: extra,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'firefly',
      labelKey: 'fireflyP08',
    });
  };

  const fireflyBreakEffectNow = (): number =>
    panelOf('firefly').breakEffect + buffSum(holderOf('firefly').buffs, 'breakEffect');

  /**
   * 大丽花行迹 point08「弃旧，恋新」：**我方目标为敌方目标添加弱点时**，该目标速度 +30%，持续 2 回合。
   * 2026-11-07 用户裁定：必须走 `tl.speedChange`（真实速度），`speedPct` 不推进时间轴。
   */
  const qiJiuTurns = new Map<CombatUnitId, number>();
  const dahliaQiJiuSpeed = (unit: CombatUnitId): void => {
    if (!ids.has('dahlia') || !tl.has(unit)) return;
    if ((qiJiuTurns.get(unit) ?? 0) <= 0) {
      tl.speedChange(unit, tl.getUnit(unit).speed * (1 + TRACE.dahlia.point08SpeedPct));
    }
    qiJiuTurns.set(unit, TRACE.dahlia.point08SpeedTurns);
  };
  /** 持有者常规行动结束递减；到期除回还原 */
  const qiJiuSpeedTick = (unit: CombatUnitId): void => {
    const left = qiJiuTurns.get(unit) ?? 0;
    if (left <= 0) return;
    if (left <= 1) {
      qiJiuTurns.set(unit, 0);
      if (tl.has(unit)) {
        tl.speedChange(unit, tl.getUnit(unit).speed / (1 + TRACE.dahlia.point08SpeedPct));
      }
      return;
    }
    qiJiuTurns.set(unit, left - 1);
  };

  const fireflyAddWeakness = (target: MonsterId, turns: number = TRACE.firefly.weaknessTurns): void => {
    const mon = monsters[target];
    if (!mon || mon.hp <= 0) return;
    if (mon.weaknesses.has('Fire')) {
      if (fireflyAddedWeak.has(target)) fireflyWeaknessTurns.set(target, turns);
      return;
    }
    mon.weaknesses.add('Fire');
    fireflyAddedWeak.add(target);
    fireflyWeaknessTurns.set(target, turns);
  };

  const fireflyTickWeakness = (target: MonsterId): void => {
    const left = fireflyWeaknessTurns.get(target);
    if (left === undefined) return;
    if (left > 1) {
      fireflyWeaknessTurns.set(target, left - 1);
      return;
    }
    fireflyWeaknessTurns.delete(target);
    if (fireflyAddedWeak.delete(target)) monsters[target].weaknesses.delete('Fire');
  };

  const fireflyCleanse = (): void => {
    if (!ids.has('firefly') || isDead('firefly')) return;
    let cleaned = false;
    for (const map of [
      memberFreeze,
      memberDrunk,
      memberImprison,
      memberEntangle,
      fearPending,
      memberDevour,
    ]) {
      if (map.delete('firefly')) cleaned = true;
    }
    if (memberIllusion.delete('firefly')) cleaned = true;
    if (cleaned) warriorPendingNotes.push('fireflyCleanse');
  };

  const fireflyExitCombustion = (removeCountdown = true): void => {
    if (fireflyCombustion) {
      fireflyCombustion = false;
      const h = holderOf('firefly');
      removeBuffInstance(h, { key: 'effectRes', source: 'firefly', labelKey: 'fireflyCombustionRes' });
      removeBuffInstance(h, { key: 'breakEffect', source: 'firefly', labelKey: 'fireflyP06' });
      if (tl.has('firefly')) {
        const speed = Math.max(1, tl.getUnit('firefly').speed - TRACE.firefly.ultSpeed);
        tl.speedChange('firefly', speed);
      }
    }
    if (removeCountdown && tl.has('fireflyCountdown')) tl.removeUnit('fireflyCountdown');
  };

  const fireflyEnterCombustion = (): void => {
    if (fireflyCombustion || !ids.has('firefly') || isDead('firefly')) return;
    fireflyCombustion = true;
    fireflyP06Used = 0;
    const h = holderOf('firefly');
    const er = TRACE.firefly.talentErr + (fireflyEidolon() >= 4 ? TRACE.firefly.e4Err : 0);
    addBuff(h, {
      key: 'effectRes',
      value: er,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'firefly',
      labelKey: 'fireflyCombustionRes',
    });
    addBuff(h, {
      key: 'breakEffect',
      value: TRACE.firefly.p06Be,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'firefly',
      labelKey: 'fireflyP06',
    });
    tl.speedChange('firefly', tl.getUnit('firefly').speed + TRACE.firefly.ultSpeed);
    if (!tl.has('fireflyCountdown')) {
      tl.addUnit({
        id: 'fireflyCountdown',
        side: 'ally',
        speed: TRACE.firefly.countdownSpeed,
        order: nextOrder++,
      });
    }
    fireflyRefreshP08();
  };

  const fireflyTryE2 = (): void => {
    if (fireflyEidolon() < 2) return;
    if (!fireflyCombustion || fireflyE2Used || isDead('firefly')) return;
    fireflyE2Used = true;
    fireflyExtraPending = true;
    warriorPendingNotes.push('fireflyE2');
  };

  const fireflyAttack = (
    target: MonsterId,
    multiplier: number,
    stance: number,
    skillCode: string,
    attackKind: 'basic' | 'skill',
    extras?: { defIgnore?: number; resPenetration?: number },
  ): number[] => {
    const p = panelOf('firefly');
    const burning = fireflyCombustion;
    if (burning) {
      addBuff(attackerHolder('firefly'), {
        key: 'breakEfficiency',
        value:
          TRACE.firefly.ultBreakEff +
          (fireflyEidolon() >= 6 ? TRACE.firefly.e6BreakEff : 0),
        stacks: 1,
        duration: 1,
        tick: 'holderEnd',
        source: 'firefly',
        labelKey: 'fireflyUltBreakEff',
      });
      addBuff(monsters[target].buffs, {
        key: 'breakVulnerability',
        value: TRACE.firefly.ultBreakDmg,
        stacks: 1,
        duration: 1,
        tick: 'holderEnd',
        source: 'firefly',
        labelKey: 'fireflyUltBreakVuln',
      });
    }
    const zoneExtras: { defIgnore?: number; resPenetration?: number } = { ...extras };
    if (burning && fireflyEidolon() >= 6) {
      zoneExtras.resPenetration =
        (zoneExtras.resPenetration ?? 0) + TRACE.firefly.e6ResPen;
    }
    const seqs = dealAttack({
      source: 'firefly',
      skillCode,
      element: 'Fire',
      level: p.level,
      statValue: p.attack,
      multiplier,
      damageBonusExtra: 0,
      critRate: p.critRate,
      critDmg: p.critDmg,
      stance,
      attackerBuffs: attackerHolder('firefly'),
      target,
      attackKind,
      ...(Object.keys(zoneExtras).length > 0 ? { zoneExtras } : {}),
    });
    if (burning) {
      removeBuffInstance(attackerHolder('firefly'), {
        key: 'breakEfficiency',
        source: 'firefly',
        labelKey: 'fireflyUltBreakEff',
      });
      removeBuffInstance(monsters[target].buffs, {
        key: 'breakVulnerability',
        source: 'firefly',
        labelKey: 'fireflyUltBreakVuln',
      });
    }
    return seqs;
  };

  const fireflySuperBreakSeqs = (
    spec: AttackSpec,
    target: MonsterId,
    postToughPortion: number,
  ): number[] => {
    if (
      postToughPortion <= 0 ||
      !fireflyCombustion ||
      spec.stance <= 0 ||
      (spec.attackKind !== 'basic' && spec.attackKind !== 'skill') ||
      !spec.skillCode.startsWith('firefly.enhanced') ||
      ownerOfUnit(spec.panelSource ?? spec.source) !== 'firefly'
    ) {
      return [];
    }
    const mon = monsters[target];
    if (!mon || mon.hp <= 0) return [];
    const be = fireflyBreakEffectNow();
    const ratio =
      be >= TRACE.firefly.p07Threshold2
        ? TRACE.firefly.p07Ratio2
        : be >= TRACE.firefly.p07Threshold1
          ? TRACE.firefly.p07Ratio1
          : 0;
    if (ratio <= 0) return [];
    const p = panelOf('firefly');
    const sb = computeSuperBreak({
      breakBase: BREAK_BASE_LEVEL_80,
      breakEffect: be,
      skillToughnessPoints: postToughPortion * ratio,
      toughnessBoost: 0,
      weaknessBreakEfficiency: buffSum(spec.attackerBuffs.buffs, 'breakEfficiency'),
      superBreakBonus: 0,
      breakDmgBoost: buffSum(spec.attackerBuffs.buffs, 'breakDmgBoost'),
      breakVuln: buffSum(mon.buffs, 'breakVulnerability'),
      common: {
        ...zoneSnapshot('Fire', p.level, 'firefly', target),
        toughness: 'broken' as const,
      },
    });
    return [
      pushHit(
        sb,
        { source: 'firefly', skillCode: `${spec.skillCode}.sb`, note: 'fireflyP07', target },
        'superBreak',
      ),
    ];
  };

  const fireflyTechSeqs = (notes: string[]): number[] => {
    const seqs: number[] = [];
    if (!ids.has('firefly') || isDead('firefly')) return seqs;
    const p = panelOf('firefly');
    const tp = skillParams('131007', 1);
    for (const target of aliveMonsters()) {
      fireflyAddWeakness(target, Math.round(tp[2]));
      dahliaQiJiuSpeed('firefly'); // 弃旧恋新：流萤战技加弱点
      seqs.push(
        ...dealAttack({
          source: 'firefly',
          skillCode: 'firefly.tech',
          element: 'Fire',
          level: p.level,
          statValue: p.attack,
          multiplier: tp[1],
          damageBonusExtra: 0,
          critRate: p.critRate,
          critDmg: p.critDmg,
          stance: stanceOf('131007', 1),
          attackerBuffs: attackerHolder('firefly'),
          target,
          attackKind: 'skill',
        }),
      );
    }
    notes.push('fireflyTech');
    return seqs;
  };

  // ===== 雪衣 1214 =====
  let xueyiMarks = 0;
  let xueyiOverflow = 0;
  let xueyiFollowupPending = false;
  let xueyiFollowupRunning = false;
  const xueyiEidolon = (): number =>
    members.find((m) => m.id === 'xueyi')?.eidolonLevel ?? 0;
  const xueyiMarkCap = (): number => (xueyiEidolon() >= 6 ? 6 : 8);
  const xueyiDamageBonus = (): number =>
    Math.min(2.4, panelOf('xueyi').breakEffect + buffSum(holderOf('xueyi').buffs, 'breakEffect'));

  const xueyiOnToughness = (spec: AttackSpec, actual: number): void => {
    if (!ids.has('xueyi') || xueyiFollowupRunning || actual <= 0 || isDead('xueyi')) return;
    const owner = ownerOfUnit(spec.panelSource ?? spec.source);
    const gain = owner === 'xueyi' ? Math.floor(actual / 10) : 1;
    if (gain <= 0) return;
    const cap = xueyiMarkCap();
    const total = xueyiMarks + gain;
    xueyiMarks = Math.min(cap, total);
    if (total > cap) xueyiOverflow = Math.min(6, xueyiOverflow + total - cap);
    if (xueyiMarks >= cap) {
      xueyiFollowupPending = true;
      warriorPendingNotes.push('xueyiMarkFull');
    }
  };

  const xueyiFlushFollowup = (): void => {
    if (!ids.has('xueyi') || !xueyiFollowupPending || xueyiFollowupRunning || isDead('xueyi')) return;
    if (aliveMonsters().length === 0) return;
    xueyiFollowupPending = false;
    xueyiFollowupRunning = true;
    const cap = xueyiMarkCap();
    const carry = xueyiOverflow;
    xueyiMarks = 0;
    xueyiOverflow = 0;
    const p = panelOf('xueyi');
    const seqs: number[] = [];
    const mult = 0.9 * (xueyiEidolon() >= 1 ? 1.4 : 1);
    const ignore = xueyiEidolon() >= 2;
    for (let i = 0; i < 3; i += 1) {
      const pool = aliveMonsters();
      if (pool.length === 0) break;
      const target = pool[Math.min(pool.length - 1, Math.floor(rand01() * pool.length))];
      seqs.push(
        ...dealAttack({
          source: 'xueyi',
          skillCode: 'xueyi.talent',
          element: 'Quantum',
          level: p.level,
          statValue: p.attack,
          multiplier: mult,
          damageBonusExtra: xueyiDamageBonus(),
          critRate: p.critRate,
          critDmg: p.critDmg,
          stance: 15,
          attackerBuffs: attackerHolder('xueyi'),
          target,
          attackKind: 'followup',
          ignoreWeakness: ignore,
          stanceNoWeaknessMult: ignore ? undefined : 0,
        }),
      );
    }
    xueyiFollowupRunning = false;
    xueyiMarks = Math.min(cap, carry);
    xueyiOverflow = 0;
    const note = ['xueyiTalent'];
    if (ignore) {
      healUnit('xueyi', maxHpOf('xueyi') * 0.05, 'xueyi', note);
      note.push('xueyiE2');
    }
    record({
      time: tl.time,
      round: tl.round,
      kind: 'action',
      unitId: 'xueyi',
      action: 'talent',
      skillCode: 'xueyi.talent',
      spAfter: sp,
      energyAfter: energyAfterOf('xueyi'),
      note,
      hitSeqs: seqs,
      targetId: resolveMain(),
    });
  };

  // ===== 云璃 1221 =====
  let yunliParry = false;
  let yunliParrySkip = false;
  let yunliParryCrit = false;
  let yunliSlashNext = false;
  const yunliEidolon = (): number =>
    members.find((m) => m.id === 'yunli')?.eidolonLevel ?? 0;

  const yunliEndParry = (): void => {
    if (!yunliParry) return;
    yunliParry = false;
    yunliParryCrit = false;
    removeBuffInstance(holderOf('yunli'), { key: 'taunt', source: 'yunli', labelKey: 'yunliParryTaunt' });
    removeBuffInstance(holderOf('yunli'), { key: 'effectRes', source: 'yunli', labelKey: 'yunliP07' });
  };

  const yunliAttack = (
    mode: 'talent' | 'slash' | 'annihilation',
    attacker?: string,
    extraBonus = 0,
  ): number[] => {
    if (!ids.has('yunli') || isDead('yunli') || aliveMonsters().length === 0) return [];
    const p = panelOf('yunli');
    const lv = levelsOf('yunli');
    const talent = skillParams('122104', lv.talent);
    const ultP = skillParams('122103', lv.ult);
    const eid = yunliEidolon();
    const isUlt = mode !== 'talent';
    const mainMultBase = isUlt ? 2.2 : talent[0];
    const adjMultBase = isUlt ? 1.1 : talent[1];
    const e1 = isUlt && eid >= 1 ? 0.2 : 0;
    const bonusScale = 1 + (isUlt ? extraBonus : 0);
    const mainMult = mainMultBase * (1 + e1) * bonusScale;
    const adjMult = adjMultBase * (1 + e1) * bonusScale;
    const attackerMon =
      attacker && isMonsterId(attacker as CombatUnitId)
        ? (attacker as MonsterId)
        : resolveMain();
    const main = monsters[attackerMon] && monsters[attackerMon].hp > 0 ? attackerMon : resolveMain();
    const adj = resolveAdjacent(main);
    const skillCode =
      mode === 'talent'
        ? 'yunli.talent'
        : mode === 'slash'
          ? 'yunli.ultSlash'
          : 'yunli.ultAnnihilation';
    const note =
      mode === 'talent'
        ? ['yunliTalent']
        : mode === 'slash'
          ? ['yunliSlash']
          : ['yunliAnnihilation'];
    const p08 = 0.3;
    addBuff(holderOf('yunli'), {
      key: 'atkPct',
      value: p08,
      stacks: 1,
      duration: 1,
      tick: 'holderEnd',
      source: 'yunli',
      labelKey: 'yunliP08',
    });
    const critRate = p.critRate + (isUlt && eid >= 6 ? 0.15 : 0);
    const critDmg = p.critDmg + (yunliParryCrit ? 1 : 0);
    const zoneExtras: { defIgnore?: number; resPenetration?: number } = {};
    if (eid >= 2) zoneExtras.defIgnore = 0.2;
    if (isUlt && eid >= 6) zoneExtras.resPenetration = 0.2;
    const seqs: number[] = [];
    const hit = (target: MonsterId, mult: number, stance: number): number[] =>
      dealAttack({
        source: 'yunli',
        skillCode,
        element: 'Physical',
        level: p.level,
        statValue: p.attack,
        multiplier: mult,
        damageBonusExtra: 0,
        critRate,
        critDmg,
        stance,
        attackerBuffs: attackerHolder('yunli'),
        target,
        attackKind: 'followup',
        ...(Object.keys(zoneExtras).length > 0 ? { zoneExtras } : {}),
      });
    seqs.push(...hit(main, mainMult, 60));
    for (const target of adj) seqs.push(...hit(target, adjMult, 30));
    if (mode === 'annihilation') {
      const extraHits = 6 + (eid >= 1 ? 3 : 0);
      for (let i = 0; i < extraHits; i += 1) {
        const pool = aliveMonsters();
        if (pool.length === 0) break;
        const target = pool[Math.min(pool.length - 1, Math.floor(rand01() * pool.length))];
        seqs.push(...hit(target, ultP[6] * (1 + e1) * bonusScale, 0));
      }
    }
    yunliParryCrit = false;
    if (mode === 'slash') yunliSlashNext = true;
    if (isUlt && eid >= 4) {
      addBuff(holderOf('yunli'), {
        key: 'effectRes',
        value: 0.5,
        stacks: 1,
        duration: 1,
        tick: 'holderEnd',
        source: 'yunli',
        labelKey: 'yunliE4',
      });
      note.push('yunliE4');
    }
    record({
      time: tl.time,
      round: tl.round,
      kind: 'action',
      unitId: 'yunli',
      action: 'talent',
      skillCode,
      spAfter: sp,
      energyAfter: energyAfterOf('yunli'),
      note,
      hitSeqs: seqs,
      targetId: main,
    });
    return seqs;
  };

  const yunliOnActionEnd = (): void => {
    if (!ids.has('yunli') || !yunliParry) return;
    if (yunliParrySkip) {
      yunliParrySkip = false;
      return;
    }
    if (aliveMonsters().length === 0) {
      yunliEndParry();
      return;
    }
    const slash = yunliSlashNext ? 'annihilation' : 'slash';
    const keepCrit = yunliParryCrit;
    yunliSlashNext = false;
    yunliEndParry();
    yunliParryCrit = keepCrit;
    yunliAttack(slash);
    yunliParryCrit = false;
  };

  const yunliOnEnemyAttack = (hits: { targetId: string }[], attacker: string): void => {
    if (!ids.has('yunli') || isDead('yunli') || hits.length === 0) return;
    const hitYunli = hits.some((h) => h.targetId === 'yunli');
    if (yunliParry) {
      const e6Any = yunliEidolon() >= 6;
      if (hitYunli || e6Any) {
        const keepCrit = yunliParryCrit;
        yunliEndParry();
        yunliParryCrit = keepCrit;
        yunliAttack('annihilation', attacker);
        yunliParryCrit = false;
      }
      return;
    }
    if (hitYunli) {
      gainEnergy('yunli', 15);
      yunliAttack('talent', attacker);
    }
  };

  // ===== 克拉拉 1107 =====
  let claraEnhancedCounters = 0;
  let claraE4Active = false;
  const claraMarks = new Set<MonsterId>();
  const claraEidolon = (): number =>
    members.find((m) => m.id === 'clara')?.eidolonLevel ?? 0;

  const claraCleanseOne = (): boolean => {
    for (const map of [memberFreeze, memberDrunk, memberImprison, memberEntangle, fearPending, memberDevour]) {
      if (map.delete('clara')) return true;
    }
    return memberIllusion.delete('clara');
  };

  const claraAttack = (mode: 'talent' | 'enhanced' | 'skill', attacker?: string): number[] => {
    if (!ids.has('clara') || isDead('clara') || aliveMonsters().length === 0) return [];
    const p = panelOf('clara');
    const attackerMon =
      attacker && isMonsterId(attacker as CombatUnitId)
        ? (attacker as MonsterId)
        : resolveMain();
    const main = monsters[attackerMon] && monsters[attackerMon].hp > 0 ? attackerMon : resolveMain();
    const adj = mode === 'enhanced' ? resolveAdjacent(main) : [];
    const mult = mode === 'enhanced' ? 4.16 : 1.6;
    const skillCode = mode === 'enhanced' ? 'clara.ultCounter' : 'clara.talent';
    const note = mode === 'enhanced' ? ['claraUltCounter'] : ['claraTalent'];
    const p08 = 0.3;
    const seqs: number[] = [];
    const hit = (target: MonsterId, m: number, stance: number): number[] =>
      dealAttack({
        source: 'clara',
        skillCode,
        element: 'Physical',
        level: p.level,
        statValue: p.attack,
        multiplier: m,
        damageBonusExtra: p08,
        critRate: p.critRate,
        critDmg: p.critDmg,
        stance,
        attackerBuffs: attackerHolder('clara'),
        target,
        attackKind: 'followup',
      });
    seqs.push(...hit(main, mult, 30));
    for (const target of adj) seqs.push(...hit(target, mult * 0.5, 0));
    if (mode !== 'skill' && isMonsterId(attacker as CombatUnitId)) {
      claraMarks.add(attacker as MonsterId);
    }
    record({
      time: tl.time,
      round: tl.round,
      kind: 'action',
      unitId: 'clara',
      action: 'talent',
      skillCode,
      spAfter: sp,
      energyAfter: energyAfterOf('clara'),
      note,
      hitSeqs: seqs,
      targetId: main,
    });
    return seqs;
  };

  const claraOnEnemyAttack = (hits: { targetId: string }[], attacker: string): void => {
    if (!ids.has('clara') || isDead('clara') || hits.length === 0) return;
    const hitClara = hits.some((h) => h.targetId === 'clara');
    const hitOther = hits.some((h) => h.targetId !== 'clara');
    if (hitClara) {
      claraE4Active = claraEidolon() >= 4;
      const chance = 0.35;
      if (rand01() < chance && claraCleanseOne()) warriorPendingNotes.push('claraP06');
    }
    if (claraEnhancedCounters > 0 && (hitClara || hitOther)) {
      claraEnhancedCounters -= 1;
      claraAttack('enhanced', attacker);
      return;
    }
    if (hitClara) {
      claraAttack('talent', attacker);
      return;
    }
    if (claraEidolon() >= 6 && hitOther && rand01() < 0.5) {
      claraAttack('talent', attacker);
      warriorPendingNotes.push('claraE6');
    }
  };

  /** 我方全属性抗性（2026-10-29 光锥 21002 接入：抗性区 = 1 − Σ resAll；敌方伤害通道消费） */
  const memberResistance = (id: CharId): number =>
    Math.min(1, Math.max(0, buffSum(holderOf(id).buffs, 'resAll')));

  const memberDamageReduction = (id: CharId, attackerMon?: string): number => {
    let dr = panelOf(id).damageReduction ?? 0;
    // 2026-10-29：通用「受到伤害降低」buff（光锥21009/21023 等）——此前只有克拉拉单独求和
    dr += buffSum(holderOf(id).buffs, 'dmgReduction');
    // 光锥 24002「记忆的质料」：装备者持有护盾时，自身受到的伤害降低 #5（>0 守卫＝未装备不生效）
    const lp24002 = lc24002Params.get(id);
    if (lp24002 && (shieldValues[id] ?? 0) > 0) dr += lp24002[4] ?? 0;
    // 真珠 1503 天赋150304 #4：我方目标当前 HP% ≤ #1=50% → 受到的伤害降低 #4=30%    // （2026-11-02 用户裁定：**全队**所有 ≤50% 血的成员都享受，阈值用**受击前** HP% 判定）
    if (ids.has('zhenzhu') && !isDead(id)) {
      const zMax = Math.max(1, maxHpOf(id));
      dr += zhenzhuLowHpDr((memberHp[id] ?? zMax) / zMax, skillParams('150304', levelsOf('zhenzhu').talent));
    }
    // 绘世【忍耐】（5014030，2026-11-02 用户裁定）：选择忍耐后受到的伤害降低（数值占位 30%）
    if ((memberEndureTurns.get(id) ?? 0) > 0) dr += EMBER_ENDURE_DR;
    if (id === 'firefly' && !isDead('firefly')) {
      if (fireflyCombustion) {
        dr += TRACE.firefly.talentMaxDr;
      } else {
        const maxHp = Math.max(1, maxHpOf('firefly'));
        const hpPct = Math.min(1, Math.max(0, (memberHp.firefly ?? maxHp) / maxHp));
        dr +=
          TRACE.firefly.talentMaxDr *
          Math.min(1, Math.max(0, (1 - hpPct) / (1 - TRACE.firefly.talentLowHp)));
      }
    }
    if (id === 'clara' && !isDead('clara')) {
      dr += 0.1;
      if (claraE4Active) dr += 0.3;
    }
    if (id === 'yunli' && !isDead('yunli') && yunliParry) dr += 0.2;
    // 千冶 1507 秘技150707：自身受到的伤害降低 #1%（2 回合）
    if (id === 'qianye' && !isDead('qianye') && qyTechDrTurns > 0) dr += TRACE.qianye.techDr;
    // 波提欧 1315【绝命对峙】：受对峙目标伤害 +15%（E4 再压低 12%）；受**非**对峙目标伤害 point07 −30%
    if (id === 'boothill' && !isDead('boothill') && boothillInStandoff()) {
      const fromStandoff = attackerMon !== undefined && attackerMon === boothillStandoff;
      if (fromStandoff) {
        dr -= TRACE.boothill.standoffSelfDmgUp;
        if (boothillEidolon() >= 4) dr += TRACE.boothill.e4SelfDr;
      } else if (attackerMon !== undefined) {
        dr += TRACE.boothill.p07NonStandoffDr;
      }
    }
    // 素裳 E2：触发【剑势】后受到的伤害降低 20%（1 回合）
    if (id === 'sushang' && !isDead('sushang') && sushangE2Turns > 0) {
      dr += TRACE.sushang.e2DmgReduction;
    }
    if (id === 'phainon' && phainonForm && phainonSoulfire > 0) dr += TRACE.phainon.soulDr;
    // 存护开拓者：战技自身 −50%（1 回合）、行迹 point06「强援弱」全队 −15%（1 回合）
    if (TK_IDS.includes(id)) {
      if (tbkSelfDrTurns > 0) dr += 0.5;
      if (tbkP06Turns > 0) dr += 0.15;
    }
    // 符玄天赋【避厄】：符玄处于可战斗状态时，我方全体受到伤害降低 #1=18%（2026-10-28 裁定）
    if (ids.has('fuxuan') && !isDead('fuxuan')) {
      dr += skillParams('120804', levelsOf('fuxuan').talent)[0] ?? 0;
    }
    return Math.min(1, dr);
  };
  // ===== 瓦尔特 1004 状态（2026-10 接入；裁定见 TRACE.welt 注释；虚数输出） =====
  /** E1：终招后剩余普攻/战技附加段次数（终招施放后置入） */
  let weltE1Charges = 0;
  /** 瓦尔特散落备注（记录并入下一事件——weltSlow/weltE1 附加伤害触发标记等） */
  let weltPendingNotes: string[] = [];
  // ===== 佩拉 1106 状态（2026-10 接入；裁定见 TRACE.pela 注释；冰输出） =====
  /** E4 冰抗降低倒计时（怪 id→剩余回合递减；到点还原 resistance） */
  const pelaIceRed = {} as Record<MonsterId, number>;
  /** 佩拉散落备注（pelaDataCollect/pelaE6 触发标记并入下一事件） */
  let pelaPendingNotes: string[] = [];
  /** E2 速度 buff 剩余持有者回合（进轴乘法，到期除以 1+10%） */
  const pelaE2SpeedLeft = new Map<CharId, number>();
  /** point08 追歼：下一次攻击 +20% 是否已挂（攻击动作结束时消费） */
  let pelaP08Pending = false;
  // ===== 桑博 1108 状态（2026-10 接入；裁定见 TRACE.sampo 注释；风化=怪侧 skillDot 原生 stacks） =====
  /** 桑博散落备注（spWind/spE4 标记并入下一事件） */
  let sampoPendingNotes: string[] = [];
  // ===== 卢卡 1111 状态（2026-10 接入；裁定见 TRACE.luka 注释；裂伤=怪侧 skillDot hpBased） =====
  /** 【斗志】层数（战斗开始1；普攻/普攻后+1≤4；终招+2；强化普攻消耗2；获层时 R4 攻入+point07 回能） */
  let lukaSpirit = 0;
  /** 卢卡散落备注（lkSpirit/R1/R6 标记并入下一事件） */
  let lkPendingNotes: string[] = [];
  /** 获增强普攻段数（R6：本次强化普攻直冲累计段数，碎天命中时按段数额外爆发） */
  let lukaStraightSegments = 0;
  // ===== 桂乃芬 1210 状态（2026-10 接入；裁定见 TRACE.guinaifen 注释；灼烧=怪侧 skillDot 原生、吞火=怪侧 vuln buff） =====
  /** 桂乃芬散落备注（gnTom 吞火 / gnBurn 标记并入下一事件） */
  let gnPendingNotes: string[] = [];
  // ===== 赛飞儿 1406 状态（2026-10 接入；裁定见 TRACE.saifeir 注释；记录值=中央钩累计） =====
  /** 天赋记录值（对老主顾 12% ×R1×point06 / 非老主顾 point07 8%；终招消费后清空） */
  let sfRecord = 0;
  /** 天赋追击剩余次数（每回合 tal#3=1 次；赛飞儿回合开始重置） */
  let sfFollowLeft = 0;
  /** 记录值倍率（进战静态：0.12×point06 档×R1 1.5——进战判定落档） */
  let sfRecordRate = 0.12;
  /** 非老主顾记录倍率（point07 8%，随进战档判定融合——7/8 与老记录共用）。 */
  let sfExtraRate = 0;
  /** 赛飞儿散落备注（sfFollow/sfRecord/sfR2 标记并入下一事件） */
  let sfPendingNotes: string[] = [];
  // ===== 真理医生 1305 状态（2026-10-28 接入；归纳永久累积，E1 上限 +4/进战 4 层） =====
  /** point06 归纳层数（永久累积至战斗结束，封顶 6；E1 10） */
  let ratioStacks = 0;
  // ===== 托帕&账账 1112 状态（2026-10-29 接入） =====
  /** 【涨幅惊人！】剩余账账攻击次数（2；E6 3） */
  let topazUltLeft = 0;
  /** 秘技「明补」首次账账攻击 +60 能量待发 */
  let topazTechEnergyPending = false;
  /** 账账自身回合中（禁止【涨幅惊人！】拉条） */
  let topazNumbyActing = false;
  // ===== 貊泽 1223 状态（2026-10-29 接入；裁定见 docs/AGENTS-rogue.md §13） =====
  /** 【充能】0..9（战技设为 9；每次天赋附加伤害 -1） */
  let mozeCharge = 0;
  /** 自上次追击以来已累计消耗的充能点数（0..3-1；满 3 触发 1 次追击并清零） */
  let mozeSpent = 0;
  /** 当前【猎物】目标（仅最新有效；充能归零即解除） */
  let mozePrey: MonsterId | undefined;
  /** 离场中（挂上猎物即离场；充能归零回归） */
  let mozeAway = false;
  /** 离场时保存的 av / 行动条位置（回归时恢复） */
  let mozeSavedUnit: { av: number; order: number; speed: number } | null = null;
  /** point06 回 SP 冷却：true = 可触发 */
  let mozeP06Ready = true;
  /** point06 冷却计数（按貊泽自身回合计） */
  let mozeP06Wait = 0;
  // ===== 三月七（巡猎）1224 状态（2026-10-29 接入；裁定见 docs/AGENTS-rogue.md §12） =====
  /** 【充能】0..10 */
  let s7Charge = 0;
  /** 【师父】（仅最新目标有效；除自身外） */
  let s7Master: CharId | null = null;
  /** 终结技给「下一次强化普攻」的加成（初始段数 +2、额外段概率 +20%），用后清除 */
  let s7UltBuff = false;
  /** E6：下一次强化普攻暴伤 +50%（一次性） */
  let s7E6Ready = false;
  /** E2「每三月七回合最多 1 次」的本回合已触发标记 */
  let s7E2Used = false;
  /** 强化普攻结算中（防止「充能 ≥7 → 立即行动」自触发） */
