  /** 风堇实时速度（面板 + speedPct buff；point08/E4 阈值用） */
  function fengjinSpeed(): number {
    return panelOf('fengjin').speed * (1 + buffSum(holderOf('fengjin').buffs, 'speedPct'));
  }
  /** 小伊卡当前生命上限 = 召唤快照 ×（1+maxHpPct）+ 无 point08 动态百分比。
   *  受击分支/状态快照/maxHpOf 共用（遗器127 的忆灵半边必须走同一处，避免显示与钳制不一致）。 */
  function xiaoyikaCap(ignorePoint08 = false): number {
    let cap = xiaoyikaHpMax;
    if (!ignorePoint08 && fengjinSpeed() > TRACE.fengjin.point08Speed) {
      cap *= 1 + TRACE.fengjin.point08HpPct;
    }
    return cap * (1 + buffSum(holderOf('xiaoyika').buffs, 'maxHpPct'));
  }
  /** 目标当前生命上限：面板 + 玲可求生反应等 maxHpFlat + 风堇雨过天晴/E1/point08 动态加成。
   * 小伊卡按召唤时快照，不再吃雨过天晴动态百分比（快照已含召唤时风堇上限）。
   * 2026-11-02：新增 `maxHpPct` 比例乘区（遗器127「装备者及其忆灵生命上限 +24%」）；
   * 无该 buff 时 `base×(1+0)+flat` 与旧口径逐位等价（零回归）。 */
  function maxHpOf(target: HealTarget, ignorePoint08 = false, ignoreMaxHpPct = false): number {
    if (target === 'changye') return Math.max(1, changyeHpMax());
    if (target === 'silong') return Math.max(1, silongHpMax());
    if (target === 'xiaoyika') {
      return Math.max(
        1,
        xiaoyikaCap(ignorePoint08) + buffSum(holderOf('xiaoyika').buffs, 'maxHpFlat'),
      );
    }
    // 缇宝结界生命上限走 tibaoHp()（含 point07 显示生命），避免通用 clamp 把结界血量削回面板
    const base = target === 'tibao' ? tibaoHp() : panelOf(target).hp;
    const hpPct = ignoreMaxHpPct ? 0 : buffSum(holderOf(target).buffs, 'maxHpPct');
    const baseUp = base * (1 + hpPct);
    let flat = buffSum(holderOf(target).buffs, 'maxHpFlat');
    if (ids.has('fengjin') && fjRainyLeft > 0) {
      const ultP = skillParams('140903', levelsOf('fengjin').ult);
      const pct = ultP[2] + (fengjinEidolon() >= 1 ? TRACE.fengjin.eidolon1HpPct : 0);
      flat += baseUp * pct + ultP[3];
    }
    if (!ignorePoint08 && target === 'fengjin' && fengjinSpeed() > TRACE.fengjin.point08Speed) {
      flat += baseUp * TRACE.fengjin.point08HpPct;
    }
    if (target === 'phainon' && phainonForm) {
      return Math.max(1, (baseUp + flat) * (1 + TRACE.phainon.formHp));
    }
    // 符玄【穷观阵】鉴知：我方全体生命上限 +符玄生命上限×6%（2026-10-28 用户裁定）
    if (ids.has('fuxuan') && fxJzPct() > 0) flat += panelOf('fuxuan').hp * fxJzPct();
    return Math.max(1, baseUp + flat);
  }
  function healCap(target: HealTarget): number {
    const base = maxHpOf(target);
    // 【源质吞噬】（亚婆离 503401004）：可回复的生命上限降低（可叠加；只降可回复上限，不改当前 HP）
    const dev = memberDevour.get(target as CharId) ?? 0;
    // 【侵蚀】/【罪血腐蚀】（4064012）：已损失生命的一部分转为不可回复量（绝对生命值，ratio 上限 60%）
    const ero = memberErosion.get(target as CharId) ?? 0;
    if (dev <= 0 && ero <= 0) return base;
    const devCut = Math.min(DEVOUR_HEAL_CUT_MAX, DEVOUR_HEAL_CUT * dev);
    const eroCut = Math.min(EROSION_HEAL_CUT_MAX, base > 0 ? ero / base : 0);
    const cut = Math.min(DEVOUR_HEAL_CUT_MAX + EROSION_HEAL_CUT_MAX, devCut + eroCut);
    return Math.max(1, base * (1 - cut));
  }
  /** 符玄 1208（存护·量子）工具：穷观阵分摊 / 鉴知 / 天赋回血（2026-10-28 用户裁定） */
  function fxEidolon(): number {
    return ids.has('fuxuan') ? (members.find((x) => x.id === 'fuxuan')?.eidolonLevel ?? 0) : 0;
  }
  function fxSkillP(): number[] {
    return ids.has('fuxuan') ? skillParams('120802', levelsOf('fuxuan').skill) : [];
  }
  /** 【鉴知】生命上限提高比例（= 符玄上限 × #4；阵外为 0） */
  function fxJzPct(): number {
    return ids.has('fuxuan') && fxMatrix > 0 && !isDead('fuxuan') ? (fxSkillP()[3] ?? 0) : 0;
  }
  /** 符玄 E2「柔兆」：一次敌方行动结束后，本次行动中所有受致命伤的目标回 70% 上限且不倒下（单场 1 次） */
  function fxResolveE2(): void {
    if (fxE2Pending.length === 0) return;
    const ok = ids.has('fuxuan') && !fxE2Used && fxEidolon() >= 2 && fxMatrix > 0;
    if (ok) {
      fxE2Used = true;
      for (const id of fxE2Pending) {
        memberHp[id] = Math.max(1, maxHpOf(id)) * 0.7;
      }
    }
    fxE2Pending.length = 0;
  }
  /** 结束【穷观阵】：清鉴知/E1 暴伤 buff，当前 HP 截断到回落后的上限（符玄阵亡或阵到期） */
  function fxEndMatrix(): void {
    fxMatrix = 0;
    fxP08Charges = 0;
    // 移除与施加同步（120802【鉴知】施加处已改 allHolders）；HP 截断仍只对成员
    for (const h of allHolders()) {
      removeBuffInstance(h, { key: 'critRate', source: 'fuxuan', labelKey: 'fxJzCr' });
      removeBuffInstance(h, { key: 'critDmg', source: 'fuxuan', labelKey: 'fxE1Cd' });
    }
    for (const mm of members) {
      if (isDead(mm.id)) continue;
      memberHp[mm.id] = Math.min(memberHp[mm.id] ?? 0, Math.max(1, maxHpOf(mm.id)));
    }
  }
  /** 天赋 120804：HP≤#2=50% 时回「已损失生命×#3=90%」，初始 1 次、最多 2 次（致命伤不触发） */
  function fxTalentHeal(notes: string[]): void {
    if (!ids.has('fuxuan') || isDead('fuxuan') || fxHealCharges <= 0) return;
    const cap = Math.max(1, maxHpOf('fuxuan'));
    const hp = memberHp['fuxuan'] ?? cap;
    if (hp <= 0 || hp / cap > 0.5) return;
    const p = skillParams('120804', levelsOf('fuxuan').talent);
    memberHp['fuxuan'] = Math.min(cap, hp + (cap - hp) * (p[2] ?? 0));
    p06DirectHeal('fuxuan', hp);
    fxHealCharges -= 1;
    notes.push('fxTalentHeal');
  }
  /** 穷观阵分摊：护盾抵挡前伤害的 #1=65% 转给符玄（含所有通道，2026-10-28 裁定①）；
   *  分摊部分吃符玄自身护盾与减伤（裁定②）。返回被分走的数值。 */
  function fxSplitOf(target: CharId, raw: number, notes: string[]): number {
    if (!ids.has('fuxuan') || fxMatrix <= 0) return 0;
    if (target === 'fuxuan' || isDead('fuxuan')) return 0;
    const share = raw * (fxSkillP()[0] ?? 0);
    if (share <= 0) return 0;
    const fxA = applyDamageToMember(
      {
        hp: memberHp['fuxuan'] ?? 1,
        maxHp: Math.max(1, maxHpOf('fuxuan')),
        shield: shieldValues['fuxuan'] ?? 0,
      },
      share,
    );
    memberHp['fuxuan'] = fxA.hp;
    shieldValues['fuxuan'] = fxA.shield;
    if (fxA.hpLoss > 0) onHpLoss('fuxuan', fxA.hpLoss, { fromEnemy: true });
    notes.push('fxSplit');
    // 符玄阵亡 → 穷观阵立即结束（鉴知/避厄/分摊全部失效）
    if (fxA.dead) fxEndMatrix();
    // E4「格泽」：阵中其他目标受击 → 符玄 +5 能量
    if (fxEidolon() >= 4) gainEnergy('fuxuan', 5);
    fxTalentHeal(notes);
    return share;
  }
  /** E6「永屹城垣的壁垒」已叠层数（+10% 防御/层，上限 3） */
  let tbkE6Stacks = 0;
  /** E6：施放强化普攻或终结技后 防御力 +10%（最多 3 层） */
  function tbkAddE6(): void {
    const who = TK_IDS.find((x) => ids.has(x));
    if (!who) return;
    if ((members.find((x) => x.id === who)?.eidolonLevel ?? 0) < 6) return;
    tbkE6Stacks = Math.min(3, tbkE6Stacks + 1);
    removeBuffInstance(holderOf(who), { key: 'defPct', source: 'tbkE6', labelKey: 'tbkE6' });
    addBuff(holderOf(who), {
      key: 'defPct',
      source: 'tbkE6',
      labelKey: 'tbkE6',
      value: 0.1 * tbkE6Stacks,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
    });
  }
  /** MonsterState → 所在槽位 id（召唤物实体同样适用；找不到时返回 undefined） */
  function monsterIdOf(mon: MonsterState): MonsterId | undefined {
    return MONSTER_IDS.find((id) => monsters[id] === mon);
  }
  /** 强制敌方【主目标】的「嘲讽」统一入口（2026-10-29 用户裁定：嘲讽 = 强制主目标，与「受击概率提高」分离）：
   *  存护开拓者战技 / 万敌【血仇】/ 云璃格挡 / 波提欧【绝命对峙】（弹射/扩散仍按原规则） */
  function forcedMainOf(pool: readonly string[], attackerMon?: string): string | null {
    if (tbkTauntTurns > 0) {
      const who = TK_IDS.find((x) => ids.has(x) && pool.includes(x) && !isDead(x));
      if (who) return who;
    }
    // 万敌：终结技/秘技【血仇】嘲讽
    if (
      ids.has('mydei') &&
      pool.includes('mydei') &&
      !isDead('mydei') &&
      !!findBuffInstance(holderOf('mydei'), { key: 'taunt', source: 'mydei' })
    ) {
      return 'mydei';
    }
    // 云璃：格挡期间嘲讽
    if (ids.has('yunli') && pool.includes('yunli') && !isDead('yunli') && yunliParry) return 'yunli';
    // 波提欧：【绝命对峙】期间强制敌方攻击自己
    if (ids.has('boothill') && pool.includes('boothill') && boothillInStandoff()) return 'boothill';
    // 千冶：**被**千冶嘲讽的怪（150701/150708 单体、150707 全体）攻击时，主目标强制为千冶
    if (
      attackerMon !== undefined &&
      ids.has('qianye') &&
      pool.includes('qianye') &&
      !isDead('qianye') &&
      monsters[attackerMon as MonsterId] &&
      !!findBuffInstance(monsters[attackerMon as MonsterId].buffs, {
        key: 'lcMark',
        source: 'qianye',
        labelKey: 'qyTaunt',
      })
    ) {
      return 'qianye';
    }
    return null;
  }
  /** 存护开拓者天赋 800304：每受到 1 次攻击 +1 层【灼热意志】（每次敌方行动算 1 层，多段不叠加，裁定⑧） */
  function tbkOnEnemyAction(hits: { targetId: string }[]): void {
    if (hits.length === 0) return;
    const who = TK_IDS.find((x) => ids.has(x));
    if (!who || isDead(who)) return;
    if (!hits.some((h) => h.targetId === who)) return;
    tbkStacks = Math.min(8, tbkStacks + 1);
  }
  /** 多来源护盾分账（2026-10-29 用户裁定⑩）：每个来源独立记量，显示/有效吸收取最大，受击时各来源同扣一笔 */
  const shieldSources = new Map<string, Map<string, number>>();
  function shieldTop(id: string): number {
    const m = shieldSources.get(id);
    if (!m) return 0;
    let top = 0;
    for (const v of m.values()) top = Math.max(top, v);
    return top;
  }
  /** 兼容旧写法：shieldValues[id] 被直接写成超过分账总值的数时，差额记到 'misc' 来源 */
  function shieldSyncFromValue(id: string): void {
    const cur = shieldValues[id] ?? 0;
    let m = shieldSources.get(id);
    if (!m) {
      m = new Map();
      shieldSources.set(id, m);
    }
    const others = shieldTop(id) - (m.get('misc') ?? 0);
    const rest = Math.max(0, cur - others);
    if (rest > 0) m.set('misc', rest);
    else m.delete('misc');
    if (m.size === 0) shieldSources.delete(id);
  }
  /** 写入某来源的盾（同来源覆盖，不叠加） */
  function shieldWrite(id: string, source: string, amount: number, turns: number): void {
    // 4★ A 21053 愿旅途永远坦然：装备者提供的护盾量 +（按来源=装备者判定；'misc' 等匿名来源不乘）
    let amt = amount;
    const p53 = lcWearerParamOf('21053', source as CharId);
    if (p53 && amt > 0) amt *= 1 + p53[0];
    // ⚠ 遗器 128「护盾量 +12%」**不在这里**加：它统一在 `relicShieldMult(producer)` 里做，
    //   否则走「relicShieldMult → shieldWrite」的路径会双计（三月七 800304 就是这条路）。
    // 5★ A 23023 命运从未公平：提供护盾 → 暴伤 +
    if (amt > 0 && ids.has(source as CharId)) lc5aOnShield(source as CharId);
    let m = shieldSources.get(id);
    if (!m) {
      m = new Map();
      shieldSources.set(id, m);
    }
    if (amt > 0) m.set(source, amt);
    else m.delete(source);
    shieldValues[id] = shieldTop(id);
    shieldTurns[id] = turns;
  }
  /** 受击结算后：每个来源各扣同一笔吸收量，归零移除；显示取最大（裁定⑩a） */
  function shieldConsume(id: string, absorbed: number): void {
    const m = shieldSources.get(id);
    if (!m || absorbed <= 0) {
      shieldValues[id] = shieldTop(id);
      return;
    }
    for (const [k, v] of [...m]) {
      const left = v - absorbed;
      if (left > 0) m.set(k, left);
      else m.delete(k);
    }
    if (m.size === 0) shieldSources.delete(id);
    shieldValues[id] = shieldTop(id);
  }
  /** 存护开拓者天赋 800304「筑城者遗宝」：普攻/战技/终结技后为全队提供护盾
   *  = 开拓者防御×#1=6% + #4=80（#2=2 回合）；E2「古老寒铁的坚守」额外 + 防御×2% + 27 */
  function tbkTeamShield(source: CharId): void {
    if (!ids.has(source)) return;
    const tp = skillParams('800304', levelsOf(source).talent);
    const tE = members.find((x) => x.id === source)?.eidolonLevel ?? 0;
    const def = panelOf(source).defence * (1 + buffSum(holderOf(source).buffs, 'defPct'));
    let amount = def * (tp[0] ?? 0) + (tp[3] ?? 0);
    if (tE >= 2) amount += def * 0.02 + 27;
    amount *= relicShieldMult(source);
    const turns = Math.round(tp[2] ?? 2);
    for (const mm of members) {
      if (isDead(mm.id)) continue;
      shieldWrite(mm.id, source, amount, turns);
      dahliaP06OnAllySupport(mm.id, source);
    }
  }
  /** 目标效果抵抗（面板 + buff + 风堇 point07；0~1） */
  function effectResOf(id: CharId): number {
    let er = panelOf(id).effectRes ?? 0;
    er += buffSum(holderOf(id).buffs, 'effectRes');
    if (id === 'fengjin' && ids.has('fengjin')) er += TRACE.fengjin.point07EffectRes;
    return Math.min(1, Math.max(0, er));
  }
  /** 怪→我方负面加算概率：base + 怪物 effectHit − (我方 effectRes + 分项抵抗)；总抵抗≥1 免疫 */
  function enemyDebuffChance(
    base: number,
    target: CharId,
    effectHit: number,
    resist?: MonsterDebuffResist,
    kind?: string,
  ): number {
    const er = effectResOf(target);
    const rr = kind ? debuffResistValue(resist, kind) : 0;
    // 黑塔 point07「人偶」：抵抗控制类负面状态的概率 +35%（只作用于控制类）
    const isControl =
      kind !== undefined &&
      (kind === 'freeze' || kind === 'imprison' || kind === 'fear' || kind === 'entangle' || kind === 'drunk');
    let controlRes = 0;
    if (isControl) {
      if (target === 'herta4' && ids.has('herta4')) controlRes += TRACE.herta4.point07ControlRes;
      if (target === 'clara' && ids.has('clara')) controlRes += 0.35;
      if (target === 'yunli' && ids.has('yunli') && yunliParry) controlRes += 0.2;
      if (target === 'hook' && ids.has('hook')) controlRes += TRACE.hook.p07ControlRes;
      // 丹恒•饮月 point07「抵抗控制类负面状态的概率 +35%」（2026-11-02 A1 核出：常量原先从未被读取）
      if (target === 'danhengIL' && ids.has('danhengIL')) controlRes += TRACE.danhengIL.p07ControlRes;
    }
    if (er + rr + controlRes >= 1) return 0;
    return Math.min(1, Math.max(0, base + effectHit - er - rr - controlRes));
  }
  /** 敌方施加冻结：基础概率 + 敌方效果命中 − 我方效果抵抗 − 冻结抵抗（加算），种子随机；小伊卡免疫 */
  function applyEnemyFreeze(
    target: CharId,
    baseChance: number,
    duration: number,
    notes: string[],
    resist?: MonsterDebuffResist,
    effectHit = 0,
  ): void {
    if (isDead(target) || memberFreeze.has(target)) return;
    // 符玄 point08「六壬兆堪」：阵中我方全体抵抗本次行动的控制类负面（每个阵 1 次，重开阵刷新）
    if (ids.has('fuxuan') && fxMatrix > 0 && fxP08Charges > 0) {
      fxP08Charges = 0;
      notes.push('fxP08');
      return;
    }
    if (ids.has('mydei') && target === 'mydei' && mydeiBloodFeud) {
      notes.push('mydeiP07');
      return;
    }
    // 砂金天赋 130404「枪口以右」：持有【坚垣筹码】的我方目标抵抗控制类负面
    // 口径（2026-10-24 用户裁定）：首次控制直接免疫，2 回合后可再次触发
    if (
      ids.has('aventurine') &&
      (shieldValues[target] ?? 0) > 0 &&
      (avenImmunityRound.get(target) ?? -99) + 2 <= tl.round
    ) {
      avenImmunityRound.set(target, tl.round);
      notes.push('avenControlResist');
      return;
    }
    const chance = enemyDebuffChance(baseChance, target, effectHit, resist, 'freeze');
    if (chance <= 0) {
      notes.push('freezeResist');
      return;
    }
    // 100% 命中不耗随机数，避免改变既有固定种子的敌方技能序列
    const hit = chance >= 1 || debuffRand01() < chance;
    if (hit) {
      memberFreeze.set(target, Math.max(1, duration));
      notes.push('freeze');
    } else {
      notes.push('freezeResist');
    }
  }
  /** 风堇 point07：战技/终招解除全队各 1 个负面（最小模型仅冻结） */
  function fjCleanseOne(notes: string[]): void {
    let cleansed = false;
    for (const m of members) {
      if (isDead(m.id)) continue;
      if (memberFreeze.delete(m.id)) cleansed = true;
    }
    if (cleansed) notes.push('fjCleanse');
  }
  /** 上限下降时把当前 HP 钳回上限（雨过天晴结束等） */
  function clampHpToMax(): void {
    for (const t of healTargets()) {
      const cap = maxHpOf(t);
      if ((memberHp[t] ?? cap) > cap) memberHp[t] = cap;
    }
  }
  /** 统一治疗写回：只负责 cap/写 HP/实际回血后的 dahlia P06 钩子；治疗加成由各 helper 先算 */
  function healUnit(
    target: HealTarget,
    amount: number,
    healer: CharId,
    notes?: string[],
    allowDead = false,
  ): number {
    if (amount <= 0) return 0;
    if (target === 'changye') {
      if (!present.changye) return 0;
    } else if (target === 'silong') {
      if (!present.silong) return 0;
    } else if (target === 'xiaoyika') {
      if (!xiaoyikaPresent()) return 0;
    } else if (isDead(target) && !allowDead) {
      return 0;
    }
    // 刃 point07：受到治疗提高 20%；万敌 point08：按生命上限提高受疗
    let boosted = amount;
    if (target === 'blade' && ids.has('blade')) boosted *= 1 + TRACE.blade.point06HealBonus;
    if (target === 'mydei' && ids.has('mydei')) boosted *= 1 + mydeiP08Heal;
    const cap = healCap(target);
    const before =
      target === 'changye' ? changyeHp : target === 'silong' ? silongHp : (memberHp[target] ?? cap);
    const after = Math.min(cap, before + boosted);
    const actual = after - before;
    if (target === 'changye') changyeHp = after;
    else if (target === 'silong') silongHp = after;
    else memberHp[target] = after;
    if (after > before && target !== 'xiaoyika') dahliaP06OnAllySupport(target, healer);
    if (actual > 0 && target === 'blade') bladeOnHealed(actual);
    if (actual > 0 && target === 'mydei') mydeiOnHealed(actual);
    // 遐蝶 point06：治疗→【新蕊】（用实际入账量 actual，不是请求量；死龙在场转死龙 HP）
    xiedieP06Convert(actual, target);
    if (actual > 0 && target === 'phainon' && ids.has('phainon') && healer !== 'phainon') {
      if (phainonP07Turn !== tl.round) {
        phainonP07Turn = tl.round;
        addBuff(holderOf('phainon'), {
          key: 'damageBonus',
          source: 'phainon',
          labelKey: 'phainonP07',
          value: TRACE.phainon.p07Dmg,
          stacks: 1,
          duration: TRACE.phainon.p07Turns,
          tick: 'holderEnd',
        });
        notes?.push('phainonP07');
      }
    }
    void notes;
    return actual;
  }
