  /** E2 速度还原：除以 1+30% */
  function fjE2RestoreSpeed(id: CharId): void {
    if (!tl.has(id)) return;
    tl.speedChange(id, tl.getUnit(id).speed / (1 + TRACE.fengjin.eidolon2Speed));
  }
  /** E2：我方目标生命降低→速度+30% 2回合（进轴；刷新时先还原旧乘数） */
  function fjE2ApplySpeed(id: CharId): void {
    if (!ids.has('fengjin') || fengjinEidolon() < 2 || isDead(id) || !tl.has(id)) return;
    if (fjE2SpeedLeft.has(id)) fjE2RestoreSpeed(id);
    tl.speedChange(id, tl.getUnit(id).speed * (1 + TRACE.fengjin.eidolon2Speed));
    fjE2SpeedLeft.set(id, TRACE.fengjin.eidolon2Turns);
  }
  /** E2 速度在持有者行动前递减；归零还原（非行动单位也安全） */
  function fjE2SpeedTick(id: CharId): void {
    const left = fjE2SpeedLeft.get(id);
    if (left === undefined) return;
    if (left <= 1) {
      fjE2SpeedLeft.delete(id);
      fjE2RestoreSpeed(id);
    } else {
      fjE2SpeedLeft.set(id, left - 1);
    }
  }
  /** 天赋增伤计时：风堇行动结束递减；归零清层数并移除 buff（小伊卡不行动） */
  function tickXiaoyikaTalent(): void {
    if (xiaoyikaTalentTurns <= 0) return;
    if (xiaoyikaTalentFresh) {
      xiaoyikaTalentFresh = false;
      return;
    }
    xiaoyikaTalentTurns -= 1;
    if (xiaoyikaTalentTurns > 0) return;
    xiaoyikaTalentStacks = 0;
    removeBuffInstance(holderOf('xiaoyika'), {
      key: 'damageBonus',
      source: 'fengjin',
      labelKey: 'fjTalent',
    });
  }
