  /** 【醇醉】值 = 终招122203#4（随终招等级；秘技挂同名状态同源——2026-10 裁定） */
  function lingshaDrunkenValue(): number {
    return skillParams('122203', levelsOf('lingsha').ult)[3];
  }
  /** 挂【醇醉】到敌全体（终招/秘技）：受到的击破伤害提高（breakVulnerability 消费端既有） */
  function lingshaApplyDrunken(turns: number, notes: string[], label: string): void {
    for (const t of MONSTER_IDS) {
      addBuff(monsters[t].buffs, {
        key: 'breakVulnerability',
        value: lingshaDrunkenValue(),
        stacks: 1,
        duration: turns,
        tick: 'holderEnd',
        source: 'lingsha',
        labelKey: 'lingshaDrunken',
      });
    }
    if (!notes.includes(label)) notes.push(label);
  }
  /** 浮元消失（行动次数耗尽/灵砂退场）：清次数出轴 + E6 全抗还原 */
  function lingshaRemoveFuyuan(notes?: string[]): void {
    if (lingshaFuyuanActions <= 0 && !lingshaE6ResOn && !tl.has('fuyuan')) return;
    lingshaFuyuanActions = 0;
    if (tl.has('fuyuan')) tl.removeUnit('fuyuan');
    if (lingshaE6ResOn) {
      lingshaE6ResOn = false;
      for (const t of MONSTER_IDS) {
        removeBuffInstance(monsters[t].buffs, { key: 'resReduction', source: 'lingsha', labelKey: 'lingshaE6' });
      }
    }
    if (notes && !notes.includes('lingshaFuyuanEnd')) notes.push('lingshaFuyuanEnd');
  }
  /** 召唤/补充浮元（战技/终招/秘技后调用）：+actions 次（封顶天赋#5）、首次进轴速度#1、E6 挂载 */
  function lingshaSummonFuyuan(addActions: number, notes: string[]): void {
    if (!ids.has('lingsha') || isDead('lingsha')) return;
    const p = skillParams('122204', levelsOf('lingsha').talent);
    const first = lingshaFuyuanActions <= 0 && !tl.has('fuyuan');
    lingshaFuyuanActions = Math.min(p[4], lingshaFuyuanActions + addActions);
    if (first) {
      tl.addUnit({ id: 'fuyuan', side: 'ally', speed: p[0], order: members.length });
      if (!notes.includes('lingshaFuyuan')) notes.push('lingshaFuyuan');
    }
    if (lingshaEidolon() >= 6 && !lingshaE6ResOn) {
      lingshaE6ResOn = true;
      for (const t of MONSTER_IDS) {
        addBuff(monsters[t].buffs, {
          key: 'resReduction',
          value: TRACE.lingsha.eidolon6ResDown,
          stacks: 1,
          duration: 999,
          tick: 'holderEnd',
          source: 'lingsha',
          labelKey: 'lingshaE6',
        });
      }
    }
  }
  /** 浮元行动提前（战技#4/终招#6——tl.actionAdvance，翔鹰110先例） */
  function lingshaFuyuanAdvance(pct: number): void {
    if (pct > 0 && tl.has('fuyuan')) tl.actionAdvance('fuyuan', pct);
  }
  /** 天赋121704【禳命】触发治疗（我方目标回合开始/施放终结技时）：
   * 先治藿藿自身+生命%最低队友各一次，再治每个生命%≤50%的队友一次；
   * 每次治疗量 = 藿藿MaxHP×#3 + #5（E4 低血加成、E6 伤害提高、专武#3 攻提高、point08 回能经 tailsHeal）。
   * 净化#2 与触发次数#7 本轮跳过（我方负面未建模，记待核）。 */
  function tailsRangelMingTrigger(notes: string[]): void {
    if (rangelMing <= 0 || isDead('tails')) return;
    const tal = skillParams('121704', levelsOf('tails').talent);
    const amount = tal[2] * tailsHpMax() + tal[4];
    const alive = healTargets().filter((t) => t !== 'tails');
    // 生命%最低队友（Alive 顺序=编队顺序；并列取先；小伊卡可被选中）
    let lowest: HealTarget | undefined;
    let lowestPct = 2;
    for (const t of alive) {
      const cap = healCap(t);
      const pct = (memberHp[t] ?? 1) / cap;
      if (pct < lowestPct) {
        lowestPct = pct;
        lowest = t;
      }
    }
    const targets = new Set<HealTarget>(['tails']);
    if (lowest) targets.add(lowest);
    for (const t of targets) tailsHeal(t, amount, { boost: true, notes });
    // 第二波：每个生命%≤#6 的队友再治一次
    for (const t of alive) {
      const cap = healCap(t);
      if ((memberHp[t] ?? 1) / cap <= tal[5]) tailsHeal(t, amount, { boost: true, notes });
    }
    notes.push('tailsTalent');
    // point08：触发天赋提供治疗 → 藿藿 +1 能量×充能（按每次触发计，待核是否按受治疗目标数）
    gainEnergy('tails', TRACE.tails.point08Energy);
  }
  /** 秘技减攻递减（每怪物行动后调用；归零还原攻击乘区） */
  function tickMonsterAtkDown(id: MonsterId): void {
    if (monsterAtkDown >= 1) return;
    monsterAtkLeft[id] -= 1;
    if (monsterAtkLeft[id] <= 0) {
      let any = false;
      for (const m of MONSTER_IDS) {
        if (monsterAtkLeft[m] > 0) any = true;
      }
      if (!any) monsterAtkDown = 1;
    }
  }
  // ===== 娜塔莎 1105 helpers + 通用持续治疗（HoT）机制（2026-10 接入） =====
  /** 娜塔莎星魂等级（function 声明提升，init 早期可调用） */
  function natashaEidolon(): number {
    return members.find((x) => x.id === 'natasha')?.eidolonLevel ?? 0;
  }
  /** 娜塔莎治疗中心化（溢出钳制+死人不奶——zzHeal/luochaHeal 同款；healBonus 乘区；
   * 天赋110504：治疗生命%≤#1 目标时治疗量+#2（对持续治疗生效——统一在此加成） */
  function natashaHeal(target: HealTarget, base: number, notes?: string[]): void {
    if ((target === 'xiaoyika' && !xiaoyikaPresent()) || (target !== 'xiaoyika' && isDead(target)) || base <= 0) {
      return;
    }
    let amount = base;
    const cap = healCap(target);
    const tal = skillParams('110504', levelsOf('natasha').talent);
    if ((memberHp[target] ?? 1) / cap <= tal[0]) amount *= 1 + tal[1];
    amount *= healBonusMult('natasha');
    const effective = healUnit(target, amount, 'natasha', notes);
    if (effective > 0 && notes && !notes.includes('natashaHeal')) notes.push('natashaHeal');
  }
  /** 挂持续治疗条目（同 target+source 覆盖刷新不叠层——娜塔莎110502战技/E2、玲可111004 共用） */
  function addRegenHeal(e: RegenHeal): void {
    regenHeals = regenHeals.filter((r) => !(r.target === e.target && r.source === e.source));
    regenHeals.push({ ...e });
  }
  /** 回合开始结算持续治疗：在目标成员行动前调用（charAction 决策前——禳命钩子旁）；
   * 按 source 分发治疗中心化函数，每条 -1 回合、耗尽移除；tick 备注走 entry.labelKey。 */
  function tickRegenHealsStart(target: CombatUnitId, notes: string[]): void {
    if (regenHeals.length === 0) return;
    for (const r of [...regenHeals]) {
      if (r.mode !== 'turnStart' || r.target !== target) continue;
      if (isDead(r.target)) {
        regenHeals = regenHeals.filter((x) => x !== r);
        continue;
      }
      const base = r.hpPct * panelOf(r.source).hp + r.flat;
      if (r.source === 'natasha') natashaHeal(r.target, base, notes);
      else if (r.source === 'lynx') lynxHeal(r.target, base, notes);
      r.left -= 1;
      if (r.left <= 0) regenHeals = regenHeals.filter((x) => x !== r);
      if (!notes.includes(r.labelKey)) notes.push(r.labelKey);
    }
  }

