  /** 目标是否持有玲可求生反应（maxHpFlat buff 存在性判定——天赋HoT分档/E4 用） */
  function hasSurvivalReaction(target: CharId): boolean {
    return !!findBuffInstance(holderOf(target), {
      key: 'maxHpFlat',
      source: 'lynx',
      labelKey: 'lynxSurvival',
    });
  }
  /** 挂求生反应：目标 maxHpFlat buff（value=玲可上限×p0[+E6加成]+p1，duration=p2，holderEnd）
   * + E4 获得时目标 atkFlat（玲可上限×3%，持1回合）+ note lynxSurvival */
  function applySurvivalReaction(target: CharId, notes: string[]): void {
    const lynxHp = panelOf('lynx').hp;
    const p = skillParams('111002', levelsOf('lynx').skill);
    const e = lynxEidolon();
    const hpPct = p[0] + (e >= 6 ? TRACE.lynx.eidolon6HpPct : 0);
    addBuff(holderOf(target), {
      key: 'maxHpFlat',
      source: 'lynx',
      labelKey: 'lynxSurvival',
      value: hpPct * lynxHp + p[1],
      stacks: 1,
      duration: p[2],
      tick: 'holderEnd',
    });
    // E4：获得求生反应时目标攻击力+玲可上限×3% 持续1回合
    if (e >= 4) {
      addBuff(holderOf(target), {
        key: 'atkFlat',
        source: 'lynx',
        labelKey: 'lynxE4Atk',
        value: TRACE.lynx.eidolon4AtkPct * lynxHp,
        stacks: 1,
        duration: TRACE.lynx.eidolon4Turns,
        tick: 'holderEnd',
      });
    }
    if (!notes.includes('lynxSurvival')) notes.push('lynxSurvival');
  }
  /** 天赋111004 HoT：按求生反应状态分档（持有→基础+额外，无→仅基础）。
   * 挂 turnStart 型持续治疗（与 natashaHoT 共用 addRegenHeal 机制，source=lynx 分发）。 */
  function lynxApplyHoT(target: CharId): void {
    const tal = skillParams('111004', levelsOf('lynx').talent);
    const enhanced = hasSurvivalReaction(target);
    addRegenHeal({
      target,
      hpPct: tal[1] + (enhanced ? tal[3] : 0),
      flat: tal[2] + (enhanced ? tal[4] : 0),
      left: tal[0],
      mode: 'turnStart',
      source: 'lynx',
      labelKey: 'lynxHoT',
    });
  }

