  // ===== 卢卡 1111 helpers（2026-10-19 接入；裁定见 TRACE.luka 注释） =====
  function lukaEidolon(): number {
    return members.find((x) => x.id === 'luka')?.eidolonLevel ?? 0;
  }
  /** 战技参数快照：[1.2,1,0.24,3.38,3]（#3 生命上限%、#4 cap=攻击力%、#5 持续回合） */
  function lukaRuptureParams(): number[] {
    return skillParams('111102', levelsOf('luka').skill);
  }
  /** R4 同步：atkPct 实例按当前斗志层数覆盖刷新（0 层清除；未激活不挂/清除） */
  function lukaSyncR4(): void {
    const e = lukaEidolon();
    const h = holderOf('luka');
    const inst = { key: 'atkPct' as BuffKey, value: 0, stacks: 1, duration: -1, tick: 'permanent' as const, source: 'luka', labelKey: 'lkR4' };
    if (findBuffInstance(h, inst)) removeBuffInstance(h, inst);
    if (e >= 4 && lukaSpirit > 0) {
      addBuff(h, { ...inst, value: TRACE.luka.eidolon4AtkPct * Math.min(lukaSpirit, TRACE.luka.eidolon4MaxStacks) });
    }
  }
  /** 获得 n 层【斗志】（cap4）：R4 同步 + point07 每「实际获得」1 层 +3 能（吃充能效率） */
  function lukaGainSpirit(n: number): void {
    if (!ids.has('luka') || isDead('luka')) return;
    const gained = Math.min(4, lukaSpirit + n) - lukaSpirit;
    if (gained <= 0) return;
    lukaSpirit += gained;
    lukaSyncR4();
    gainEnergy('luka', TRACE.luka.point07Energy * gained);
  }
  /** 消耗 2 层斗志（强化普攻），R4 同步回落 */
  function lukaSpendSpirit(): void {
    if (!ids.has('luka')) return;
    lukaSpirit = Math.max(0, lukaSpirit - 2);
    lukaSyncR4();
  }
  /** 目标是否陷【卢卡裂伤】 */
  function lukaHasRupture(target: MonsterId): boolean {
    return monsters[target].skillDots.some((d) => d.dotType === 'bleed' && d.source === 'luka');
  }
  /** R1 消费点：目标持有裂伤→damageBonusExtra +0.15（2 回合持续=每次行动命中即挂的落档简化） */
  function lukaR1Bonus(target: MonsterId): number {
    if (!ids.has('luka') || lukaEidolon() < 1) return 0;
    return lukaHasRupture(target) ? TRACE.luka.eidolon1DmgBonus : 0;
  }
  /** 挂【裂伤】（怪侧 skillDot：dotType='bleed'、hpBased、capRatio=p4=3.38、持续=p5=3）；
   *  同 source 同 dotType 覆盖刷新（官方复挂=刷新回合）；chance 由调用方先 lcRoll */
  function lukaApplyRupture(target: MonsterId, chance: number): void {
    if (!ids.has('luka') || monsters[target].hp <= 0) return;
    if (!lcRoll('luka', chance, target, 'dot')) return;
    const p = lukaRuptureParams();
    const mon = monsters[target];
    const ex = mon.skillDots.find((d) => d.dotType === 'bleed' && d.source === 'luka');
    if (ex) {
      ex.multiplier = p[2];
      ex.duration = Math.round(p[4]);
      ex.capRatio = p[3];
    } else {
      mon.skillDots.push({ dotType: 'bleed', element: 'Physical', source: 'luka', stacks: 1, duration: Math.round(p[4]), multiplier: p[2], hpBased: true, capRatio: p[3] });
    }
    lkPendingNotes.push('lkRupture');
  }
  /** 裂伤立即爆发：只对卢卡 bleed 逐条跳伤 ×mult（复读 detonate skillDot 分支；不消耗裂伤条目） */
  function lukaDetonateRupture(target: MonsterId, mult: number, skillCode: string, seqs: number[]): void {
    if (!ids.has('luka')) return;
    const mon = monsters[target];
    if (mon.hp <= 0) return;
    for (const sd of [...mon.skillDots]) {
      if (sd.dotType !== 'bleed' || sd.source !== 'luka') continue;
      const src = sd.source;
      const atkNow = atkNowOf(src, holderOf(src));
      let statValue = atkNow;
      let multiplier = sd.multiplier * sd.stacks;
      if (sd.hpBased) {
        statValue = Math.min(mon.maxHp * sd.multiplier * sd.stacks, atkNow * (sd.capRatio ?? 0));
        multiplier = 1;
      }
      const snap = zoneSnapshot(sd.element, panelOf(src).level, src, target);
      const result = computeDotDamage({
        statValue,
        multiplier,
        damageBonus: panelOf(src).damageBonus + buffSum(holderOf(src).buffs, 'damageBonus'),
        independentMultiplier: hysilensDotMult() * mult * kafkaDoTIndep(mon, src),
        common: { ...snap, toughness: 'notApplied' },
      });
      seqs.push(pushHit(result, { source: target, skillCode: `${skillCode}.${sd.dotType}`, target }, 'dot'));
      hysilensNoteDotDamage(target);
    }
  }

