  /** 挂【吞火】（121004：#1=1 概率、#4=受伤提高 7%/层、#5=持续3、#6=上限3层；E6 上限+1；
   *  单实例 upsert：stacks 累计、value=每层×总层数，jqJinwei 先例） */
  function guinaifenApplyTom(target: MonsterId, chance: number, noteKey: string): void {
    if (!ids.has('guinaifen') || isDead('guinaifen') || monsters[target].hp <= 0) return;
    if (!lcRoll('guinaifen', chance, target, 'vulnerability')) return;
    const tp = gnTalentParams();
    const mon = monsters[target];
    const perStack = tp[3];
    const cap = Math.round(tp[5]) + (guinaifenEidolon() >= 6 ? 1 : 0);
    const inst = findBuffInstance(mon.buffs, { key: 'vulnerability', source: 'guinaifen', labelKey: 'gnTom' });
    const cur = inst?.stacks ?? 0;
    if (cur >= cap) return;
    if (inst) {
      inst.stacks = cur + 1;
      inst.value = perStack * inst.stacks;
      inst.duration = Math.round(tp[4]);
    } else {
      addBuff(mon.buffs, {
        key: 'vulnerability',
        value: perStack,
        stacks: 1,
        duration: Math.round(tp[4]),
        tick: 'holderEnd',
        source: 'guinaifen',
        labelKey: 'gnTom',
      });
    }
    gnPendingNotes.push(noteKey);
  }
