  /** point08 破敌：普攻/战技后，若场上有敌方目标处于弱点击破状态 → 自身行动提前 15% */
  function sushangPoint08(notes: string[]): void {
    if (!ids.has('sushang') || isDead('sushang')) return;
    const anyBroken = aliveMonsters().some((m) => monsters[m].broken === true);
    if (!anyBroken) return;
    sushangP08Pending = true;
    notes.push('sushangP08');
  }
  /** 天赋 120604：任意敌方弱点被击破 → 自身速度 +20%（2 回合；E6 可叠 2 层） */
  function sushangSyncSpeed(): void {
    if (!tl.has('sushang')) return;
    const next = 1 + TRACE.sushang.talentSpeed * sushangSpeedStacks;
    if (next === sushangSpeedMult) return;
    tl.speedChange('sushang', (tl.getUnit('sushang').speed / sushangSpeedMult) * next);
    sushangSpeedMult = next;
  }
  function sushangOnAllyBreak(notes: string[]): void {
    if (!ids.has('sushang') || isDead('sushang')) return;
    const cap = sushangEidolon() >= 6 ? TRACE.sushang.e6MaxStacks : 1;
    if (sushangSpeedStacks >= cap && sushangSpeedTurns > 0) {
      sushangSpeedTurns = TRACE.sushang.talentTurns;
      return;
    }
    sushangSpeedStacks = Math.min(cap, sushangSpeedStacks + 1);
    sushangSpeedTurns = TRACE.sushang.talentTurns;
    sushangSyncSpeed();
    notes.push('sushangTalent');
  }
  /** 自身回合结束：加速/终结技额外判定/E2 计时递减，到期还原 */
  function sushangOnTurnEnd(): void {
    if (!ids.has('sushang')) return;
    if (sushangExtraTurns > 0) sushangExtraTurns -= 1;
    if (sushangE2Turns > 0) sushangE2Turns -= 1;
    if (sushangSpeedTurns > 0) {
      sushangSpeedTurns -= 1;
      if (sushangSpeedTurns === 0) {
        sushangSpeedStacks = 0;
        sushangSyncSpeed();
      }
    }
  }
  // ===== 巡猎 1112 托帕&账账 helpers（2026-10-29 接入） =====
  function topazEidolon(): number {
    return members.find((m) => m.id === 'topaz')?.eidolonLevel ?? 0;
  }
  function topazDebtTarget(): MonsterId | undefined {
    return MONSTER_IDS.find(
      (id) =>
        monsters[id].hp > 0 &&
        !!findBuffInstance(monsters[id].buffs, {
          key: 'topazDebt',
          source: 'topaz',
          labelKey: 'topazDebt',
        }),
    );
  }
  function topazClearDebt(): void {
    for (const id of MONSTER_IDS) {
      removeBuffInstance(monsters[id].buffs, {
        key: 'topazDebt',
        source: 'topaz',
        labelKey: 'topazDebt',
      });
      removeBuffInstance(monsters[id].buffs, {
        key: 'topazExecuted',
        source: 'topaz',
        labelKey: 'topazExecuted',
      });
    }
  }
  function topazApplyDebt(target: MonsterId): void {
    if (monsters[target].hp <= 0) return;
    const cur = topazDebtTarget();
    if (cur !== target) topazClearDebt();
    lcMonsterBuff(target, 'topazDebt', TRACE.topaz.debtVuln, 'topazDebt', 'topaz', -1);
  }
  function topazEnsureDebt(notes: string[]): void {
    if (!ids.has('topaz') || isDead('topaz')) return;
    if (topazDebtTarget()) return;
    const alive = aliveMonsters();
    if (alive.length === 0) return;
    topazApplyDebt(alive[Math.floor(rand01() * alive.length)]);
    notes.push('topazAutoDebt');
  }
  function topazP07(target: MonsterId): number {
    return monsters[target].weaknesses.has('Fire') ? TRACE.topaz.p07FireWeakDmg : 0;
  }
  function topazUltActive(): boolean {
    return (
      topazUltLeft > 0 &&
      ids.has('topaz') &&
      !isDead('topaz') &&
      tl.has('topazNumby')
    );
  }
  function topazE1Stack(target: MonsterId): void {
    if (topazEidolon() < 1 || monsters[target].hp <= 0) return;
    const cur = findBuffInstance(monsters[target].buffs, {
      key: 'topazExecuted',
      source: 'topaz',
      labelKey: 'topazExecuted',
    });
    const next = Math.min(TRACE.topaz.e1MaxStacks, (cur?.stacks ?? 0) + 1);
    lcMonsterBuff(
      target,
      'topazExecuted',
      TRACE.topaz.e1CritDmgTaken,
      'topazExecuted',
      'topaz',
      -1,
      next,
    );
  }
  /** 账账攻击（战技带出 / 自身回合）：150% 攻击火伤、按追加攻击结算 */
  function topazNumbyAttack(
    target: MonsterId,
    mode: 'skill' | 'talent',
    notes: string[],
  ): number[] {
    if (!ids.has('topaz') || isDead('topaz')) return [];
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    let main = target;
    if (monsters[main].hp <= 0) main = topazDebtTarget() ?? alive[0];
    if (monsters[main].hp <= 0) main = alive[0];
    const panel = panelOf('topaz');
    const lv = levelsOf('topaz');
    const eid = topazEidolon();
    const inUlt = topazUltActive();
    const base =
      mode === 'skill'
        ? skillParams('111202', lv.skill)[0]
        : skillParams('111204', lv.talent)[1];
    const skillId = mode === 'skill' ? '111202' : '111204';
    const skillCode = mode === 'skill' ? 'topaz.skill' : 'topaz.talent';
    const seqs: number[] = [];
    try {
      relicFollowupStart('topaz');
      seqs.push(
        ...dealAttack({
          source: 'topaz',
          skillCode,
          element: panel.element,
          level: panel.level,
          statValue: panel.attack,
          multiplier: base + (inUlt ? TRACE.topaz.ultAtkAdd : 0),
          damageBonusExtra: topazP07(main),
          critRate: panel.critRate,
          critDmg: panel.critDmg + (inUlt ? TRACE.topaz.ultCritDmg : 0),
          stance: stanceOf(skillId, mode === 'skill' ? lv.skill : lv.talent),
          attackerBuffs: holderOf('topaz'),
          target: main,
          attackKind: 'followup',
          zoneExtras:
            inUlt && eid >= 6 ? { resPenetration: TRACE.topaz.e6FirePen } : undefined,
        }),
      );
    } finally {
      relicFollowupEnd();
    }
    if (seqs.length === 0) return seqs;
    notes.push('topazNumby');
    gainEnergy('topaz', TRACE.topaz.numbyEnergy);
    if (topazTechEnergyPending) {
      topazTechEnergyPending = false;
      gainEnergy('topaz', TRACE.topaz.techEnergy);
      notes.push('topazTech');
    }
    if (inUlt) {
      gainEnergy('topaz', TRACE.topaz.p08Energy);
      notes.push('topazP08');
      topazUltLeft = Math.max(0, topazUltLeft - 1);
      if (topazUltLeft === 0) notes.push('topazUltEnd');
    }
    return seqs;
  }
  /** 账账自身回合：E4 拉条 → 确保负债 → 攻击 → E2 回能 */
  function topazNumbyTurn(time: number, round: number): void {
    if (!ids.has('topaz') || isDead('topaz') || aliveMonsters().length === 0) return;
    const notes: string[] = [];
    const eid = topazEidolon();
    topazNumbyActing = true;
    try {
      if (eid >= 4 && tl.has('topaz')) {
        tl.actionAdvance('topaz', TRACE.topaz.e4Advance);
        notes.push('topazE4');
      }
      topazEnsureDebt(notes);
      const target = topazDebtTarget() ?? aliveMonsters()[0];
      const seqs = topazNumbyAttack(target, 'talent', notes);
      if (eid >= 2 && seqs.length > 0) {
        gainEnergy('topaz', TRACE.topaz.e2Energy);
        notes.push('topazE2');
      }
      record({
        time,
        round,
        kind: 'action',
        unitId: 'topazNumby',
        action: 'talent',
        skillCode: 'topaz.talent',
        spAfter: sp,
        energyAfter: energyAfterOf('topaz'),
        hitSeqs: seqs.length > 0 ? seqs : undefined,
        note: notes,
      });
    } finally {
      topazNumbyActing = false;
    }
  }
  function topazSyncPresence(): void {
    if (ids.has('topaz') && !isDead('topaz')) return;
    topazUltLeft = 0;
    topazTechEnergyPending = false;
    topazClearDebt();
    if (tl.has('topazNumby')) tl.removeUnit('topazNumby');
  }

  // ===== 貊泽 1223 helpers（2026-10-29 接入；裁定见 docs/AGENTS-rogue.md §13） =====
  function mozeEidolon(): number {
    return members.find((m) => m.id === 'moze')?.eidolonLevel ?? 0;
  }
  /** 场上是否还有其他可战斗角色（solo 时**不能施放战技**、也不进入离场） */
  function mozeCanSkill(): boolean {
    if (!ids.has('moze')) return false;
    return members.some((m) => m.id !== 'moze' && !isDead(m.id));
  }
  /** 天赋追击倍率（p3；E6 ×1.25 相对提高） */
  function mozeFollowMult(): number {
    const base = skillParams('122304', levelsOf('moze').talent)[2] ?? TRACE.moze.followMult;
    return mozeEidolon() >= 6 ? base * TRACE.moze.e6FollowMult : base;
  }
  /** 只清【猎物】标记（buff + 局部状态），不动离场/充能 */
  function mozeClearPreyMarks(): void {
    for (const id of MONSTER_IDS) {
      removeBuffInstance(monsters[id].buffs, { key: 'mozePrey', source: 'moze', labelKey: 'mozePrey' });
      removeBuffInstance(monsters[id].buffs, { key: 'mozePreyVuln', source: 'moze', labelKey: 'mozePreyVuln' });
    }
    mozePrey = undefined;
  }
  /** 进入离场：保存 av/order/speed 后移出行动条（不可选中、不占跑道） */
  function mozeEnterAway(): void {
    if (mozeAway) return;
    mozeAway = true;
    if (tl.has('moze')) {
      const u = tl.getUnit('moze');
      mozeSavedUnit = { av: u.av, order: u.order, speed: u.speed };
      tl.removeUnit('moze');
    } else {
      mozeSavedUnit = null;
    }
  }
  /** 解除离场：恢复保存的 av 回行动条，随后行迹 point07 行动提前 20% */
  function mozeReturn(notes?: string[]): void {
    if (!mozeAway) return;
    mozeAway = false;
    if (!tl.has('moze')) {
      const saved = mozeSavedUnit;
      tl.addUnit({
        id: 'moze',
        side: 'ally',
        speed: saved?.speed ?? panelOf('moze').speed,
        order: saved?.order ?? members.length,
        ...(saved ? { initialAv: saved.av } : {}),
      });
    }
    mozeSavedUnit = null;
    if (tl.has('moze')) {
      tl.actionAdvance('moze', TRACE.moze.p07AdvanceReturn);
      notes?.push('mozeReturn');
    }
  }
  /** 解除【猎物】（充能归零）：清标记 + 重置计数 + 回归 */
  function mozeEndPrey(notes?: string[]): void {
    mozeClearPreyMarks();
    mozeSpent = 0;
    mozeReturn(notes);
    notes?.push('mozePreyEnd');
  }
  /** 挂【猎物】：覆盖旧目标 → 有其他队友时进入离场 */
  function mozeApplyPrey(target: MonsterId, notes?: string[]): void {
    if (!ids.has('moze') || monsters[target].hp <= 0) return;
    mozeClearPreyMarks();
    lcMonsterBuff(target, 'mozePrey', 0, 'mozePrey', 'moze', -1);
    lcMonsterBuff(target, 'mozePreyVuln', TRACE.moze.preyVuln, 'mozePreyVuln', 'moze', -1);
    mozePrey = target;
    if (mozeCanSkill()) mozeEnterAway();
    notes?.push('mozePrey');
  }
  /** 天赋追击（p3 倍率；不消耗充能；point06 回 SP 有 1 个自身回合 CD） */
  function mozeFollowup(target: MonsterId | undefined, notes: string[]): number[] {
    if (!ids.has('moze')) return [];
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    let main = target ?? mozePrey ?? alive[0];
    if (monsters[main].hp <= 0) main = mozePrey ?? alive[0];
    if (monsters[main].hp <= 0) main = alive[0];
    const p = panelOf('moze');
    const seqs: number[] = [];
    try {
      relicFollowupStart('moze');
      seqs.push(
        ...dealAttack({
          source: 'moze',
          skillCode: 'moze.talent',
          element: p.element,
          level: p.level,
          statValue: p.attack,
          multiplier: mozeFollowMult(),
          damageBonusExtra: 0,
          critRate: p.critRate,
          critDmg: p.critDmg,
          stance: TRACE.moze.followStance,
          attackerBuffs: holderOf('moze'),
          target: main,
          attackKind: 'followup',
        }),
      );
    } finally {
      relicFollowupEnd();
    }
    if (seqs.length === 0) return seqs;
    notes.push('mozeFollowup');
    if (mozeP06Ready) {
      mozeP06Ready = false;
      mozeP06Wait = TRACE.moze.p06Turns;
      gainSp(TRACE.moze.p06Sp, 'moze');
      notes.push('mozeP06');
    }
    return seqs;
  }
  /** 我方一次攻击行动命中【猎物】后：天赋附加伤害 → 扣 1 充能 → 每满 3 点发动 1 次追击 */
  function mozeOnPreyHit(target: MonsterId, notes: string[], seqs: number[]): void {
    if (!ids.has('moze') || isDead('moze')) return;
    if (mozePrey !== target || monsters[target].hp <= 0) return;
    if (mozeCharge <= 0) return;
    const p = panelOf('moze');
    const lv = levelsOf('moze');
    const extra = skillParams('122304', lv.talent)[0] ?? TRACE.moze.extraMult;
    // 附加伤害：30%×攻击、雷属性、可暴击（不削韧；不视为 1 次攻击）
    seqs.push(
      ...dealAttack({
        source: 'moze',
        skillCode: 'moze.extra',
        element: p.element,
        level: p.level,
        statValue: p.attack,
        multiplier: extra,
        damageBonusExtra: 0,
        critRate: p.critRate,
        critDmg: p.critDmg,
        stance: 0,
        attackerBuffs: holderOf('moze'),
        target,
        attackKind: 'followup',
      }),
    );
    notes.push('mozeExtra');
    mozeCharge = Math.max(0, mozeCharge - 1);
    mozeSpent += 1;
    if (mozeEidolon() >= 1) {
      gainEnergy('moze', TRACE.moze.e1EnergyPerExtra);
      notes.push('mozeE1');
    }
    // 每满 3 点消耗 → 1 次追击（追击本身不再扣充能）
    while (mozeSpent >= TRACE.moze.chargePerFollowup && monsters[target].hp > 0) {
      mozeSpent -= TRACE.moze.chargePerFollowup;
      seqs.push(...mozeFollowup(target, notes));
    }
    if (mozeCharge === 0) mozeEndPrey(notes);
  }
  /** 每次事件前的存在性同步：貊泽阵亡清全部状态；【猎物】目标已死则解除并回归 */
  function mozeSyncPresence(): void {
    if (!ids.has('moze') || isDead('moze')) {
      mozeClearPreyMarks();
      mozeCharge = 0;
      mozeSpent = 0;
      mozeAway = false;
      mozeSavedUnit = null;
      if (tl.has('moze')) tl.removeUnit('moze');
      return;
    }
    if (mozePrey !== undefined && monsters[mozePrey].hp <= 0) mozeEndPrey();
  }

  // ===== 三月七（巡猎）1224 helpers（2026-10-29 接入；裁定见 docs/AGENTS-rogue.md §12） =====
  /** 师父速度加速的基础速度记录（换人/解绑时还原） */
  let s7MasterSpeedTarget: CharId | null = null;
  let s7MasterSpeedBase = 0;
  function s7Eidolon(): number {
    return members.find((m) => m.id === 'sanyueqi2')?.eidolonLevel ?? 0;
  }
  function s7Alive(): boolean {
    return ids.has('sanyueqi2') && !isDead('sanyueqi2');
  }
  /** 充能 ≥7 → 强化普攻窗口（可强化普攻、禁战技） */
  function s7EnhancedReady(): boolean {
    return s7Alive() && s7Charge >= TRACE.sanyueqi2.chargeNeed;
  }
  /** 是否需要（重新）指定【师父】：无师父 / 师父已阵亡 / 当前主 C 不是师父 */
  function s7NeedSkill(): boolean {
    if (!s7Alive()) return false;
    if (!s7Master || isDead(s7Master)) return true;
    const main = members.find((m) => m.id !== 'sanyueqi2' && !isDead(m.id));
    return !!main && main.id !== s7Master;
  }
  function s7MasterPath(): string | null {
    if (!s7Master) return null;
    return CHAR_PATH[s7Master] ?? null;
  }
  /** 师父命途分支：附加伤害系（智识/毁灭/巡猎/记忆/欢愉）或削韧系（同谐/虚无/存护/丰饶） */
  function s7MasterBranch(): 'extra' | 'break' | null {
    const p = s7MasterPath();
    if (!p) return null;
    if (p === 'Mage' || p === 'Warrior' || p === 'Rogue' || p === 'Memory' || p === 'Elation') return 'extra';
    return 'break';
  }
  /** 还原/施加师父速度 +10%（真实速度） */
  function s7RestoreMasterSpeed(): void {
    if (s7MasterSpeedTarget && tl.has(s7MasterSpeedTarget)) {
      tl.speedChange(s7MasterSpeedTarget, s7MasterSpeedBase);
    }
    s7MasterSpeedTarget = null;
    s7MasterSpeedBase = 0;
  }
  function s7SetMaster(target: CharId | null): void {
    s7RestoreMasterSpeed();
    s7Master = target;
    if (target && tl.has(target) && !isDead(target)) {
      const cur = tl.getUnit(target).speed;
      s7MasterSpeedTarget = target;
      s7MasterSpeedBase = cur;
      tl.speedChange(target, cur * (1 + TRACE.sanyueqi2.masterSpeedPct));
    }
    s7ApplySelfSpeed();
  }
  /** E1：场上存在【师父】时三月七自身速度 +10%（真实速度） */
  let s7SelfSpeedBase = 0;
  let s7SelfSpeedOn = false;
  function s7ApplySelfSpeed(): void {
    if (!tl.has('sanyueqi2')) return;
    const shouldOn = s7Eidolon() >= 1 && !!s7Master && !isDead(s7Master);
    if (shouldOn === s7SelfSpeedOn) return;
    const cur = tl.getUnit('sanyueqi2').speed;
    if (shouldOn) {
      s7SelfSpeedBase = cur;
      tl.speedChange('sanyueqi2', cur * (1 + TRACE.sanyueqi2.e1SpeedPct));
      s7SelfSpeedOn = true;
    } else {
      tl.speedChange('sanyueqi2', s7SelfSpeedBase);
      s7SelfSpeedOn = false;
    }
  }
  /** 行迹 07【玲珑】：目标弱点集合含【师父】属性 → 该次削韧按全额计（ignoreWeakness）
   *（「击破按虚数击破」无需额外处理：三月七自身属性即虚数） */
  function s7IgnoreWeakness(target: MonsterId): boolean {
    if (!s7Alive() || !s7Master || isDead(s7Master)) return false;
    return monsters[target].weaknesses.has(panelOf(s7Master).element);
  }
  /** 战技附加伤害（元素随师父、双暴/增伤归三月七、削韧 0）；每段触发 1 次 */
  function s7ExtraHit(target: MonsterId, notes: string[]): number[] {
    if (!s7Alive() || s7MasterBranch() !== 'extra') return [];
    const p = panelOf('sanyueqi2');
    const masterPanel = s7Master ? panelOf(s7Master) : p;
    const mult = skillParams('122402', levelsOf('sanyueqi2').skill)[1] ?? TRACE.sanyueqi2.extraDmgPct;
    const seqs = dealAttack({
      source: 'sanyueqi2',
      skillCode: 'sanyueqi2.extra',
      // 「基于【师父】属性的附加伤害」：元素取师父，强度取三月七
      element: masterPanel.element,
      level: p.level,
      statValue: p.attack,
      multiplier: mult,
      damageBonusExtra: s7DmgBonus(),
      critRate: p.critRate,
      critDmg: p.critDmg,
      stance: 0,
      attackerBuffs: holderOf('sanyueqi2'),
      target,
      attackKind: 'followup',
    });
    if (seqs.length > 0) notes.push('s7Extra');
    return seqs;
  }
  /** 充能 ≥7 窗口内的 +80% 增伤（增伤区加算，全部伤害） */
  function s7DmgBonus(): number {
    if (!s7Alive()) return 0;
    return s7Charge >= TRACE.sanyueqi2.chargeNeed ? TRACE.sanyueqi2.enhancedDmgBonus : 0;
  }
  /** 充能获取（上限 10）；满阈值后由调用方决定是否立即行动 */
  function s7GainCharge(n: number, notes?: string[], label?: string): void {
    if (!s7Alive() || n <= 0) return;
    const before = s7Charge;
    s7Charge = Math.min(TRACE.sanyueqi2.chargeMax, s7Charge + n);
    if (s7Charge > before && notes && label) notes.push(label);
  }
  /** E2 追击：师父普攻/战技命中后，对主目标 60%，随后 +1 充能（每三月七回合 1 次） */
  function s7E2Followup(target: MonsterId, notes: string[]): number[] {
    if (s7Eidolon() < 2 || s7E2Used || !s7Alive()) return [];
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    let main = target;
    if (monsters[main].hp <= 0) main = alive[0];
    const p = panelOf('sanyueqi2');
    s7E2Used = true;
    const seqs: number[] = [];
    try {
      relicFollowupStart('sanyueqi2');
      seqs.push(
        ...dealAttack({
          source: 'sanyueqi2',
          skillCode: 'sanyueqi2.e2',
          element: p.element,
          level: p.level,
          statValue: p.attack,
          multiplier: TRACE.sanyueqi2.e2Mult,
          damageBonusExtra: s7DmgBonus(),
          critRate: p.critRate,
          critDmg: p.critDmg,
          stance: 15,
          attackerBuffs: holderOf('sanyueqi2'),
          target: main,
          attackKind: 'followup',
          ...(s7IgnoreWeakness(main) ? { ignoreWeakness: true } : {}),
        }),
      );
    } finally {
      relicFollowupEnd();
    }
    if (seqs.length > 0) {
      notes.push('s7E2');
      seqs.push(...s7ExtraHit(main, notes));
      s7GainCharge(TRACE.sanyueqi2.e2Charge, notes, 's7Charge');
    }
    return seqs;
  }
  /** 师父阵亡/三月七阵亡后的状态同步 */
  function s7SyncPresence(): void {
    if (!s7Alive()) {
      s7RestoreMasterSpeed();
      s7Master = null;
      s7Charge = 0;
      s7UltBuff = false;
      s7E6Ready = false;
      s7SelfSpeedOn = false;
      return;
    }
    if (s7Master && isDead(s7Master)) {
      s7RestoreMasterSpeed();
      s7Master = null;
    }
    s7ApplySelfSpeed();
  }

  // ===== 不死途 1504 helpers（2026-10-29 接入；裁定见 docs/AGENTS-rogue.md §14） =====
  function asEidolon(): number {
    return members.find((m) => m.id === 'ashveil')?.eidolonLevel ?? 0;
  }
  function asGreedCap(): number {
    return asEidolon() >= 2 ? TRACE.ashveil.e2GreedMax : TRACE.ashveil.greedMax;
  }
  /** 加【婪酣】层数（同时累加到「累计获得」；上限只看当前层数） */
  function asAddGreed(n: number, notes?: string[], label?: string): void {
    if (!ids.has('ashveil') || n <= 0) return;
    asGreed = Math.min(asGreedCap(), asGreed + n);
    asGreedTotal = Math.min(TRACE.ashveil.e6Max, asGreedTotal + n);
    if (notes && label) notes.push(label);
  }
  /** 只清【饲饵】标记（buff + 局部状态） */
  function asClearBaitMarks(): void {
    for (const id of MONSTER_IDS) {
      removeBuffInstance(monsters[id].buffs, { key: 'asBait', source: 'ashveil', labelKey: 'asBait' });
      removeBuffInstance(monsters[id].buffs, { key: 'asBaitDefDown', source: 'ashveil', labelKey: 'asBaitDef' });
      removeBuffInstance(monsters[id].buffs, { key: 'asBaitResDown', source: 'ashveil', labelKey: 'asBaitRes' });
    }
    asBait = undefined;
  }
  /** 挂【饲饵】：覆盖旧目标；同时给全体敌人挂减防/降抗（有饵期间生效，饵消失即移除） */
  function asApplyBait(target: MonsterId, notes?: string[]): void {
    if (!ids.has('ashveil') || monsters[target].hp <= 0) return;
    asClearBaitMarks();
    lcMonsterBuff(target, 'asBait', 0, 'asBait', 'ashveil', -1);
    asBait = target;
    const lvS = levelsOf('ashveil').skill;
    const defDown = skillParams('150402', lvS)[3] ?? TRACE.ashveil.skillDefDown;
    for (const id of MONSTER_IDS) {
      if (monsters[id].hp <= 0) continue;
      lcMonsterBuff(id, 'asBaitDefDown', defDown, 'asBaitDef', 'ashveil', -1);
      if (asEidolon() >= 6) {
        lcMonsterBuff(id, 'asBaitResDown', TRACE.ashveil.e6ResDown, 'asBaitRes', 'ashveil', -1);
      }
    }
    notes?.push('asBait');
  }
  /** 场上无【饲饵】时自动补：当前 HP 最低的存活敌人 */
  function asEnsureBait(notes?: string[]): void {
    if (!ids.has('ashveil') || isDead('ashveil')) return;
    if (asBait !== undefined && monsters[asBait].hp > 0) return;
    const alive = aliveMonsters();
    if (alive.length === 0) return;
    let lowest = alive[0];
    for (const id of alive) {
      if (monsters[id].hp < monsters[lowest].hp) lowest = id;
    }
    asApplyBait(lowest, notes);
  }
  /** 天赋追击倍率（p4=2.0） */
  function asFollowMult(): number {
    return skillParams('150404', levelsOf('ashveil').talent)[3] ?? 2;
  }
  /** 行迹 07：追击增伤 +80%，每层【婪酣】额外 +10%（增伤区加算） */
  function asFollowDmgBonus(): number {
    if (!ids.has('ashveil')) return 0;
    return TRACE.ashveil.p07FollowDmg + TRACE.ashveil.p07GreedPer * asGreed;
  }
  /** E6：每累计获得 1 层婪酣 → 伤害 +4%（上限 30 层） */
  function asE6DmgBonus(): number {
    if (!ids.has('ashveil') || asEidolon() < 6) return 0;
    return TRACE.ashveil.e6DmgPer * Math.min(TRACE.ashveil.e6Max, asGreedTotal);
  }
  /** 天赋追击（200%；强化版不消耗充能；均吃行迹 07 / E6 增伤） */
  function asFollowup(target: MonsterId | undefined, enhanced: boolean, notes: string[]): number[] {
    if (!ids.has('ashveil')) return [];
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    let main = target ?? asBait ?? alive[0];
    if (monsters[main].hp <= 0) main = asBait ?? alive[0];
    if (monsters[main].hp <= 0) main = alive[0];
    const p = panelOf('ashveil');
    const seqs: number[] = [];
    try {
      relicFollowupStart('ashveil');
      seqs.push(
        ...dealAttack({
          source: 'ashveil',
          skillCode: enhanced ? 'ashveil.followEnhanced' : 'ashveil.talent',
          element: p.element,
          level: p.level,
          statValue: p.attack,
          multiplier: asFollowMult(),
          damageBonusExtra: asFollowDmgBonus() + asE6DmgBonus(),
          critRate: p.critRate,
          critDmg: p.critDmg,
          stance: stanceOf('150404', levelsOf('ashveil').talent),
          attackerBuffs: holderOf('ashveil'),
          target: main,
          attackKind: 'followup',
        }),
      );
    } finally {
      relicFollowupEnd();
    }
    if (seqs.length > 0) notes.push(enhanced ? 'asFollowEnhanced' : 'asFollow');
    return seqs;
  }
  /** 【饲饵】受我方其他目标攻击后：固定回 8 能 → 消耗 1 充能 → 追击 → +2 层婪酣 */
  function asOnBaitHit(target: MonsterId, notes: string[], seqs: number[]): void {
    if (!ids.has('ashveil') || isDead('ashveil')) return;
    if (asBait !== target || monsters[target].hp <= 0) return;
    if (asCharge < TRACE.ashveil.chargeCost) return;
    asCharge -= TRACE.ashveil.chargeCost;
    gainEnergyRaw('ashveil', TRACE.ashveil.energyPerProc);
    notes.push('asEnergy');
    seqs.push(...asFollowup(target, false, notes));
    asAddGreed(TRACE.ashveil.greedPerFollow, notes, 'asGreed');
  }
  /** 每次事件前的存在性同步 */
  function asSyncPresence(): void {
    if (!ids.has('ashveil') || isDead('ashveil')) {
      asClearBaitMarks();
      asGreed = 0;
      asGreedTotal = 0;
      return;
    }
    if (asBait !== undefined && monsters[asBait].hp <= 0) asClearBaitMarks();
  }

  // ===== 飞霄 1220 helpers（2026-10-29 接入；裁定见 docs/AGENTS-rogue.md §11） =====
  function feixiaoEidolon(): number {
    return members.find((m) => m.id === 'feixiao')?.eidolonLevel ?? 0;
  }
  /** 【飞黄】同步到展示层 energy（真实资源是 feixiaoFeihuang） */
  function feixiaoSyncEnergy(): void {
    if (ids.has('feixiao')) energy.feixiao = feixiaoFeihuang;
  }
  /** 加【飞黄】（不吃充能效率；上限 12）；返回是否真的增加 */
  function feixiaoAddFeihuang(n: number, notes?: string[], label?: string): boolean {
    if (!ids.has('feixiao') || n <= 0) return false;
    const before = feixiaoFeihuang;
    feixiaoFeihuang = Math.min(TRACE.feixiao.feihuangMax, feixiaoFeihuang + n);
    feixiaoSyncEnergy();
    if (feixiaoFeihuang > before) {
      if (notes && label) notes.push(label);
      return true;
    }
    return false;
  }
  /** 天赋追击倍率（p1=1.1；E6 ×(1+1.4)=×2.4 相对提高） */
  function feixiaoFollowMult(): number {
    const t = skillParams('122004', levelsOf('feixiao').talent);
    const base = t[0] ?? 1.1;
    return feixiaoEidolon() >= 6 ? base * (1 + TRACE.feixiao.e6FollowMultAdd) : base;
  }
  /** 天赋追击：对目标 110%（E6 264%）；攻击后附加 point07 暴伤、E4 削韧×2/加速、+60% 自身增伤 */
  function feixiaoTalentFollowup(target: MonsterId | undefined, notes: string[]): number[] {
    if (!ids.has('feixiao') || isDead('feixiao')) return [];
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    let main = target ?? alive[0];
    if (monsters[main].hp <= 0) main = alive[0];
    const p = panelOf('feixiao');
    const t = skillParams('122004', levelsOf('feixiao').talent);
    const eid = feixiaoEidolon();
    const seqs: number[] = [];
    try {
      relicFollowupStart('feixiao');
      seqs.push(
        ...dealAttack({
          source: 'feixiao',
          skillCode: 'feixiao.talent',
          element: p.element,
          level: p.level,
          statValue: p.attack,
          multiplier: feixiaoFollowMult(),
          // E6「天赋追击同时视为终结技伤害」→ 吃 E6 的终结技全属性抗穿 +20%
          damageBonusExtra: 0,
          zoneExtras: eid >= 6 ? { resPenetration: TRACE.feixiao.e6ResPen } : undefined,
          critRate: p.critRate,
          critDmg: p.critDmg + TRACE.feixiao.p07FollowCritDmg,
          stance: Math.round(
            stanceOf('122004', levelsOf('feixiao').talent) *
              (eid >= 4 ? TRACE.feixiao.e4StanceMul : 1),
          ),
          attackerBuffs: holderOf('feixiao'),
          target: main,
          attackKind: 'followup',
        }),
      );
    } finally {
      relicFollowupEnd();
    }
    if (seqs.length === 0) return seqs;
    notes.push('feixiaoTalent');
    // 天赋：发动后自身增伤 +60%，2 回合（刷新不叠层）
    removeBuffInstance(holderOf('feixiao'), {
      key: 'damageBonus',
      source: 'feixiao',
      labelKey: 'feixiaoTalentBuff',
    });
    addBuff(holderOf('feixiao'), {
      key: 'damageBonus',
      source: 'feixiao',
      labelKey: 'feixiaoTalentBuff',
      value: t[4] ?? 0.6,
      stacks: 1,
      duration: Math.round(t[5] ?? 2),
      tick: 'holderEnd',
    });
    // E4：发动时自身速度 +8%，2 回合（真实速度；记基础值，到期还原，不叠加）
    if (eid >= 4 && tl.has('feixiao')) {
      if (!feixiaoE4On) {
        feixiaoE4SpeedBase = tl.getUnit('feixiao').speed;
        feixiaoE4On = true;
        tl.speedChange('feixiao', feixiaoE4SpeedBase * (1 + TRACE.feixiao.e4SpeedPct));
      }
      feixiaoE4Left = TRACE.feixiao.e4Turns;
      addBuff(holderOf('feixiao'), {
        key: 'speedPct',
        source: 'feixiao',
        labelKey: 'feixiaoE4Speed',
        value: TRACE.feixiao.e4SpeedPct,
        stacks: 1,
        duration: TRACE.feixiao.e4Turns,
        tick: 'holderEnd',
      });
      notes.push('feixiaoE4');
    }
    feixiaoLastTurnProcs = true;
    // E2：追击也攒飞黄（每飞霄回合最多 6 次）
    if (eid >= 2 && feixiaoE2Count < TRACE.feixiao.e2PerTurn) {
      feixiaoE2Count += 1;
      feixiaoAddFeihuang(1, notes, 'feixiaoE2');
    }
    return seqs;
  }
  /** 秘技「岚身」：每个波次开始对敌方全体造成 200%+100%×(存活敌数−1) 风伤（上限 1000%），必定暴击 */
  function feixiaoTechWave(notes: string[]): number[] {
    if (!ids.has('feixiao') || isDead('feixiao')) return [];
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    const tp = skillParams('122007', 1);
    const base = tp[2] ?? 2;
    const perExtra = tp[3] ?? 1;
    const cap = tp[5] ?? TRACE.feixiao.techMaxMult;
    const mult = Math.min(cap, base + perExtra * (alive.length - 1));
    const p = panelOf('feixiao');
    const seqs: number[] = [];
    for (const target of alive) {
      seqs.push(
        ...dealAttack({
          source: 'feixiao',
          skillCode: 'feixiao.tech',
          element: p.element,
          level: p.level,
          statValue: p.attack,
          multiplier: mult,
          damageBonusExtra: 0,
          // 必定暴击：暴率按 100% → crit 因子 = 1 + 暴伤
          critRate: 1,
          critDmg: p.critDmg,
          stance: 0,
          attackerBuffs: holderOf('feixiao'),
          target,
        }),
      );
    }
    if (seqs.length > 0) notes.push('feixiaoTech');
    return seqs;
  }
  /** 飞霄回合开始：重置天赋/ E2 计数；行迹 06 上一回合未触发追击则「攻击计数」+1 */
  function feixiaoTurnStart(notes?: string[]): void {
    if (!ids.has('feixiao')) return;
    if (!feixiaoLastTurnProcs) {
      feixiaoAttackCount += 1;
      while (feixiaoAttackCount >= TRACE.feixiao.talentAttackPer) {
        feixiaoAttackCount -= TRACE.feixiao.talentAttackPer;
        feixiaoAddFeihuang(1, notes, 'feixiaoP06');
      }
    }
    feixiaoLastTurnProcs = false;
    feixiaoTalentUsed = false;
    feixiaoE2Count = 0;
    // E4 速度窗口按飞霄自身回合递减，到期还原基础速度（不叠加、不遗留）
    if (feixiaoE4On && feixiaoE4Left > 0) {
      feixiaoE4Left -= 1;
      if (feixiaoE4Left <= 0 && tl.has('feixiao')) {
        tl.speedChange('feixiao', feixiaoE4SpeedBase);
        feixiaoE4On = false;
      }
    }
  }

  // ===== 毁灭最终批 1408 白厄 helpers =====
  function phainonEidolon(): number {
    return members.find((m) => m.id === 'phainon')?.eidolonLevel ?? 0;
  }
  function phainonSyncEnergy(): void {
    if (ids.has('phainon')) energy.phainon = phainonSeed;
  }
  function phainonAddSeed(n: number, notes?: string[], label?: string): void {
    if (!ids.has('phainon') || n <= 0) return;
    const cap =
      phainonEidolon() >= 6
        ? Number.POSITIVE_INFINITY
        : TRACE.phainon.seedNeed + TRACE.phainon.seedOverflow;
    const before = phainonSeed;
    phainonSeed = Math.min(cap, phainonSeed + n);
    phainonSyncEnergy();
    if (notes && label && phainonSeed > before) notes.push(label);
  }
  function phainonSyncP08(): void {
    const h = holderOf('phainon');
    removeBuffInstance(h, { key: 'atkPct', source: 'phainon', labelKey: 'phainonP08' });
    if (phainonP08Stacks > 0) {
      addBuff(h, {
        key: 'atkPct',
        source: 'phainon',
        labelKey: 'phainonP08',
        value: TRACE.phainon.p08Atk,
        stacks: phainonP08Stacks,
        duration: -1,
        tick: 'permanent',
      });
    }
  }
  function phainonGainDamage(n: number): void {
    phainonDamage = Math.min(TRACE.phainon.damageMax, phainonDamage + n);
  }
  function phainonOnAllySupport(target: CombatUnitId, source: CombatUnitId, notes?: string[]): void {
    if (!ids.has('phainon') || target !== 'phainon' || source === 'phainon') return;
    if (isDead('phainon')) return;
    if (phainonP07Turn !== tl.round) {
      phainonP07Turn = tl.round;
      addBuff(holderOf('phainon'), {
        key: 'damageBonus',
        source: 'phainon',
        labelKey: 'phainonP07',
        value: TRACE.phainon.p07Dmg,
        stacks: 1,
        duration: TRACE.phainon.p07Turns,
        tick: 'holderEnd',
      });
      notes?.push('phainonP07');
    }
  }
  function phainonOnTargeted(notes?: string[], teamCrit = true): void {
    if (!ids.has('phainon') || isDead('phainon')) return;
    phainonAddSeed(TRACE.phainon.seedOnTargeted, notes, 'phainonTargeted');
    if (teamCrit && !phainonForm) {
      addBuff(holderOf('phainon'), {
        key: 'critDmg',
        source: 'phainon',
        labelKey: 'phainonTeamCrit',
        value: TRACE.phainon.teamCritDmg,
        stacks: 1,
        duration: TRACE.phainon.teamCritDmgTurns,
        tick: 'holderEnd',
      });
    }
  }
  function phainonHit(
    skillCode: string,
    target: MonsterId,
    multiplier: number,
    stance: number,
    opts?: {
      kind?: 'basic' | 'skill' | 'ult' | 'followup';
      bonus?: number;
      /** 属性覆写：默认物理；1141521【永续的燃烧】的附加伤害是**火**属性 */
      element?: Element;
    },
  ): number[] {
    const p = panelOf('phainon');
    const resPen =
      phainonForm && phainonEidolon() >= 2 ? TRACE.phainon.e2ResPen : 0;
    return dealAttack({
      source: 'phainon',
      skillCode,
      element: opts?.element ?? 'Physical',
      level: p.level,
      statValue: p.attack,
      multiplier,
      critRate: p.critRate,
      critDmg: p.critDmg,
      stance,
      attackerBuffs: attackerHolder('phainon'),
      target,
      attackKind: opts?.kind,
      damageBonusExtra: opts?.bonus ?? 0,
      zoneExtras: resPen > 0 ? { resPenetration: resPen } : undefined,
    });
  }
  function phainonRecalcExtraSpeed(): void {
    if (!phainonForm || !tl.has('phainonExtra')) return;
    const ratio =
      phainonEidolon() >= 1 ? TRACE.phainon.e1Speed : TRACE.phainon.extraSpeed;
    const killBonus = Math.min(
      TRACE.phainon.e1KillMax,
      phainonKillCount * TRACE.phainon.e1KillBonus,
    );
    tl.speedChange('phainonExtra', panelOf('phainon').speed * ratio * (1 + killBonus));
  }
  function phainonOnKill(): void {
    if (!phainonForm) return;
    phainonKillCount += 1;
    phainonRecalcExtraSpeed();
  }
  function phainonTechSeqs(): number[] {
    const p = skillParams('140807', 1);
    const seqs: number[] = [];
    for (const t of aliveMonsters()) {
      seqs.push(...phainonHit('phainon.tech', t, p[0], stanceOf('140807', 1)));
    }
    return seqs;
  }
  function phainonHealSelf(notes?: string[]): void {
    if (!phainonForm) return;
    healUnit(
      'phainon',
      maxHpOf('phainon') * TRACE.phainon.formHeal,
      'phainon',
      notes,
      true,
    );
  }
  function phainonExtendBuffs(id: CharId): void {
    for (const b of holderOf(id).buffs) {
      if (b.duration > 0) b.duration += 1;
    }
  }
  function phainonFinalStrike(remaining: number): number[] {
    const alive = aliveMonsters();
    if (alive.length === 0) return [];
    const total = Math.max(
      0,
      TRACE.phainon.finalMult * (1 - TRACE.phainon.finalDecay * remaining),
    );
    const per = total / alive.length;
    const seqs: number[] = [];
    for (const t of alive) seqs.push(...phainonHit('phainon.final', t, per, 0, { kind: 'ult' }));
    return seqs;
  }
  function phainonStartForm(notes: string[]): void {
    if (!ids.has('phainon') || phainonForm) return;
    phainonForm = true;
    phainonFatalUsed = false;
    phainonFatalPending = false;
    phainonDamage = TRACE.phainon.formSeed;
    phainonSoulfire = 0;
    phainonSoulfireExpected = 0;
    phainonSoulfireSeen = 0;
    phainonExtraLeft = TRACE.phainon.extraTurns;
    phainonSeed = Math.max(0, phainonSeed - TRACE.phainon.seedNeed);
    phainonSyncEnergy();
    // 1141521【永续的燃烧】变身时生效：暴击率 +#1；【火种】超过 #5 的每 1 点暴伤 +#6（上限 #7）。
    // 注意此处 phainonSeed 已扣掉变身消耗的 12 点 → 余量正好是「超过 #5」的部分。
    if (phainonBurn && phainonBurnP.length > 0) {
      const pb = phainonBurnP;
      addBuff(holderOf('phainon'), {
        key: 'critRate',
        source: 'phainon',
        labelKey: 'phainonBurnCr',
        value: pb[0] ?? 0,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
      });
      const excess = Math.max(0, phainonSeed - (pb[4] ?? 0));
      const cd = Math.min(pb[6] ?? 0, excess * (pb[5] ?? 0));
      if (cd > 0) {
        addBuff(holderOf('phainon'), {
          key: 'critDmg',
          source: 'phainon',
          labelKey: 'phainonBurnCd',
          value: cd,
          stacks: 1,
          duration: -1,
          tick: 'permanent',
        });
      }
      notes.push('phainonBurn');
    }
    // 140805：若终结技插入在我方目标回合，延长该目标全部增益 1 回合并结束本回合
    const pending = tl.pendingId();
    if (pending && pending !== 'phainon' && ids.has(pending as CharId) && !isDead(pending)) {
      phainonExtendBuffs(pending as CharId);
    }
    // 队友完全离场（保存 av/order/speed），白厄本体也离开常态跑道
    for (const m of members) {
      const unit = tl.has(m.id) ? tl.getUnit(m.id) : null;
      if (unit) {
        // 终结技若插在该队友回合，延长增益后结束其回合（回归时按新回合起算）
        const av = m.id === pending ? 10000 / unit.speed : unit.av;
        phainonSavedUnits.set(m.id, { av, order: unit.order, speed: unit.speed });
        tl.removeUnit(m.id);
      }
      if (m.id !== 'phainon') phainonExiled.add(m.id);
    }
    // 境界【时墟铁墓】：敌方全体常驻物理弱点
    for (const mid of MONSTER_IDS) {
      const mon = monsters[mid];
      if (!mon) continue;
      phainonSavedWeak.set(mid, new Set(mon.weaknesses));
      mon.weaknesses.add('Physical');
    }
    // 变身天赋：攻击 +80%；当前生命与上限同比放大 270%
    addBuff(holderOf('phainon'), {
      key: 'atkPct',
      source: 'phainon',
      labelKey: 'phainonFormAtk',
      value: TRACE.phainon.formAtk,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
    });
    memberHp.phainon = Math.max(1, (memberHp.phainon ?? panelOf('phainon').hp) * (1 + TRACE.phainon.formHp));
    phainonExiled.delete('phainon');
    const ratio =
      phainonEidolon() >= 1 ? TRACE.phainon.e1Speed : TRACE.phainon.extraSpeed;
    const killBonus = Math.min(
      TRACE.phainon.e1KillMax,
      phainonKillCount * TRACE.phainon.e1KillBonus,
    );
    const speed = panelOf('phainon').speed * ratio * (1 + killBonus);
    tl.addUnit({ id: 'phainonExtra', side: 'ally', speed, order: members.length + 10 });
    notes.push('phainonForm');
  }
  function phainonEndForm(notes: string[]): void {
    if (!phainonForm) return;
    phainonForm = false;
    if (tl.has('phainonExtra')) tl.removeUnit('phainonExtra');
    removeBuffInstance(holderOf('phainon'), {
      key: 'atkPct',
      source: 'phainon',
      labelKey: 'phainonFormAtk',
    });
    // 1141521【永续的燃烧】：变身结束清掉暴率/暴伤两实例（正常情况下无限刷新不会走到这里）
    removeBuffInstance(holderOf('phainon'), {
      key: 'critRate',
      source: 'phainon',
      labelKey: 'phainonBurnCr',
    });
    removeBuffInstance(holderOf('phainon'), {
      key: 'critDmg',
      source: 'phainon',
      labelKey: 'phainonBurnCd',
    });
    // 生命上限还原（当前生命同比缩回，至少 1）
    memberHp.phainon = Math.max(1, (memberHp.phainon ?? 1) / (1 + TRACE.phainon.formHp));
    // 队友回归
    for (const [id, saved] of phainonSavedUnits) {
      phainonExiled.delete(id);
      if (!tl.has(id) && !isDead(id)) {
        tl.addUnit({ id, side: 'ally', speed: saved.speed, initialAv: saved.av, order: saved.order });
      }
    }
    phainonSavedUnits.clear();
    // 恢复敌方原弱点
    for (const [mid, weak] of phainonSavedWeak) {
      const mon = monsters[mid];
      if (!mon) continue;
      mon.weaknesses.clear();
      for (const el of weak) mon.weaknesses.add(el);
    }
    phainonSavedWeak.clear();
    phainonSoulfire = 0;
    phainonSoulfireExpected = 0;
    phainonSoulfireSeen = 0;
    phainonExtraLeft = 0;
    // point06 变身结束 +3 火种
    phainonAddSeed(TRACE.phainon.p06End, notes, 'phainonP06End');
    // point08 变身结束攻击 +50%，最多 2 层
    phainonP08Stacks = Math.min(TRACE.phainon.p08Max, phainonP08Stacks + 1);
    phainonSyncP08();
    notes.push('phainonP08');
    // 全队速度 +20% 1 回合
    for (const m of members) {
      if (isDead(m.id)) continue;
      harmonyApplySpeed(m.id, 1 + TRACE.phainon.endSpeed, 0, 1);
    }
    notes.push('phainonEnd');
  }
  function phainon808(notes: string[]): number[] {
    const p = skillParams('140808', levelsOf('phainon').basic);
    const main = resolveMain();
    const stance = stanceOf('140808', levelsOf('phainon').basic);
    const seqs = phainonHit('phainon.skill808', main, p[0], stance, { kind: 'skill' });
    for (const adj of resolveAdjacent(main)) {
      seqs.push(
        ...phainonHit('phainon.skill808', adj, p[1], Math.round((stance * 2) / 3), {
          kind: 'skill',
        }),
      );
    }
    phainonGainDamage(2);
    notes.push('phainon808');
    phainonHealSelf(notes);
    return seqs;
  }
  function phainon809(notes: string[]): void {
    const alive = aliveMonsters();
    phainonGainDamage(alive.length);
    phainonSoulfire += 1 + (phainonEidolon() >= 4 ? TRACE.phainon.e4Extra : 0);
    phainonSoulfireExpected = alive.length;
    phainonSoulfireSeen = 0;
    notes.push('phainon809');
    for (const t of alive) tl.instantAction(t);
  }
  function phainonCounter(): number[] {    const stacks = phainonSoulfire;
    if (!phainonForm || stacks <= 0) return [];
    const p = skillParams('140809', levelsOf('phainon').skill);
    const mul = 1 + p[4] * stacks;
    const alive = aliveMonsters();
    const seqs: number[] = [];
    for (const t of alive) {
      seqs.push(...phainonHit('phainon.counter', t, p[0] * mul, 0, { kind: 'skill' }));
    }
    const extraHits = Math.max(0, Math.round(p[2]));
    for (let i = 0; i < extraHits && alive.length > 0; i += 1) {
      const t = alive[Math.floor(rand01() * alive.length)];
      seqs.push(...phainonHit('phainon.counter', t, p[3] * mul, 0, { kind: 'skill' }));
    }
    phainonSoulfire = 0;
    phainonSoulfireExpected = 0;
    phainonSoulfireSeen = 0;
    phainonHealSelf();
    return seqs;
  }
  function phainon811(notes: string[]): number[] {
    const p = skillParams('140811', levelsOf('phainon').skill);
    const maxPoints = Math.max(0, Math.round(p[3]));
    const hitsPer = Math.max(0, Math.round(p[2]));
    const use = Math.min(maxPoints, phainonDamage);
    phainonDamage = Math.max(0, phainonDamage - use);
    const alive = aliveMonsters();
    const seqs: number[] = [];
    for (let point = 0; point < use; point += 1) {
      for (let i = 0; i < hitsPer && alive.length > 0; i += 1) {
        const t = alive[Math.floor(rand01() * alive.length)];
        seqs.push(...phainonHit('phainon.skill811', t, p[1], 0, { kind: 'skill' }));
      }
    }
    if (use >= maxPoints && alive.length > 0) {
      const per = p[0] / alive.length;
      for (const t of alive) {
        seqs.push(...phainonHit('phainon.skill811', t, per, 0, { kind: 'skill' }));
      }
      if (phainonEidolon() >= 2) {
        phainonExtraLeft += 1;
        notes.push('phainonE2');
      }
    }
    if (phainonEidolon() >= 6 && seqs.length > 0) {
      const total = seqs.reduce((acc, s) => acc + (hits[s]?.total ?? 0), 0);
      const candidates = aliveMonsters();
      if (candidates.length > 0 && total > 0) {
        const highest = candidates.reduce((a, b) => (monsters[a].hp >= monsters[b].hp ? a : b));
        seqs.push(
          pushHit(
            computeTrueDamage({ originalTotal: total, ratio: TRACE.phainon.e6True }),
            { source: 'phainon', skillCode: 'phainon.e6', target: highest, note: 'phainonE6' },
            'trueDamage',
          ),
        );
      }
    }
    notes.push('phainon811');
    phainonHealSelf(notes);
    return seqs;
  }
  /** 1141521【永续的燃烧】：施放攻击后 #3 次随机单体 #4% 攻击力**火**属性附加伤害（0 削韧） */
  function phainonBurnHits(): number[] {
    if (!phainonBurn || phainonBurnP.length === 0) return [];
    const n = Math.max(0, Math.round(phainonBurnP[2] ?? 0));
    const mult = phainonBurnP[3] ?? 0;
    const seqs: number[] = [];
    for (let i = 0; i < n; i += 1) {
      const alive = aliveMonsters();
      if (alive.length === 0) break;
      const t = alive[Math.floor(rand01() * alive.length)];
      seqs.push(...phainonHit('phainon.burn', t, mult, 0, { kind: 'skill', element: 'Fire' }));
    }
    return seqs;
  }
  function phainonRunExtraTurn(): void {
    if (!phainonForm || !tl.has('phainonExtra')) return;
    // 【永续的燃烧】#2：额外回合开始时消耗等同于当前生命值 15% 的生命（几何收敛，不至 0）
    if (phainonBurn && (phainonBurnP[1] ?? 0) > 0) {
      consumeHp('phainon', (memberHp.phainon ?? 0) * (phainonBurnP[1] ?? 0));
    }
    if (phainonExtraLeft <= 1 && phainonBurn) {
      // 【永续的燃烧】：额外回合耗尽 → **不结束变身**，刷新全部额外回合并获得 #9 点【毁伤】
      //（2026-11-05 用户裁定：按字面无限，由 rounds/maxTime 兜底）
      phainonExtraLeft = TRACE.phainon.extraTurns;
      phainonGainDamage(Math.round(phainonBurnP[8] ?? 0));
      record({
        time: tl.time,
        round: tl.round,
        kind: 'action',
        unitId: 'phainonExtra',
        action: 'skip',
        skillCode: 'phainon.burnRefresh',
        spAfter: sp,
        energyAfter: phainonSeed,
        note: ['phainonBurnRefresh'],
      });
      return;
    }
    if (phainonExtraLeft <= 1) {
      const notes = ['phainonFinal'];
      const seqs = phainonFinalStrike(0);
      record({
        time: tl.time,
        round: tl.round,
        kind: 'action',
        unitId: 'phainonExtra',
        action: 'ult',
        skillCode: 'phainon.final',
        spAfter: sp,
        energyAfter: phainonSeed,
        note: notes,
        hitSeqs: seqs.length ? seqs : undefined,
      });
      phainonEndForm(notes);
      if (phainonSeed > 0) notes.push('phainonSeed');
      return;
    }
    if (phainonSoulfire > 0) {
      const notes = ['phainonCounter'];
      const seqs = phainonCounter();
      // 【永续的燃烧】「施放攻击后」：反击也是一次攻击 → 追加附伤
      seqs.push(...phainonBurnHits());
      record({
        time: tl.time,
        round: tl.round,
        kind: 'action',
        unitId: 'phainonExtra',
        action: 'skill',
        skillCode: 'phainon.counter',
        spAfter: sp,
        energyAfter: phainonSeed,
        note: notes,
        hitSeqs: seqs.length ? seqs : undefined,
      });
    }
    const notes: string[] = [];
    let skillCode: string;
    let seqs: number[] = [];
    if (phainonDamage >= 4) {
      skillCode = 'phainon.skill811';
      seqs = phainon811(notes);
      phainonExtraLeft -= 1;
    } else if (phainonDamage > 0) {
      skillCode = 'phainon.skill809';
      phainon809(notes);
      phainonExtraLeft -= 1;
    } else {
      skillCode = 'phainon.skill808';
      seqs = phainon808(notes);
      phainonExtraLeft -= 1;
    }
    // 【永续的燃烧】「施放攻击后」：811/808 是攻击（809 是标记，不触发附伤）
    if (skillCode !== 'phainon.skill809') seqs.push(...phainonBurnHits());
    record({
      time: tl.time,
      round: tl.round,
      kind: 'action',
      unitId: 'phainonExtra',
      action: 'skill',
      skillCode,
      spAfter: sp,
      energyAfter: phainonSeed,
      note: notes,
      hitSeqs: seqs.length ? seqs : undefined,
    });
  }
  function phainonTryFatal(notes: string[]): boolean {
    if (!phainonForm || phainonFatalUsed) return false;
    phainonFatalUsed = true;
    memberHp.phainon = Math.max(1, maxHpOf('phainon') * TRACE.phainon.fatalHeal);
    phainonFatalPending = true;
    notes.push('phainonFatal');
    return true;
  }
  function phainonRunFatalStrike(): void {
    if (!phainonFatalPending) return;
    phainonFatalPending = false;
    if (!phainonForm) return;
    const notes = ['phainonFatalStrike'];
    const seqs = phainonFinalStrike(Math.max(0, phainonExtraLeft - 1));
    record({
      time: tl.time,
      round: tl.round,
      kind: 'action',
      unitId: 'phainonExtra',
      action: 'ult',
      skillCode: 'phainon.final',
      spAfter: sp,
      energyAfter: phainonSeed,
      note: notes,
      hitSeqs: seqs.length ? seqs : undefined,
    });
    phainonEndForm(notes);
  }

  // ===== 毁灭第一批 1212 镜流 helpers =====
  function jingliuEidolon(): number {
    return members.find((x) => x.id === 'jingliu')?.eidolonLevel ?? 0;
  }
  function jingliuMaxStack(): number {
    return jingliuEidolon() >= 6 ? TRACE.jingliu.eidolon6MaxStack : TRACE.jingliu.maxStack;
  }
  function jingliuSetMoon(stacks: number): void {
    jingliuMoon = Math.max(0, stacks);
    const h = holderOf('jingliu');
    if (jingliuMoon <= 0) {
      removeBuffInstance(h, { key: 'critDmg', source: 'jingliu', labelKey: 'jingliuMoon' });
      return;
    }
    addBuff(h, {
      key: 'critDmg',
      value: TRACE.jingliu.moonCritDmg + (jingliuEidolon() >= 4 ? TRACE.jingliu.eidolon4MoonCritDmg : 0),
      stacks: jingliuMoon,
      duration: -1,
      tick: 'permanent',
      source: 'jingliu',
      labelKey: 'jingliuMoon',
    });
  }
  function jingliuEnterTranscend(): void {
    if (jingliuInTranscend) return;
    jingliuInTranscend = true;
    jingliuSyzygy = Math.min(
      jingliuMaxStack(),
      jingliuSyzygy +
        TRACE.jingliu.enterBonusStacks +
        (jingliuEidolon() >= 6 ? TRACE.jingliu.eidolon6EnterStacks : 0),
    );
    const h = holderOf('jingliu');
    addBuff(h, {
      key: 'critRate',
      value: TRACE.jingliu.critRate,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'jingliu',
      labelKey: 'jingliuTranscend',
    });
    addBuff(h, {
      key: 'effectRes',
      value: TRACE.jingliu.point06Res,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'jingliu',
      labelKey: 'jingliuP06Res',
    });
    if (jingliuEidolon() >= 6) {
      addBuff(h, {
        key: 'resPenetration',
        value: TRACE.jingliu.eidolon6ResPen,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
        source: 'jingliu',
        labelKey: 'jingliuE6Res',
      });
    }
    if (tl.has('jingliu')) tl.actionAdvance('jingliu', TRACE.jingliu.advance);
    warriorPendingNotes.push('jingliuTranscend');
  }
  function jingliuExitTranscend(): void {
    if (!jingliuInTranscend) return;
    jingliuInTranscend = false;
    const h = holderOf('jingliu');
    removeBuffInstance(h, { key: 'critRate', source: 'jingliu', labelKey: 'jingliuTranscend' });
    removeBuffInstance(h, { key: 'effectRes', source: 'jingliu', labelKey: 'jingliuP06Res' });
    removeBuffInstance(h, { key: 'resPenetration', source: 'jingliu', labelKey: 'jingliuE6Res' });
    removeBuffInstance(h, { key: 'critDmg', source: 'jingliu', labelKey: 'jingliuMoon' });
    jingliuMoon = 0;
    warriorPendingNotes.push('jingliuExit');
  }
  function jingliuAddSyzygy(n: number): void {
    if (n <= 0 || isDead('jingliu')) return;
    if (jingliuSyzygy >= jingliuMaxStack()) jingliuP08Pending = true;
    jingliuSyzygy = Math.min(jingliuMaxStack(), jingliuSyzygy + n);
    if (!jingliuInTranscend && jingliuSyzygy >= TRACE.jingliu.enterStacks) jingliuEnterTranscend();
  }
  function jingliuOnHpLoss(
    target: CharId | AllyUnitId,
    amount: number,
    opts?: { attackKey?: string },
  ): void {
    if (amount <= 0 || isDead('jingliu')) return;
    const key = opts?.attackKey ? `${opts.attackKey}|${target}` : '';
    if (jingliuInTranscend && jingliuMoon < TRACE.jingliu.moonMax) {
      if (!key || !jingliuMoonSeen.has(key)) {
        if (key) jingliuMoonSeen.add(key);
        jingliuSetMoon(jingliuMoon + 1);
      }
    }
    if (!key || !jingliuCountSeen.has(key)) {
      if (key) jingliuCountSeen.add(key);
      jingliuHpLossCount += 1;
      if (jingliuHpLossCount >= TRACE.jingliu.countThreshold) {
        jingliuHpLossCount = 0;
        jingliuAddSyzygy(1);
        warriorPendingNotes.push('jingliuCount');
      }
    }
  }
  function jingliuZoneExtras(): AttackSpec['zoneExtras'] | undefined {
    const defIgnore = jingliuP08Pending ? TRACE.jingliu.point08DefIgnore : 0;
    const resPenetration =
      jingliuInTranscend && jingliuEidolon() >= 6 ? TRACE.jingliu.eidolon6ResPen : 0;
    return defIgnore > 0 || resPenetration > 0 ? { defIgnore, resPenetration } : undefined;
  }
  function jingliuConsumeP08(): void {
    jingliuP08Pending = false;
  }
  function jingliuE1Pre(): void {
    if (jingliuEidolon() < 1) return;
    addBuff(holderOf('jingliu'), {
      key: 'critDmg',
      value: TRACE.jingliu.eidolon1CritDmg,
      stacks: 1,
      duration: 3,
      tick: 'holderEnd',
      source: 'jingliu',
      labelKey: 'jingliuE1',
    });
  }
  function jingliuE1Extra(
    skillCode: string,
    kind: 'skill' | 'ult',
    main: MonsterId,
    extras: AttackSpec['zoneExtras'] | undefined,
  ): number[] {
    if (jingliuEidolon() < 1) return [];
    const p = panelOf('jingliu');
    return dealAttack({
      source: 'jingliu',
      skillCode,
      element: p.element,
      level: p.level,
      statValue: maxHpOf('jingliu'),
      hpBased: true,
      multiplier: TRACE.jingliu.eidolon1ExtraHp,
      damageBonusExtra:
        kind === 'ult' && jingliuInTranscend ? TRACE.jingliu.point06UltDmg : 0,
      critRate: p.critRate,
      critDmg: p.critDmg,
      stance: 0,
      attackerBuffs: attackerHolder('jingliu'),
      target: main,
      attackKind: kind,
      zoneExtras: extras,
    });
  }
  function jingliuDrainAllies(): void {
    for (const m of members) {
      if (m.id === 'jingliu' || isDead(m.id)) continue;
      const cap = maxHpOf(m.id);
      const cur = memberHp[m.id] ?? cap;
      const amount = Math.min(Math.max(0, cur - 1), cap * TRACE.jingliu.drainPct);
      if (amount <= 0) continue;
      // 镜流吸取队友生命 = 「被我方目标消耗生命值」→ 走统一入口（触发 113 4pc 第二半边）
      const applied = consumeHp(m.id, amount, { keepHp: 1 });
      if (applied <= 0) continue;
      onHpLoss(m.id, applied, { attackKey: 'jingliu.enhanced' });
    }
  }

  // ===== 毁灭第一批 1404 万敌 helpers =====
  function mydeiEidolon(): number {
    return members.find((x) => x.id === 'mydei')?.eidolonLevel ?? 0;
  }
  function mydeiP08Init(): void {
    if (!ids.has('mydei')) return;
    const base = panelOf('mydei').hp;
    const count =
      Math.min(TRACE.mydei.point08MaxCount, Math.max(0, base - TRACE.mydei.point08HpThreshold)) / 100;
    mydeiP08Crit = count * TRACE.mydei.point08CritPer100;
    mydeiP08ChargeMult = count * TRACE.mydei.point08ChargePer100;
    mydeiP08Heal = count * TRACE.mydei.point08HealPer100;
  }
  function mydeiGodCost(): number {
    return mydeiEidolon() >= 6 ? TRACE.mydei.eidolon6GodSkillCost : TRACE.mydei.godSkillCost;
  }
  function mydeiAddCharge(points: number, opts?: { fromEnemy?: boolean }): void {
    if (mydeiNoCharge || points <= 0 || isDead('mydei')) return;
    const mult = opts?.fromEnemy ? 1 + mydeiP08ChargeMult : 1;
    mydeiCharge = Math.min(TRACE.mydei.chargeMax, mydeiCharge + points * mult);
    if (!mydeiBloodFeud && mydeiCharge >= TRACE.mydei.enterCharge) mydeiEnterBloodFeud();
    if (mydeiBloodFeud && mydeiCharge >= mydeiGodCost()) {
      mydeiCharge -= mydeiGodCost();
      mydeiExtraTurnPending = true;
      warriorPendingNotes.push('mydeiGodReady');
    }
  }
  function mydeiEnterBloodFeud(): void {
    if (mydeiBloodFeud || isDead('mydei')) return;
    const maxBefore = maxHpOf('mydei');
    addBuff(holderOf('mydei'), {
      key: 'maxHpFlat',
      value: maxBefore * TRACE.mydei.bloodFeudMaxHp,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'mydei',
      labelKey: 'mydeiBloodFeud',
    });
    mydeiBloodFeud = true;
    const newMax = maxHpOf('mydei');
    healUnit('mydei', newMax * TRACE.mydei.enterHeal, 'mydei', undefined, true);
    if (tl.has('mydei')) tl.actionAdvance('mydei', 1);
    warriorPendingNotes.push('mydeiBloodFeud');
  }
  function mydeiExitBloodFeud(): void {
    if (!mydeiBloodFeud) return;
    mydeiBloodFeud = false;
    mydeiCharge = 0;
    removeBuffInstance(holderOf('mydei'), {
      key: 'maxHpFlat',
      source: 'mydei',
      labelKey: 'mydeiBloodFeud',
    });
    clampHpToMax();
    warriorPendingNotes.push('mydeiBloodFeudExit');
  }
  function mydeiOnHpLoss(
    target: CharId | AllyUnitId,
    amount: number,
    opts?: { fromEnemy?: boolean },
  ): void {
    if (target !== 'mydei' || amount <= 0 || isDead('mydei')) return;
    mydeiAddCharge((amount / maxHpOf('mydei')) * 100, { fromEnemy: opts?.fromEnemy });
  }
  function mydeiOnHealed(actual: number): void {
    if (actual <= 0 || !mydeiBloodFeud || mydeiEidolon() < 2 || isDead('mydei')) return;
    const remaining = Math.max(0, TRACE.mydei.eidolon2ChargeCap - mydeiHealChargeUsed);
    const points = Math.min(
      remaining,
      (actual / maxHpOf('mydei')) * 100 * TRACE.mydei.eidolon2HealToCharge,
    );
    if (points <= 0) return;
    mydeiHealChargeUsed += points;
    mydeiAddCharge(points);
  }
  /** 毁灭三人：条件暴击加成（dealAttack / dealAttackEnemyUnit 共用） */
  function warriorCritBonus(src: string): { rate: number; dmg: number } {
    let rate = 0;
    let dmg = 0;
    if (src === 'blade' && bladeInHell() && bladeEidolon() >= 2) {
      rate += TRACE.blade.eidolon2CritRate;
    }
    if (src === 'mydei') {
      rate += mydeiP08Crit;
      if (mydeiBloodFeud && mydeiEidolon() >= 4) dmg += TRACE.mydei.eidolon4CritDmg;
    }
    return { rate, dmg };
  }
  /** 万敌 point06：血仇中致命 → 前 3 次不退血仇；第 4 次退出并清充能，仍存活 */
  function mydeiTryFatalSave(notes: string[]): boolean {
    // 致命时 HP 已为 0，不能用 isDead（否则保护永不触发）
    if (!mydeiBloodFeud) return false;
    if (mydeiFatalUsed >= TRACE.mydei.point06FatalCount + 1) return false;
    mydeiFatalUsed += 1;
    if (mydeiFatalUsed <= TRACE.mydei.point06FatalCount) {
      healUnit('mydei', maxHpOf('mydei') * TRACE.mydei.fatalHeal, 'mydei', notes, true);
      notes.push('mydeiFatal');
      return true;
    }
    mydeiExitBloodFeud();
    healUnit('mydei', maxHpOf('mydei') * TRACE.mydei.fatalHeal, 'mydei', notes, true);
    notes.push('mydeiFatalExit');
    return true;
  }
  /** 万敌 E4：血仇中每次敌方攻击事件后回复 10% 上限（多段只 1 次） */
  function mydeiOnEnemyAttack(notes: string[]): void {
    if (!mydeiBloodFeud || mydeiEidolon() < 4 || isDead('mydei')) return;
    healUnit('mydei', maxHpOf('mydei') * TRACE.mydei.eidolon4Heal, 'mydei', notes);
    notes.push('mydeiE4Heal');
  }
  /** 血仇满充能 → 下一次行动立即行动并施放弑神登神
   *  （2026-11 用户裁定：这是**额外回合** → 插入回合，不动跑道、不算新回合） */
  function mydeiConsumeGodExtra(): void {
    if (!mydeiExtraTurnPending || !ids.has('mydei')) return;
    mydeiExtraTurnPending = false;
    if (isDead('mydei') || !tl.has('mydei')) return;
    mydeiGodExtraReady = true;
    tl.insertExtraTurn('mydei', 'mydeiGodExtra');
    warriorPendingNotes.push('mydeiGodExtra');
  }
  function mydeiSpendCurrentHp(pct: number, attackKey: string): number {
    const cur = memberHp['mydei'] ?? maxHpOf('mydei');
    const amount = Math.min(Math.max(0, cur - 1), cur * pct);
    if (amount <= 0) return 0;
    const applied = consumeHp('mydei', amount, { keepHp: 1 });
    if (applied <= 0) return 0;
    onHpLoss('mydei', applied, { attackKey });
    return applied;
  }
  function mydeiZoneExtras(): AttackSpec['zoneExtras'] | undefined {
    return mydeiBloodFeud && mydeiEidolon() >= 2
      ? { defIgnore: TRACE.mydei.eidolon2DefIgnore }
      : undefined;
  }
  /** 万敌 Blast（主/相邻，生命上限倍率） */
  function mydeiBlast(
    skillCode: string,
    skillId: string,
    kind: 'skill',
    main: MonsterId,
    multMain: number,
    multAdj: number,
    critDmgBonus = 0,
  ): number[] {
    const p = panelOf('mydei');
    const stance = stanceOf(skillId, levelsOf('mydei')[kind]);
    const targets: MonsterId[] = [main, ...resolveAdjacent(main)];
    const seqs: number[] = [];
    for (const target of targets) {
      const mult = target === main ? multMain : multAdj;
      seqs.push(
        ...dealAttack({
          source: 'mydei',
          skillCode,
          element: p.element,
          level: p.level,
          statValue: maxHpOf('mydei'),
          hpBased: true,
          multiplier: mult,
          damageBonusExtra: 0,
          critRate: p.critRate,
          critDmg: p.critDmg + critDmgBonus,
          stance,
          attackerBuffs: attackerHolder('mydei'),
          target,
          attackKind: kind,
          zoneExtras: mydeiZoneExtras(),
        }),
      );
    }
    return seqs;
  }
  /** 万敌血仇自动战技 / 弑神登神 */
  function mydeiAutoAction(notes: string[]): { hitSeqs: number[]; skillCode: string } {
    const p = panelOf('mydei');
    const isGod = mydeiGodExtraReady;
    mydeiGodExtraReady = false;
    // 献予「纷争」之诗：本次弑神登神的暴伤加成（读完即清，只作用于这一次攻击）
    const poemGodCrit = mydeiPoemGodCritDmg;
    mydeiPoemGodCritDmg = 0;
    const hitSeqs: number[] = [];
    if (isGod) {
      const main =
        mydeiGodTarget && monsters[mydeiGodTarget]?.hp > 0 ? mydeiGodTarget : resolveMain();
      mydeiNoCharge = true;
      if (mydeiEidolon() >= 1) {
        const mult = TRACE.mydei.godSkillMainHp * (1 + TRACE.mydei.eidolon1MainBonus);
        for (const ent of aliveEnemyEntities()) {
          hitSeqs.push(
            ...dealAttack({
              source: 'mydei',
              skillCode: 'mydei.autoGod',
              element: p.element,
              level: p.level,
              statValue: maxHpOf('mydei'),
              hpBased: true,
              multiplier: mult,
              damageBonusExtra: 0,
              critRate: p.critRate,
              critDmg: p.critDmg + poemGodCrit,
              stance: stanceOf('140411', levelsOf('mydei').skill),
              attackerBuffs: attackerHolder('mydei'),
              target: ent.id as MonsterId,
              attackKind: 'skill',
              zoneExtras: mydeiZoneExtras(),
            }),
          );
        }
      } else {
        hitSeqs.push(
          ...mydeiBlast(
            'mydei.autoGod',
            '140411',
            'skill',
            main,
            TRACE.mydei.godSkillMainHp,
            TRACE.mydei.godSkillAdjHp,
            poemGodCrit,
          ),
        );
      }
      mydeiNoCharge = false;
      mydeiGodTarget = undefined;
      notes.push('mydeiGod');
      gainEnergy('mydei', 30);
      return { hitSeqs, skillCode: 'mydei.autoGod' };
    }
    mydeiSpendCurrentHp(TRACE.mydei.autoSkillHpCost, 'mydei.autoKing');
    const main = resolveMain();
    hitSeqs.push(
      ...mydeiBlast(
        'mydei.autoKing',
        '140409',
        'skill',
        main,
        TRACE.mydei.autoSkillMainHp,
        TRACE.mydei.autoSkillAdjHp,
      ),
    );
    gainEnergy('mydei', 30);
    notes.push('mydeiAutoKing');
    return { hitSeqs, skillCode: 'mydei.autoKing' };
  }

  // ===== 毁灭：Saber / 吉尔伽美什 / 米沙 =====
  const saberEidolon = () => members.find((x) => x.id === 'saber')?.eidolonLevel ?? 0;
  const gilgameshEidolon = () => members.find((x) => x.id === 'gilgamesh')?.eidolonLevel ?? 0;
  const mishaEidolon = () => members.find((x) => x.id === 'misha')?.eidolonLevel ?? 0;

  function saberAddRes(n: number): void {
    if (n <= 0 || isDead('saber')) return;
    saberResonance += n;
    const room = Math.max(0, TRACE.saber.p08MaxStacks - saberP08Stacks);
    const add = Math.min(n, room);
    if (add > 0) {
      saberP08Stacks += add;
      addBuff(holderOf('saber'), {
        key: 'critDmg',
        value: TRACE.saber.p08PerRes * saberP08Stacks,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
        source: 'saber',
        labelKey: 'saberP08',
      });
    }
    if (saberEidolon() >= 2) {
      const before = saberE2DefStacks;
      saberE2DefStacks = Math.min(TRACE.saber.e2Max, saberE2DefStacks + n);
      if (saberE2DefStacks > before) {
        addBuff(holderOf('saber'), {
          key: 'defIgnore',
          value: TRACE.saber.e2DefIgnorePer * saberE2DefStacks,
          stacks: 1,
          duration: -1,
          tick: 'permanent',
          source: 'saber',
          labelKey: 'saberE2',
        });
      }
    }
  }

  function saberZoneExtras(extra?: { resPenetration?: number }): { defIgnore?: number; resPenetration?: number } | undefined {
    const zx: { defIgnore?: number; resPenetration?: number } = {};
    if (extra?.resPenetration) zx.resPenetration = extra.resPenetration;
    return Object.keys(zx).length > 0 ? zx : undefined;
  }

  function saberGainRaw(amount: number): void {
    if (isDead('saber') || amount <= 0) return;
    const before = energy.saber;
    gainEnergyRaw('saber', amount);
    const gained = energy.saber - before;
    if (gained < amount) {
      const cap = saberEidolon() >= 6 ? TRACE.saber.p07OverflowE6 : TRACE.saber.p07Overflow;
      saberOverflow = Math.min(cap, saberOverflow + (amount - gained));
    }
  }

  function saberConsumeRes(): number {
    const n = saberResonance;
    saberResonance = 0;
    if (n > 0) saberGainRaw(n * TRACE.saber.resEnergy);
    return n;
  }

  function saberP08CritDmg(): number {
    return TRACE.saber.p08SkillCritDmg;
  }

  function gilgameshAddZing(n: number): void {
    if (n <= 0 || isDead('gilgamesh')) return;
    gilgameshZing = Math.min(TRACE.gilgamesh.talentZingMax, gilgameshZing + n);
    gilgameshZingTotal += n;
    const capped = Math.min(TRACE.gilgamesh.p07Max, gilgameshZingTotal);
    if (capped > 0) {
      addBuff(holderOf('gilgamesh'), {
        key: 'critDmg',
        value: TRACE.gilgamesh.p07CritDmgPer * capped,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
        source: 'gilgamesh',
        labelKey: 'gilgameshP07',
      });
    }
    addBuff(holderOf('gilgamesh'), {
      key: 'speedPct',
      value: TRACE.gilgamesh.talentSpeedPer * gilgameshZing,
      stacks: 1,
      duration: -1,
      tick: 'permanent',
      source: 'gilgamesh',
      labelKey: 'gilgameshZing',
    });
    if (gilgameshZing >= TRACE.gilgamesh.talentZingMax) gilgameshInMood = true;
    gilgameshSyncSpeed();
  }

  function gilgameshSyncSpeed(): void {
    if (!tl.has('gilgamesh')) return;
    const next = 1 + TRACE.gilgamesh.talentSpeedPer * gilgameshZing;
    if (next === gilgameshSpeedMult) return;
    tl.speedChange('gilgamesh', (tl.getUnit('gilgamesh').speed / gilgameshSpeedMult) * next);
    gilgameshSpeedMult = next;
  }

  function gilgameshClearZing(): void {
    gilgameshZing = 0;
    gilgameshInMood = false;
    removeBuffInstance(holderOf('gilgamesh'), { key: 'speedPct', source: 'gilgamesh', labelKey: 'gilgameshZing' });
    gilgameshSyncSpeed();
  }

  function gilgameshJoint(notes: string[], hitSeqs: number[]): void {
    if (gilgameshJointCount < TRACE.gilgamesh.jointCount) return;
    gilgameshJointCount = 0;
    const targets = aliveMonsters();
    for (const target of targets) {
      hitSeqs.push(
        ...dealAttack({
          source: 'gilgamesh',
          skillCode: 'gilgamesh.joint',
          element: panelOf('gilgamesh').element,
          level: panelOf('gilgamesh').level,
          statValue: panelOf('gilgamesh').attack,
          multiplier: TRACE.gilgamesh.jointGil,
          damageBonusExtra: 0,
          critRate: panelOf('gilgamesh').critRate,
          critDmg: panelOf('gilgamesh').critDmg,
          stance: stanceOf('150905', levelsOf('gilgamesh').talent),
          attackerBuffs: attackerHolder('gilgamesh'),
          target,
          attackKind: 'followup',
        }),
      );
    }
    if (ids.has('saber') && !isDead('saber')) {
      for (const target of targets) {
        hitSeqs.push(
          ...dealAttack({
            source: 'saber',
            skillCode: 'saber.joint',
            element: panelOf('saber').element,
            level: panelOf('saber').level,
            statValue: panelOf('saber').attack,
            multiplier: TRACE.gilgamesh.jointSaber,
            damageBonusExtra: 0,
            critRate: panelOf('saber').critRate,
            critDmg: panelOf('saber').critDmg,
            stance: stanceOf('150905', levelsOf('gilgamesh').talent),
            attackerBuffs: attackerHolder('saber'),
            target,
            attackKind: 'followup',
          }),
        );
      }
      saberGainRaw(TRACE.gilgamesh.jointSaberEnergy);
      saberJointUltReady = true;
    }
    gilgameshAddZing(TRACE.gilgamesh.jointZing);
    notes.push('gilgameshJoint');
  }

  function mishaAddHits(n: number): void {
    mishaUltHits = Math.min(TRACE.misha.ultMaxHits, mishaUltHits + n);
  }

  function mishaApplyFreeze(
    mon: Parameters<typeof applyControlToMonster>[0],
    first: boolean,
    notes: string[],
  ): void {
    const chance = TRACE.misha.ultFreezeChance + (first ? TRACE.misha.p06Freeze : 0);
    if (applyControlToMonster(mon, 'freeze', chance, notes, 'misha')) {
      mon.states.mishaFreezeDmg = TRACE.misha.freezeDmg;
    }
  }

  function mishaHit(target: ReturnType<typeof resolveMain>, notes: string[], first: boolean): number[] {
    const p = panelOf('misha');
    const seqs = dealAttack({
      source: 'misha',
      skillCode: 'misha.ult',
      element: p.element,
      level: p.level,
      statValue: p.attack,
      multiplier: TRACE.misha.ultHitMult + (mishaEidolon() >= 4 ? TRACE.misha.e4Dmg : 0),
      damageBonusExtra: 0,
      critRate: p.critRate,
      critDmg: p.critDmg,
      stance: first ? stanceOf('131203', levelsOf('misha').ult) : 0,
      attackerBuffs: attackerHolder('misha'),
      target,
      attackKind: 'ult',
    });
    mishaApplyFreeze(monsters[target], first, notes);
    return seqs;
  }

  /** 空槽配置（未配置的怪物位：HP=0、不上行动条、不被选为目标） */
  const EMPTY_MONSTER: MonsterConfig = {
    level: 0,
    hp: 0,
    resistance: {},
    weaknesses: [],
    maxToughness: 0,
  };
  /**
   * 波次序列（2026-10-22 用户裁定③④）：
   * monsterWaves（每波一组怪，最多 3 只）> monsters（同场多怪）> 旧口径（config.monster 复制三份）。
   * 旧口径保留「一套配置复制三份」——2026-10 多目标裁定的零回归基线。
   */
  const monsterWaves: MonsterConfig[][] = config.monsterWaves?.length
    ? config.monsterWaves
    : [
        config.monsters?.length
          ? config.monsters
          : [config.monster ?? EMPTY_MONSTER, config.monster ?? EMPTY_MONSTER, config.monster ?? EMPTY_MONSTER],
      ];
  /** 当前波序号（monsterWaves 推进用；单波恒 0） */
  let waveIndex = 0;
  /**
   * 【虚构叙事】波次规则（2026-10-30 用户裁定 56，口头给的阈值 = 20）：
   *   1. 第 1 波是小怪潮：每波只加载前 3 只，槽内怪死亡后**从本波剩余池补位**；
   *      累计击杀达到 `pureKillTarget`（默认 20）才换波。
   *   2. 第 2 波起：**boss（槽 1，即数据里每波第一只）死亡即换波**，小怪是否清完不影响。
   *   3. 最后一波的 boss 死亡 = 直接胜利（不等小怪清完）。
   * 仅 `config.waveClearRule === 'pure'` 且显式给了 `monsterWaves` 时生效（其余模式逐位不变）。
   */
  const pureWaves = config.waveClearRule === 'pure' && !!config.monsterWaves?.length;
  const pureKillTarget = config.pureKillTarget ?? 20;
  /** 每波「前 5 只之后」的剩余池（按波索引；补位从这里取） */
  const wavePools: MonsterConfig[][] = (config.monsterWaves ?? []).map((w) => w.slice(5));
  /** 本波累计击杀（仅第 1 波使用；换波清零） */
  let waveKillCount = 0;
  /**
   * 多怪/波次模式（2026-10-22 用户裁定③）：各怪独立死亡退场，死亡怪不再出手。
   * 旧口径（一套配置复制三份的木桩）保持原行为（死亡怪仍参与行动）——零回归，
   * 既有 sampo 等锚点依赖「死亡怪仍出手回能」。
   */
  const multiMonsterMode = !!(config.monsters?.length || config.monsterWaves?.length);
  /**
   * 波次模式（2026-10-22 用户裁定）：仅显式给 config.monsterWaves 时成立。
   * 成立时事件带 wave（波次号，与轮次/回合并列的第三层）+ kind:'wave' 换波事件；
   * 旧口径（同场多怪 monsters[] / 单怪复制三份）恒无 wave 字段 → 零回归。
   */
  const waveMode = !!config.monsterWaves?.length;
  const buildMonster = (cfg: MonsterConfig): MonsterState => ({
    noSplit: cfg.noSplit === true,
    phase: 1,
    level: cfg.level,
    hp: cfg.hp,
    maxHp: cfg.hp,
    maxToughness: cfg.maxToughness,
    toughnessUiMax: cfg.toughnessUiMax,
    toughness: cfg.maxToughness,
    broken: false,
    cloudToughness: cfg.maxToughness * TRACE.fugue.talentCloudToughnessPct,
    cloudActive: false,
    cloudUsed: false,
    weaknesses: new Set(cfg.weaknesses),
    // 每个木桩独立副本：狼尊E6进场改写抗性时不得污染 config.monster（跨战斗共享对象，
    // 曾致后续战斗全部继承 -0.2 抗性、E4 等锚点错位）
    resistance: { ...cfg.resistance, ...cfg.elementResistance },
    enemyClass: cfg.enemyClass ?? 'normal',
    speed: cfg.speed ?? 100,
    buffs: {
      // 流年盾纱等被动：自身受到的伤害降低 → 统一走怪侧 dmgReduction buff（2026-10-23）
      buffs:
        enemySelfDamageReduction(cfg.monsterId) > 0
          ? [
              {
                key: 'dmgReduction',
                value: enemySelfDamageReduction(cfg.monsterId),
                stacks: 1,
                duration: -1,
                tick: 'permanent',
                source: 'passive',
                labelKey: 'selfDamageReduction',
              },
            ]
          : [],
    },
    dots: [],
    skillDots: [],
    hysPending: 0,
    threaded: false,
    debt: 0,
    arcana: 0,
    bsReveal: 0,
    monsterId: cfg.monsterId,
    atk: cfg.attack ?? 0,
    name: cfg.name,
    charge: undefined,
    locked: [],
    states: {},
    effectRes: cfg.effectRes ?? 0,
    effectHit: cfg.effectHit ?? 0,
    debuffResist: cfg.debuffResist ?? monsterDebuffResist(cfg.monsterId),
    debuffApplyResist: cfg.debuffApplyResist ?? {},
  });
  /** 波次阵容 → 5 槽排列（2026-11-01 用户裁定）：pure 模式第 2 波起 boss 居中（monster3），
   *  两侧各两只小怪；第 1 波小怪潮按顺序铺满 5 槽。 */
  function orderWave(cfg: MonsterConfig[]): (MonsterConfig | undefined)[] {
    const bossFirst = pureWaves && waveIndex >= 1 && cfg.length > 0;
    if (bossFirst) {
      const rest = cfg.slice(1);
      return [rest[0], rest[1], cfg[0], rest[2], rest[3]];
    }
    return [cfg[0], cfg[1], cfg[2], cfg[3], cfg[4]];
  }
  /** 各槽位是否配置了怪物（未配置 = 空位：HP=0、不上行动条、不被选为目标） */
  const wave0 = orderWave(monsterWaves[0] ?? []);
  const monsterConfigured: Record<MonsterId, boolean> = {
    monster1: !!wave0[0],
    monster2: !!wave0[1],
    monster3: !!wave0[2],
    monster4: !!wave0[3],
    monster5: !!wave0[4],
  };
  /** 敌人状态注册表：最多 5 个木桩槽 + 敌方召唤物（键 = enemyN）。
   *  2026-10-23 用户裁定：召唤物进入我方目标池 → 与木桩共用同一份 MonsterState 结构，
   *  伤害/减益/击破管线无需分叉；胜利判定仍只看木桩槽（aliveMonsters）。 */
  const monsters: Record<string, MonsterState> = {
    monster1: buildMonster(wave0[0] ?? EMPTY_MONSTER),
    monster2: buildMonster(wave0[1] ?? EMPTY_MONSTER),
    monster3: buildMonster(wave0[2] ?? EMPTY_MONSTER),
    monster4: buildMonster(wave0[3] ?? EMPTY_MONSTER),
    monster5: buildMonster(wave0[4] ?? EMPTY_MONSTER),
  };
  const MONSTER_IDS: MonsterId[] = ['monster1', 'monster2', 'monster3', 'monster4', 'monster5'];
  // ===== 统一状态框架（2026-10-22）=====
  // 定义表：combat/monster-status-data.ts（语义/上限/共享/阈值/参数）
  // 运行时实例：怪侧 `mon.states[id]`（层数）+ 战斗级共享池 `enemyStatusPool`（【嗜血】跨怪共享）
  // 钩子：回合开始/结束/受伤/死亡/破韧 → 本处统一派发；新增状态只写数据 + 处理器
  // （放在 monsters 之后：pushHit 可能在此之前被调用，勿把本块挪到其后）
  const enemyStatusPool = new Map<string, number>();
  type EnemyStatusHandler = (
    mon: MonsterState,
    ctx: { kind?: string; notes?: string[]; stacks: number },
  ) => void;
  const enemyStatusHandlers: Record<
    string,
    Partial<Record<EnemyStatusHook, EnemyStatusHandler>>
  > = {
    // 蚕食者之影【追忆刻度】：每次受到攻击后 -1 层（DoT 不算「受到攻击」；
    // 层数决定【黄金年代的解放】的连续攻击次数）
    scaleMarks: {
      onDamaged: (mon, ctx) => {
        if (ctx.kind !== 'direct' && ctx.kind !== 'elation' && ctx.kind !== 'breakTrigger') return;
        const marks = mon.states.scaleMarks ?? 0;
        if (marks > 0) mon.states.scaleMarks = marks - 1;
      },
    },
  };
  /** 取状态层数（共享状态读战斗级池） */
  const enemyStatusStacks = (mon: MonsterState, id: string): number => {
    if (enemyStatusShared(id)) return enemyStatusPool.get(id) ?? 0;
    return mon.states[id] ?? 0;
  };
  /** 施加状态（按定义表截断层数；共享状态入战斗级池）→ 返回施加后层数 */
  const addEnemyStatus = (mon: MonsterState, id: string, stacks = 1): number => {
    const max = enemyStatusMaxStacks(id);
    if (enemyStatusShared(id)) {
      const cur = enemyStatusPool.get(id) ?? 0;
      const next = max === undefined ? cur + stacks : Math.min(max, cur + stacks);
      enemyStatusPool.set(id, next);
      return next;
    }
    const cur = mon.states[id] ?? 0;
    const next = max === undefined ? cur + stacks : Math.min(max, cur + stacks);
    mon.states[id] = next;
    return next;
  };
  /** 派发状态钩子（怪侧状态 + 共享池状态） */
  const runEnemyStatusHook = (
    phase: EnemyStatusHook,
    mon: MonsterState,
    ctx: { kind?: string; notes?: string[] } = {},
  ): void => {
    const ids = new Set<string>([...Object.keys(mon.states), ...enemyStatusPool.keys()]);
    for (const id of ids) {
      const def = enemyStatusDef(id);
      if (!def?.hooks?.includes(phase)) continue;
      const stacks = enemyStatusStacks(mon, id);
      if (stacks <= 0) continue;
      enemyStatusHandlers[id]?.[phase]?.(mon, { ...ctx, stacks });
    }
  };
  // ===== 敌方负面/印记容器 + 印记解除 helper（提前到此处）=====
  // 原因：pushHit 可能在闭包初始化早期被调用（见 TDZ 坑）→ 被它调用的 helper 必须早于首次调用点初始化。
  const enemyDebuffs = new Map<string, EnemyDebuffState>();
  const enemyDebuffOf = (id: string): EnemyDebuffState => {
    let s = enemyDebuffs.get(id);
    if (!s) {
      s = { control: new Set<string>(), decay: 0, devour: 0, aquila: 0, olonisi: 0 };
      enemyDebuffs.set(id, s);
    }
    return s;
  };
  /** 艾格勒印记解除（狮鹫 402301002/004）：我方目标消灭敌方目标后解除（优先致命者） */
  const releaseAquilaMarks = (killerId: string): void => {
    const order = [killerId, ...members.map((m) => m.id).filter((id) => id !== killerId)];
    for (const mid of order) {
      const st = enemyDebuffs.get(mid);
      if (st && st.aquila > 0) st.aquila = 0;
    }
  };
  /** 欧洛尼斯印记解除（天马 402302001~004）：我方施放终结技后解除 */
  const releaseOlonisiMark = (id: string): void => {
    const st = enemyDebuffs.get(id);
    if (st && st.olonisi > 0) st.olonisi = 0;
  };
  // ===== 敌方召唤物（独立敌方实体，2026-10-22 M1；2026-10-23 可被我方击杀）=====
  // 召唤物 = 另一个怪档案（本地 data/monsters + Dimbreath SummonIDList 变体 id），
  // 独立 HP/速度/韧性/技能表，可上行动条（side:'enemy'）→ 与三个木桩不同槽。
  // 状态本体放 monsters 注册表（键 = enemyN），故我方伤害/减益/击破管线与木桩通用；
  // 但**不计入**「三桩全灭」的胜利判定（见 aliveMonsters），胜利条件不变。
  interface EnemyUnitState {
    id: EnemyUnitId;
    /** 召唤者木桩槽 */
    owner: MonsterId;
    /** 技能表键（父档案 id，如 2032010） */
    skillKey: string;
  }
  const ENEMY_UNIT_IDS: EnemyUnitId[] = ['enemy1', 'enemy2', 'enemy3', 'enemy4'];
  const enemyUnits = new Map<EnemyUnitId, EnemyUnitState>();
  const isEnemyUnitId = (x: string | undefined): x is EnemyUnitId =>
    !!x && (ENEMY_UNIT_IDS as string[]).includes(x);
  /** 指定档案 id 的存活召唤物槽（宏观生态系统吞噬用） */
  const aliveSummonOf = (monsterId: string): EnemyUnitId | undefined =>
    aliveEnemyUnits().find((uid) => monsters[uid]?.monsterId === monsterId);
  /** 存活敌方召唤物槽 */
  const aliveEnemyUnits = (): EnemyUnitId[] =>
    ENEMY_UNIT_IDS.filter((id) => (monsters[id]?.hp ?? 0) > 0);
  /**
   * 召唤物被击杀（2026-10-23）：退场 + 召唤者被动联动。
   * 联动数据来自召唤者技能表的被动 `summonDeathEffect`（亚婆离 503401007 胎儿之梦：
   * 胚芽被击杀 → 堕神之血生命值降低 + 【贪饕之眼】充能 +1；数值待核）。
   */
  const onEnemyUnitKilled = (unitId: EnemyUnitId): void => {
    const meta = enemyUnits.get(unitId);
    if (tl.has(unitId)) tl.removeUnit(unitId);
    const owner = meta?.owner;
    if (!owner) return;
    const om = monsters[owner];
    if (!om || om.hp <= 0) return;
    for (const sk of enemySkills(om.monsterId ?? '')) {
      if (!sk.passive || !sk.summonDeathEffect) continue;
      const eff = sk.summonDeathEffect;
      if (eff.hpRatio && eff.hpRatio > 0) om.hp -= om.maxHp * eff.hpRatio;
      if (eff.statusOnOwner) {
        addEnemyStatus(om, eff.statusOnOwner.status, eff.statusOnOwner.stacks);
      }
      break;
    }
  };
  /** 召唤敌方召唤物（数量上限可调；满额不再召唤） */
  const summonEnemyUnits = (
    owner: MonsterId,
    spec: { monsterId: string | string[]; count: number; maxAlive: number },
    level: number,
    notes: string[],
  ): void => {
    const owned = (): number =>
      [...enemyUnits.values()].filter((u) => (monsters[u.id]?.hp ?? 0) > 0).length;
    if (owned() >= spec.maxAlive) {
      notes.push('summonLimit');
      return;
    }
    const pool = Array.isArray(spec.monsterId) ? spec.monsterId : [spec.monsterId];
    for (let i = 0; i < spec.count; i += 1) {
      if (owned() >= spec.maxAlive) break;
      const pick =
        pool.length === 1
          ? pool[0]!
          : pool[Math.min(pool.length - 1, Math.floor(rand01() * pool.length))]!;
      const profile = summonMonsterProfile(pick);
      if (!profile) continue;
      const st = summonStats(profile, level);
      const slot = ENEMY_UNIT_IDS.find((id) => (monsters[id]?.hp ?? 0) <= 0);
      if (!slot) break;
      monsters[slot] = buildMonster({
        level,
        hp: st.hp,
        resistance: profile.resistance,
        weaknesses: profile.weaknesses,
        maxToughness: st.maxToughness,
        // 召唤物韧性与关卡怪同口径（内部单位 = 显示值 ×3）：击破系数吃显示值
        toughnessUiMax: st.maxToughness / 3,
        speed: st.speed,
        enemyClass: 'normal',
        attack: st.atk,
        monsterId: profile.monsterId,
        name: profile.name,
      });
      enemyUnits.set(slot, { id: slot, owner, skillKey: profile.skillKey });
      // 已被击杀的旧实体仍留在跑道上时先移除（同槽复用）
      if (tl.has(slot)) tl.removeUnit(slot);
      tl.addUnit({
        id: slot,
        side: 'enemy',
        speed: st.speed,
        order: members.length + 10 + ENEMY_UNIT_IDS.indexOf(slot),
      });
      notes.push('enemySummon');
    }
  };

  // ===== 【嗜血】/【月狂】（步离战首•呼雷 203401006 + 狼卒【狼吞】）=====
  /** 可进入【月狂】的敌方单位（可调参数；来源：本地 extra 220320101「能够进入【月狂】的敌方单位」名单） */
  const MOON_RAGE_ELIGIBLE = new Set(['2034010', '2034014', '203201003', '203202004', '2033010', '2033011']);
  /** 按怪侧 speedPct buff 同步行动条速度（基础速度 = mon.speed，2026-10-23 统一走 buff） */
  const syncEnemySpeed = (id: string): void => {
    if (!tl.has(id)) return;
    const mon = monsters[id];
    if (!mon) return;
    tl.speedChange(id, mon.speed * (1 + buffSum(mon.buffs, 'speedPct')));
  };
  /** 【壁垒反震】每层防御降低（4064012；数值占位，TODO(实机)） */
  const SHIELD_COUNTER_DEF_DOWN = 0.08;
  /**
   * 【强化防御】（皮糙肉厚 406401208）：战斗开始时自身进入强化防御——引擎无怪物防御属性，
   * 折算为**减伤乘区**（`dmgReduction`，求和≥1 时该段固定 1 点）。被弱点击破后由 applyBreak 解除。
   */
  function applyHardenedDefence(slot: string): void {
    const mon = monsters[slot];
    const def = mon ? enemySkills(mon.monsterId).find((s) => s.hardenedDefence)?.hardenedDefence : undefined;
    if (!mon || !def) return;
    addBuff(mon.buffs, {
      key: 'dmgReduction',
      value: def.dmgReduction,
      stacks: 1,
      duration: 999,
      tick: 'permanent',
      source: 'judge',
      labelKey: 'hardenedDefence',
    });
  }
  for (const mid of MONSTER_IDS) applyHardenedDefence(mid);
  // 【战甲】（天谴斗士/天谴先锋 城邦守护者）：开局挂层数与减伤
  for (const mid of MONSTER_IDS) applyArmor(mid);
  // 关卡级机制（2026-10-30 rulings 15~19 全 A）：开局一次性部分延到首个我方回合开始施加
  //（`holderOf` 等 const 尚未初始化，不能在 init 处调用）
  let stageMechanicsInitDone = false;

  /** 关卡机制：开局一次性效果（桎梏层数 / 编队第一位增益） */
  function applyStageMechanics(): void {
    if (stageMechanicsInitDone) return;
    stageMechanicsInitDone = true;
    if (stageMechanics.has('shackle') || stageMechanics.has('shackle2')) {
      // 桎梏「我方造成的伤害降低 20%」→ 目标 = allHolders（2026-11-02 C3 批次10）
      // memberShackle 是**逐成员**的层数状态（队友回合开始递减），保留原写法
      for (const m of members) memberShackle.set(m.id, 2);
      for (const h of allHolders()) {
        addBuff(h, {
          key: 'damageBonus',
          value: -0.2,
          stacks: 2,
          duration: -1,
          tick: 'permanent',
          source: 'stageMechanic',
          labelKey: 'shackle',
        });
      }
    }
    // 2026-11-06 用户裁定：「贪饕」附属【阿哈帮大忙了】按**关卡 buff** 接入（录屏局内面板有具体条目）：
    // 我方全体 攻击力+300 / 防御力+240（引擎无我方防御消费点，仅语义保留）/ 生命上限+600 /
    // 速度+12（真实速度走 tl.speedChange）/ 暴击伤害+30%。
    // 注：该 buff 不含任何击破特攻/削韧词条，不直接改击破与超击破；它只通过攻击力间接影响
    //     流萤 γ模组（每 10 点攻击 +0.8% 击破特攻），是录像 γ=126.4% 与引擎残差的来源之一。
    if (stageMechanics.has('ahaHelp')) {
      for (const m of members) {
        if (isDead(m.id)) continue;
        const h = holderOf(m.id);
        addBuff(h, { key: 'atkFlat', value: 300, stacks: 1, duration: -1, tick: 'permanent', source: 'stageMechanic', labelKey: 'ahaHelp' });
        addBuff(h, { key: 'maxHpFlat', value: 600, stacks: 1, duration: -1, tick: 'permanent', source: 'stageMechanic', labelKey: 'ahaHelp' });
        addBuff(h, { key: 'critDmg', value: 0.3, stacks: 1, duration: -1, tick: 'permanent', source: 'stageMechanic', labelKey: 'ahaHelp' });
        if (tl.has(m.id)) tl.speedChange(m.id, tl.getUnit(m.id).speed + 12);
      }
    }
    // 编队第一位：狂喜之夜（欢愉增笑 +50%）/ 领航誓言（战技与终结技抗穿 +50%）
    const first = members[0];
    if (!first) return;
    if (stageMechanics.has('ecstasyNight')) {
      addBuff(holderOf(first.id), {
        key: 'mirth',
        value: 0.5,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
        source: 'stageMechanic',
        labelKey: 'ecstasyNight',
      });
    }
    if (stageMechanics.has('pilotVow')) {
      addBuff(holderOf(first.id), {
        key: 'resPenetration',
        value: 0.5,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
        source: 'stageMechanic',
        labelKey: 'pilotVow',
      });
    }
    applyStartSummons();
  }
  /**
   * 开局召唤（2026-10-30 第十七批）：被动技能里的 `startSummon`（巴姆王【洗地机之乱】/
   * 金血忆灵【化整为零】）。与关卡机制同样延到首个我方回合开始，避免 summonEnemyUnits 的 TDZ。
   */
  function applyStartSummons(): void {
    for (const mid of MONSTER_IDS) {
      const mon = monsters[mid];
      if (!mon || mon.hp <= 0) continue;
      for (const sk of enemySkills(mon.monsterId ?? '')) {
        // 【化整为零】分裂（金血忆灵 4064012）：召唤 3 只【金血忆灵】并打上【合而为一】，
        // 本体进入【假死】并获得【血脉衰弱】层数
        if (sk.splitOnStart && !mon.noSplit) {
          const beforeIds = new Set([...enemyUnits.keys()]);
          // 注意：`summonEnemyUnits` 的 maxAlive 是**全局存活数**上限，分裂体必须共用
          // 「分裂体总数」这一上限，否则第 2、3 只会被 summonLimit 挡掉。
          const splitMax = sk.splitOnStart.monsterIds.length;
          for (const sid of sk.splitOnStart.monsterIds) {
            summonEnemyUnits(mid, { monsterId: sid, count: 1, maxAlive: splitMax }, mon.level, []);
          }
          for (const uid of enemyUnits.keys()) {
            if (!beforeIds.has(uid)) monsters[uid].states.merged = 1;
          }
          mon.states.feignDeath = 1;
          mon.states.bloodWeak = sk.splitOnStart.bloodWeak;
          break;
        }
        if (!sk.startSummon) continue;
        summonEnemyUnits(mid, sk.startSummon, mon.level, []);
        break;
      }
    }
  }
  /**
   * 统一转阶段状态机（2026-10-30 第二十四轮，裁定 39）：
   * 阶段数 = 技能表 `phaseList` 最大值（`monsterPhaseCount`），按 HP 均分推进；
   * 「转阶段效果」仅在技能表声明了转阶段行为时生效（`hardenedDefence` / `splitOnStart`）：
   * 韧性回满 → 清负面 → 重挂【强化防御】→ 【化整为零】重新分裂（若身上没有存活分裂体）。
   * 由 `checkVictory`（每次伤害结算后）与 `monsterTurn` 开头共同推进；note `enemyPhaseUp`
   * 经 `enemyPhaseNotes` 并入紧随其后的事件。
   */
  function tickMonsterPhase(mon: MonsterState, notes: string[] = []): void {
    const total = monsterPhaseCount(mon.monsterId);
    if (total <= 1) return;
    const cur = mon.phase ?? 1;
    const ratio = mon.maxHp > 0 ? mon.hp / mon.maxHp : 0;
    const want = Math.min(total, 1 + Math.floor((1 - ratio) * total));
    if (want <= cur) return;
    mon.phase = want;
    // 阶段**计数**对所有多阶段怪都推进（火花大会二阶段副战场数量等靠它）；
    // 但「转阶段效果」（韧性回满 / 清负面 / 重挂强化防御 / 重新分裂）只对**技能表里声明了
    // 转阶段行为的怪**生效（皮糙肉厚 hardenedDefence 或化整为零 splitOnStart）。
    // 否则会改写可可利亚这类「有 phaseList 但无转阶段文案」的怪的旧锚点。
    const phaseEntry =
      enemySkills(mon.monsterId).some((x) => x.hardenedDefence || x.splitOnStart);
    if (!phaseEntry) return;
    mon.toughness = mon.maxToughness;
    mon.broken = false;
    // 转阶段清空自身负面（文案「转阶段时清除自身所有负面状态」）：
    // 我方施加的 DoT / 技能 DoT / 减益 buff（正值 atkPct 等增益保留）+ 状态层数清零
    mon.dots = [];
    mon.skillDots = [];
    mon.buffs.buffs = mon.buffs.buffs.filter(
      (b) => !(b.value < 0) || b.labelKey === 'hardenedDefence' || b.source === 'passive',
    );
    for (const k of Object.keys(mon.states)) {
      const key = k as keyof typeof mon.states;
      if (key === 'phase' || key === 'merged' || key === 'feignDeath' || key === 'bloodWeak') continue;
      if (typeof mon.states[key] === 'number') mon.states[key] = 0;
    }
    applyHardenedDefence(slotOfMon(mon));
    // 【化整为零】转阶段重新分裂（已有存活分裂体则不重复）
    const sk = enemySkills(mon.monsterId).find((x) => x.splitOnStart);
    const hasSplit = [...enemyUnits.keys()].some(
      (uid) => monsters[uid]?.states.merged === 1 && (monsters[uid]?.hp ?? 0) > 0,
    );
    if (sk?.splitOnStart && !mon.noSplit && !hasSplit) {
      const owner = slotOfMon(mon) as MonsterId;
      const splitMax = sk.splitOnStart.monsterIds.length;
      // 只标记「本次新召唤出来的」分裂体（不能用 monsterId 反查：执刑就位也会召雉形）
      const beforeIds = new Set([...enemyUnits.keys()]);
      for (const sid of sk.splitOnStart.monsterIds) {
        summonEnemyUnits(owner, { monsterId: sid, count: 1, maxAlive: splitMax }, mon.level, notes);
      }
      for (const uid of enemyUnits.keys()) {
        if (!beforeIds.has(uid)) monsters[uid].states.merged = 1;
      }
      mon.states.feignDeath = 1;
      mon.states.bloodWeak = sk.splitOnStart.bloodWeak;
    }
    notes.push('enemyPhaseUp');
  }

  /** 敌方实体统一枚举（主槽三怪 + 召唤物） */
  interface EnemyEntity {
    id: string;
    /** 档案 id（判「可月狂」名单） */
    monsterId: string;
    /** 技能表键（取被动） */
    skillKey: string;
    /** 状态层数容器 */
    states: Record<string, number>;
  }
  const aliveEnemyEntities = (): EnemyEntity[] => {
    const list: EnemyEntity[] = [];
    for (const mid of MONSTER_IDS) {
      const mon = monsters[mid];
      if (mon.hp <= 0) continue;
      list.push({
        id: mid,
        monsterId: mon.monsterId ?? '',
        skillKey: mon.monsterId ?? '',
        states: mon.states,
      });
    }
    for (const uid of aliveEnemyUnits()) {
      const meta = enemyUnits.get(uid)!;
      const mon = monsters[uid]!;
      list.push({
        id: uid,
        monsterId: mon.monsterId ?? '',
        skillKey: meta.skillKey,
        states: mon.states,
      });
    }
    return list;
  };
  /** 共享状态层数（战斗级池；上限由定义表决定，未声明 = 不截断） */
  const addSharedEnemyStatus = (id: string, stacks = 1): number => {
    const max = enemyStatusMaxStacks(id);
    const cur = enemyStatusPool.get(id) ?? 0;
    const next = max === undefined ? cur + stacks : Math.min(max, cur + stacks);
    enemyStatusPool.set(id, next);
    return next;
  };
  /** 进入/退出【月狂】（2034014 = 【噬月】）：速度提高（比例可调）；进入时在行动序列插入【月狂倒计时】 */
  const setMoonRage = (
    ent: EnemyEntity,
    on: boolean,
    speedPct: number,
    countdownRounds?: number,
  ): void => {
    const cur = ent.states.moonRage ?? 0;
    // 该实体的进入参数（2034014：减伤 + 进入即施放【孤战】 + 怒意初始层数）
    const enterCfg = enemySkills(ent.skillKey).find((s) => s.passive && s.allyAttackStatus)?.allyAttackStatus;
    if (on) {
      if (cur > 0) return;
      ent.states.moonRage = 1;
      const mon = monsters[ent.id];
      if (mon) {
        addBuff(mon.buffs, {
          key: 'speedPct',
          value: speedPct,
          stacks: 1,
          duration: -1,
          tick: 'permanent',
          source: 'moonRage',
          labelKey: 'moonRage',
        });
        // 2034014【噬月】：受到的伤害降低（并入减伤乘区；不再提速 → speedPct 传 0）
        if (enterCfg?.dmgReduction) {
          addBuff(mon.buffs, {
            key: 'dmgReduction',
            value: enterCfg.dmgReduction,
            stacks: 1,
            duration: -1,
            tick: 'permanent',
            source: 'moonRage',
            labelKey: 'moonRageDr',
          });
        }
        syncEnemySpeed(ent.id);
      }
      // 【月狂倒计时】（用户裁定 2026-10-23）：行动序列插入定时条目；到点全体解除【月狂】
      if (countdownRounds && countdownRounds > 0 && tl.has(ent.id)) {
        tl.scheduleAction(ent.id, tl.time + countdownRounds * LATER_ROUND_AV, 'moonRageCountdown');
      }
      // 2034014【噬月】：获得【怒意】初始层数（此后我方回合结束 −1，归零退出噬月）
      if (enterCfg?.furyDecayOnAllyTurnEnd) {
        ent.states.fury = FURY_INITIAL_2034014;
      }
      // 2034014【噬月】→ 立即施放【孤战】（蓄力窗 + 插入一次行动，保证下一动必放）
      if (enterCfg?.onEnterSkillId) {
        const mon2 = monsters[ent.id];
        if (mon2) {
          mon2.charge = enterCfg.onEnterSkillId;
          if (tl.has(ent.id)) tl.insertAction(ent.id);
        }
      }
      return;
    }
    if (cur <= 0) return;
    ent.states.moonRage = 0;
    const mon = monsters[ent.id];
    if (mon) {
      removeBuffInstance(mon.buffs, { key: 'speedPct', source: 'moonRage', labelKey: 'moonRage' });
      removeBuffInstance(mon.buffs, { key: 'dmgReduction', source: 'moonRage', labelKey: 'moonRageDr' });
      syncEnemySpeed(ent.id);
    }
    // 【怒意】归零退出噬月 → 同时结束【孤战】（2034014）
    // 退出时清空【嗜血】池：否则退出当次累积的旧层数会立刻把本体重新拉回噬月（无限循环）
    const aasCfg = enemySkills(ent.skillKey).find((s) => s.passive && s.allyAttackStatus)?.allyAttackStatus;
    if (aasCfg?.furyDecayOnAllyTurnEnd) enemyStatusPool.set(aasCfg.status, 0);
    if (duelKeep !== null) exitDuel();
  };
  /** 全体解除【月狂】并还原速度（倒计时到点）；返回 notes */
  const clearAllMoonRage = (): string[] => {
    const notes: string[] = [];
    for (const ent of aliveEnemyEntities()) {
      if ((ent.states.moonRage ?? 0) > 0) {
        setMoonRage(ent, false, 0);
        notes.push('moonRageEnd');
      }
    }
    tl.clearScheduled('moonRageCountdown');
    return notes;
  };
  /** 【月狂】额外技能（该实体被动 allyAttackStatus.extraSkillId；仅月狂期间） */
  const moonRageExtraSkillOf = (ent: EnemyEntity): EnemySkillDef | undefined => {
    if ((ent.states.moonRage ?? 0) <= 0) return undefined;
    for (const sk of enemySkills(ent.skillKey)) {
      if (sk.passive && sk.allyAttackStatus?.extraSkillId) {
        return enemySkillById(ent.skillKey, sk.allyAttackStatus.extraSkillId);
      }
    }
    return undefined;
  };
  /**
   * 我方施放攻击后 → 可月狂单位共享【嗜血】层数 +1；达各自阈值 → 进入【月狂】（速度提高）
   * （每个带该被动的敌方实体各贡献 1 层；【嗜血】为战斗级共享池，跨怪共享）
   */
  const grantBloodRageOnAllyAttack = (): void => {
    const entities = aliveEnemyEntities();
    // 「我方施放攻击后附加 1 层」按**状态**去重：同场多只带该被动的敌方单位不叠加多层
    // （否则召唤 2 只狼卒时一次攻击 +3 层，噬月/月狂会被瞬间触发）
    const granted = new Set<string>();
    for (const ent of entities) {
      for (const sk of enemySkills(ent.skillKey)) {
        if (!sk.passive || !sk.allyAttackStatus) continue;
        if (granted.has(sk.allyAttackStatus.status)) continue;
        granted.add(sk.allyAttackStatus.status);
        addSharedEnemyStatus(sk.allyAttackStatus.status, sk.allyAttackStatus.stacks);
      }
    }
    const pool = enemyStatusPool.get('bloodRage') ?? 0;
    if (pool <= 0) return;
    for (const ent of entities) {
      if (!MOON_RAGE_ELIGIBLE.has(ent.monsterId)) continue;
      if ((ent.states.moonRage ?? 0) > 0) continue;
      for (const sk of enemySkills(ent.skillKey)) {
        if (!sk.passive || !sk.allyAttackStatus) continue;
        const aas = sk.allyAttackStatus;
        if (pool >= aas.threshold) {
          // 【嗜血】达阈值即消耗（2034014：避免退出噬月后立刻被旧层数重新拉进噬月）
          enemyStatusPool.set(aas.status, 0);
          setMoonRage(ent, true, aas.speedPct ?? 0, aas.countdownRounds);
          break;
        }
      }
    }
  };
  /**
   * 【怒意】（呼雷 203401007 啸月之狼；2026-10-22 用户裁定）：
   * - 仅自身处于【月狂】时生效；
   * - 敌方单位施放攻击后 +1 层（呼雷自身攻击额外 +1）；
   * - 我方施放攻击后 −1 层（归零 → 削减自身韧性并重置层数）。
   */
  const furyConfigOf = (
    ent: EnemyEntity,
  ): NonNullable<EnemySkillDef['furyOnEnemyAttack']> | undefined => {
    if ((ent.states.moonRage ?? 0) <= 0) return undefined;
    // 2034014 的【怒意】走「我方回合结束 −1」口径，不吃敌方攻击叠层
    const aas = enemySkills(ent.skillKey).find((s) => s.passive && s.allyAttackStatus)?.allyAttackStatus;
    if (aas?.furyDecayOnAllyTurnEnd) return undefined;
    for (const sk of enemySkills(ent.skillKey)) {
      if (sk.passive && sk.furyOnEnemyAttack) return sk.furyOnEnemyAttack;
    }
    return undefined;
  };
  /** 敌方施放攻击后 → 为月狂单位叠加【怒意】；达阈值 → 强制下次释放技能并清空层数 */
  const grantFuryOnEnemyAttack = (attackerId: string | undefined, notes: string[]): void => {
    for (const ent of aliveEnemyEntities()) {
      const cfg = furyConfigOf(ent);
      if (!cfg) continue;
      const add = cfg.stacks + (attackerId && attackerId === ent.id ? cfg.selfExtra : 0);
      const cur = ent.states[cfg.status] ?? 0;
      const max = enemyStatusMaxStacks(cfg.status);
      const next = max === undefined ? cur + add : Math.min(max, cur + add);
      ent.states[cfg.status] = next;
      if (next > cur) notes.push('enemyFury');
      if (next >= cfg.releaseThreshold) {
        ent.states[cfg.status] = 0;
        if (isMonsterId(ent.id)) monsters[ent.id].charge = cfg.castSkillId;
        notes.push('enemyFuryRelease');
      }
    }
  };
  /** 我方施放攻击后 → 月狂单位【怒意】−1；归零 → 削减其韧性并重置（返回是否发生削韧） */
  const reduceFuryOnAllyAttack = (): boolean => {
    let broke = false;
    for (const ent of aliveEnemyEntities()) {
      const cfg = furyConfigOf(ent);
      if (!cfg) continue;
      const cur = ent.states[cfg.status] ?? 0;
      if (cur <= 0) continue;
      const next = cur - 1;
      ent.states[cfg.status] = next;
      if (next <= 0) {
        ent.states[cfg.status] = 0;
        if (isMonsterId(ent.id) && cfg.toughnessCut > 0) {
          const mon = monsters[ent.id];
          mon.toughness = Math.max(0, mon.toughness - cfg.toughnessCut);
          broke = true;
        }
      }
    }
    return broke;
  };
  // ===== 2034014 雷奔云谲的恶狼主：【噬月】/【怒意】/【孤战】/【血涌】 =====
  /** 【怒意】进入【噬月】时的初始层数（文案「【怒意】拥有初始层数」，占位 8，TODO(实机)） */
  const FURY_INITIAL_2034014 = 8;
  /** 【血涌】（狼群敕令）：我方全体持有的层数（孤战期间转【战血激昂】，孤战结束移除） */
  let bloodSurge = 0;
  /** 【孤战】留下的那名我方成员（null = 未进入） */
  let duelKeep: CharId | null = null;
  /** 【孤战】期间离场我方的行动条快照（结束归还） */
  const duelSavedUnits = new Map<CharId, { av: number; order: number; speed: number }>();
  /** 【孤战】期间离场敌方的行动条快照（1v1：其余敌方目标离场） */
  const duelSavedEnemies = new Map<string, { order: number; speed: number }>();
  /** 【孤战】给自身的属性加成快照（退出时原样扣回） */
  let duelBoost: { slot: MonsterId; hp: number; atk: number } | null = null;

  /**
   * 【孤战】（203401409，2026-10-30 rulings 8「完整 1v1」）：
   * 选定 1 名我方（其召唤物随主人留场）→ 其余我方与其余敌方目标**离场**（不可行动/不可选中，
   * 复用白厄的离场/回归写法）→ 自身按我方全体的生命上限/攻击力提高血量与攻击
   * （占位：selfHpRatio / selfAtkRatio + 【血涌】×bloodSurgeAtk 转【战血激昂】）→ 我方回战技点。
   * 退出 = 【怒意】归零（噬月结束），血涌一并移除。
   */
  const enterDuel = (
    slot: MonsterId,
    keep: CharId,
    cfg: NonNullable<EnemySkillDef['duel']>,
    notes: string[],
  ): void => {
    if (duelKeep !== null) return;
    duelKeep = keep;
    if (cfg.spRestore > 0) {
      sp = Math.min(MAX_SP, sp + cfg.spRestore);
      notes.push('allySpRestore');
    }
    for (const m of members) {
      if (m.id === keep || isDead(m.id)) continue;
      if (!tl.has(m.id)) continue;
      const unit = tl.getUnit(m.id);
      duelSavedUnits.set(m.id, { av: unit.av, order: unit.order, speed: unit.speed });
      tl.removeUnit(m.id);
      duelExiled.add(m.id);
    }
    for (const ent of aliveEnemyEntities()) {
      if (ent.id === slot) continue;
      if (!tl.has(ent.id)) continue;
      const unit = tl.getUnit(ent.id);
      duelSavedEnemies.set(ent.id, { order: unit.order, speed: unit.speed });
      tl.removeUnit(ent.id);
    }
    const mon = monsters[slot];
    if (mon) {
      const hpAdd = mon.maxHp * cfg.selfHpRatio;
      const atkPct = cfg.selfAtkRatio + cfg.bloodSurgeAtk * bloodSurge;
      const atkAdd = mon.atk * atkPct;
      mon.maxHp += hpAdd;
      mon.hp = Math.min(mon.maxHp, mon.hp + hpAdd);
      mon.atk += atkAdd;
      duelBoost = { slot, hp: hpAdd, atk: atkAdd };
      notes.push('enemyDuelEnter');
    }
  };
  /** 退出【孤战】：属性还原 + 离场单位回归 + 清【血涌】 */
  const exitDuel = (): void => {
    if (duelKeep === null) return;
    if (duelBoost) {
      const mon = monsters[duelBoost.slot];
      if (mon) {
        mon.maxHp = Math.max(1, mon.maxHp - duelBoost.hp);
        mon.hp = Math.min(mon.hp, mon.maxHp);
        mon.atk = Math.max(1, mon.atk - duelBoost.atk);
      }
      duelBoost = null;
    }
    for (const [id, saved] of duelSavedUnits) {
      duelExiled.delete(id);
      if (!isDead(id) && !tl.has(id)) {
        tl.addUnit({ id, side: 'ally', speed: saved.speed, initialAv: saved.av, order: saved.order });
      }
    }
    duelSavedUnits.clear();
    for (const [id, saved] of duelSavedEnemies) {
      if ((monsters[id]?.hp ?? 0) > 0 && !tl.has(id)) {
        tl.addUnit({ id, side: 'enemy', speed: saved.speed, order: saved.order });
      }
    }
    duelSavedEnemies.clear();
    duelKeep = null;
    bloodSurge = 0;
  };
  /**
   * 我方回合结束：【噬月】的【怒意】−1，归零 → 退出【噬月】（连带结束【孤战】）。
   * 仅对声明 `furyDecayOnAllyTurnEnd` 的实体生效（2034014；2034010 的怒意走敌方攻击口径）。
   */
  const decayFuryOnAllyTurnEnd = (notes: string[]): void => {
    for (const ent of aliveEnemyEntities()) {
      if ((ent.states.moonRage ?? 0) <= 0) continue;
      const cfg = enemySkills(ent.skillKey).find((s) => s.passive && s.allyAttackStatus)?.allyAttackStatus;
      if (!cfg?.furyDecayOnAllyTurnEnd) continue;
      const cur = ent.states.fury ?? 0;
      if (cur <= 0) continue;
      ent.states.fury = cur - 1;
      if (ent.states.fury <= 0) {
        ent.states.fury = 0;
        setMoonRage(ent, false, 0);
        notes.push('enemyFuryBreak');
      }
    }
  };
  /**
   * 【韧性锁】（血鸣狂噬 203401406）：未进入【噬月】前韧性无法被削减。
   * 只有声明 `untouchableToughness` 的实体生效（2034014）。
   */
  const toughnessLocked = (mon: MonsterState): boolean => {
    if ((mon.states.moonRage ?? 0) > 0) return false;
    // 【破晓力场】（5013060/5013040）：力场期间韧性不可削（与【噬月】前同口径）
    if ((mon.states.forceField ?? 0) > 0) return true;
    // 【弱点无效】（灯塔【不屈正义】/ 帕姆王【值日准备中】）：挂着时韧性不可削
    if ((mon.states.weaknessInvalid ?? 0) > 0) return true;
    return enemySkills(mon.monsterId).some((s) => s.passive && s.untouchableToughness);
  };
  /** 本次行动玩家所选敌方主目标（全真模拟目标行；未选/无效 = 中间）   *  2026-10-23：可为敌方召唤物（enemyN）→ 单体攻击改打召唤物，AoE/扩散不波及召唤物 */
  let chosenTarget: CombatTarget | undefined = config.enemyTarget;
  const isMonsterId = (x: string | undefined): x is MonsterId =>
    x === 'monster1' || x === 'monster2' || x === 'monster3' || x === 'monster4' || x === 'monster5';
  /** 目标 id → CombatTarget（木桩槽或敌方召唤物；2026-10-23） */
  const asCombatTarget = (x: string | undefined): CombatTarget | undefined =>
    isMonsterId(x) || isEnemyUnitId(x) ? x : undefined;
  const aliveMonsters = (): MonsterId[] => MONSTER_IDS.filter((id) => monsters[id].hp > 0);
  /** 玩家选定的、仍存活的敌方召唤物（无效 → undefined） */
  const chosenSummonAlive = (): EnemyUnitId | undefined =>
    isEnemyUnitId(chosenTarget) && (monsters[chosenTarget]?.hp ?? 0) > 0 ? chosenTarget : undefined;
  /** 单体/主目标解析：玩家所选（活着）→ 中间（活着）→ 第一个活着的 */
  const resolveMain = (): MonsterId => {
    // 默认主目标 = 存活槽位的中心：3 槽（monster1-3）= monster2，5 槽（含 monster4/5）= monster3
    const centerId: MonsterId =
      monsterConfigured.monster4 || monsterConfigured.monster5 ? 'monster3' : 'monster2';
    // 【连麦PK】战场隔离（裁定 51）：打副战场的角色只能选副战场敌方，反之亦然
    if (pkActive && pkSubEnemies.size > 0) {
      if (pkField === 'sub') {
        const subAlive = [...pkSubEnemies].filter((id) => (monsters[id as MonsterId]?.hp ?? 0) > 0);
        const chosen = chosenTarget;
        if (chosen && pkSubEnemies.has(chosen) && (monsters[chosen as MonsterId]?.hp ?? 0) > 0) {
          return chosen as unknown as MonsterId;
        }
        if (subAlive.length > 0) return subAlive[0] as unknown as MonsterId;
      } else {
        const mainAlive = MONSTER_IDS.filter(
          (id) => monsters[id].hp > 0 && !pkSubEnemies.has(id),
        );
        const chosen = chosenTarget;
        if (chosen && isMonsterId(chosen) && mainAlive.includes(chosen)) return chosen;
        if (mainAlive.includes(centerId)) return centerId;
        if (mainAlive.length > 0) return mainAlive[0]!;
      }
    }
    // 玩家指定了敌方召唤物（2026-10-23）→ 单体/主目标攻击改打该召唤物。
    // 返回类型仍是 MonsterId（下游全部经 monsters[id] 索引，召唤物与木桩共用同一注册表），
    // 运行时 id 为 enemyN；AoE/扩散经 resolveAdjacent 不会自动波及召唤物。
    const s = chosenSummonAlive();
    if (s) return s as unknown as MonsterId;
    const t = chosenTarget;
    if (isMonsterId(t) && monsters[t].hp > 0) return t;
    if (monsters[centerId].hp > 0) return centerId;
    return aliveMonsters()[0] ?? centerId;
  };
  /** 实际命中目标（2026-10-23 召唤物）：玩家指定召唤物时，原本打「主目标」的
   *  单体攻击改为打该召唤物；其余（显式指定其它木桩槽 / DoT 跳伤 / 破韧登记）保持原样 */
  const resolveTargetOf = (t?: CombatTarget): CombatTarget => {
    const s = chosenSummonAlive();
    if (s && (t === undefined || t === resolveMain())) return s;
    return t ?? resolveMain();
  };
  /** 相邻目标（1↔2↔3↔4↔5 链式）：只返回仍存活的；召唤物无相邻（不波及） */
  const resolveAdjacent = (t: CombatTarget): MonsterId[] => {
    if (!isMonsterId(t)) return [];
    // 【连麦PK】副战场敌方彼此无相邻关系（裁定 51），主战场也不跨场溅射
    if (pkActive && pkSubEnemies.has(t)) return [];
    const idx = MONSTER_IDS.indexOf(t);
    const near = [MONSTER_IDS[idx - 1], MONSTER_IDS[idx + 1]].filter((x): x is MonsterId => !!x);
    return near.filter((id) => monsters[id].hp > 0 && !(pkActive && pkSubEnemies.has(id)));
  };

  // ===== 大黑塔 1401：解读层数（怪侧 buff，value=1×stacks，上限 42）=====
  const hertaInterpOf = (t: MonsterId): number => (monsters[t] ? buffSum(monsters[t].buffs, 'interpretation') : 0);
  /** 直接写入解读层数；gainMystery=false 用于终结技重排/死亡转移，避免重复叠谜底 */
  const hertaSetInterpRaw = (t: MonsterId, n: number, gainMystery = true): void => {
    const mon = monsters[t];
    if (!mon) return;
    const cur = hertaInterpOf(t);
    const next = Math.max(0, Math.min(TRACE.herta.interpretationCap, Math.round(n)));
    if (next === cur) return;
    if (next === 0) {
      removeBuffInstance(mon.buffs, { key: 'interpretation', source: 'herta', labelKey: 'hertaInterpretation' });
    } else {
      addBuff(mon.buffs, {
        key: 'interpretation',
        value: 1,
        stacks: next,
        duration: -1,
        tick: 'permanent',
        source: 'herta',
        labelKey: 'hertaInterpretation',
      });
    }
    if (gainMystery && next > cur) {
      hertaMystery = Math.min(TRACE.herta.mysteryCap, hertaMystery + (next - cur));
    }
  };
  const hertaAddInterp = (t: MonsterId, n: number): void => hertaSetInterpRaw(t, hertaInterpOf(t) + n);
  const hertaWaveStart = (): void => {
    const alive = aliveMonsters();
    if (alive.length === 0) return;
    const elites = alive.filter((t) => monsters[t].enemyClass === 'elite');
    const pool = elites.length > 0 ? elites : alive;
    const target = pool[Math.floor(rand01() * pool.length)];
    hertaAddInterp(target, TRACE.herta.waveStartStacks);
  };
  const hertaTransferInterp = (from: MonsterId): void => {
    const amount = hertaInterpOf(from);
    if (amount <= 0) return;
    hertaSetInterpRaw(from, 0, false);
    const alive = aliveMonsters().filter((t) => t !== from);
    if (alive.length === 0) return;
    const elites = alive.filter((t) => monsters[t].enemyClass === 'elite');
    const pool = elites.length > 0 ? elites : alive;
    const target = pool[Math.floor(rand01() * pool.length)];
    hertaSetInterpRaw(target, hertaInterpOf(target) + amount, false);
  };
  const hertaMageCount = (): number => members.filter((m) => CHAR_PATH[m.id] === 'Mage').length;

  /** 全单位增益持有者（惰性创建：四成员 + 神君/忆灵/龙灵）。
   * 全队 buff（晴歌光锥、救世主、隐士等）需挂所有输出单位。 */
  const holderMap = new Map<string, BuffHolder>();
  const holderOf = (id: string): BuffHolder => {
    let h = holderMap.get(id);
    if (!h) {
      h = { buffs: [] };
      holderMap.set(id, h);
    }
    return h;
  };
  const attackerHolder = (id: CombatUnitId): BuffHolder => holderOf(id);
  energyRegenBuffOf = (id) => buffSum(holderOf(id).buffs, 'energyRegen');

  /**
   * 我方召唤物 / 忆灵单位全集 —— 「我方目标 / 我方全体」语义的 buff 必须覆盖这些 holder。
   *
   * **单一真相 = `SUMMON_OWNERS`**（含神君/晴空乐手/龙灵/衣匠/迷迷/死龙/小伊卡/长夜/德谬歌/浮元）。
   * 因为召唤物不继承主人 buff（`holderOf` 按单位 id 独立，攻击时读 `attackerHolder(<自己>)`），
   * 漏掉谁 = 谁的伤害永远吃不到任何全队增益（2026-11-02 复盘的系统性 bug：
   * 原实现手写 8 个，漏了 `mimi` / `fuyuan`）。
   */
  const ALLY_SUMMON_UNITS: readonly AllyUnitId[] = SUMMON_OWNERS.map((s) => s.id);

  /** 我方全体 holder（全队 buff 用；召唤物未出场也持有，出场即带着） */
  const allHolders = (): BuffHolder[] => [
    ...members.map((m) => holderOf(m.id)),
    ...ALLY_SUMMON_UNITS.map((id) => holderOf(id)),
  ];

  /**
   * 召唤物（重新）登场 / 退场时的 holder 重置：**清掉瞬发与限时状态，保留常驻光环**（`duration === -1`）。
   *
   * 为什么不能写成 `holderOf(x).buffs = []`（2026-11-02 修）：`allHolders()` 把「我方全体 / 我方目标」
   * 的常驻 buff 挂在召唤物 holder 上，整批清空会连它们一起丢；更关键的是**退场后再召唤没有任何补挂路径**
   * （各召唤函数只在在场时补挂自己的专属效果）→ 一旦退场过，该忆灵就永久吃不到全队增益。
   * 实测：小伊卡在风堇首次战技召唤后丢掉晴歌 1512 E2 的抗穿，由 `memory-summon-buff-matrix` 用例抓到。
   */
  const resetSummonHolder = (unit: AllyUnitId): void => {
    const h = holderOf(unit);
    h.buffs = h.buffs.filter((b) => b.duration === -1);
  };

  /** 当前嘲讽值 = 基础值 + `taunt` buff 加算（下限 1；不可受击单位恒 0） */
  const tauntOf = (unit: string): number => {
    const base = baseTauntOf(unit);
    if (base <= 0) return 0;
    // 三月七战技「受击概率大幅提高」= 嘲讽 +50（加算点数），**有护盾时生效**（2026-10-24 用户裁定）
    const shieldTaunt = ids.has('sanyueqi') && (shieldValues[unit] ?? 0) > 0 ? 50 : 0;
    // 素裳 point06「赤子」：当前生命百分比 ≤50% → 被敌方攻击的概率降低（权重 −25；上限 1 由末位 clamp 兜底）
    const sushangP06 =
      unit === 'sushang' &&
      ids.has('sushang') &&
      !isDead('sushang') &&
      (memberHp.sushang ?? maxHpOf('sushang')) / Math.max(1, maxHpOf('sushang')) <=
        TRACE.sushang.p06HpThreshold
        ? TRACE.sushang.p06Taunt
        : 0;
    // 彦卿【智剑连心】「受击概率降低」= 嘲讽权重 −25（2026-10-29 嘲讽口径：不是强制主目标）
    const yanqingWisdomTaunt =
      unit === 'yanqing' && ids.has('yanqing') && !isDead('yanqing') && yanqingWisdomTurns > 0
        ? TRACE.yanqing.wisdomTaunt
        : 0;
    // 丹恒 point06「潜龙」：当前生命百分比 ≤50% → 被攻击概率降低（权重 −25）
    const danhengP06 =
      unit === 'danheng' &&
      ids.has('danheng') &&
      !isDead('danheng') &&
      (memberHp.danheng ?? maxHpOf('danheng')) / Math.max(1, maxHpOf('danheng')) <=
        TRACE.danheng.p06HpThreshold
        ? TRACE.danheng.p06Taunt
        : 0;
    // 希儿 point06「夜行」：当前生命百分比 ≤50% → 被攻击概率降低（权重 −25）
    const seeleP06 =
      unit === 'seele' &&
      ids.has('seele') &&
      !isDead('seele') &&
      (memberHp.seele ?? maxHpOf('seele')) / Math.max(1, maxHpOf('seele')) <=
        TRACE.seele.p06HpThreshold
        ? TRACE.seele.p06Taunt
        : 0;
    return Math.max(
      1,
      base +
        buffSum(holderOf(unit).buffs, 'taunt') +
        shieldTaunt +
        sushangP06 +
        yanqingWisdomTaunt +
        danhengP06 +
        seeleP06,
    );
  };
  /** 按嘲讽权重抽 1 个目标（只耗 1 次 rand01，调用顺序与旧均匀抽样一致） */
  const pickByTaunt = (pool: readonly string[]): string => {    if (pool.length === 0) return '';
    const weights = pool.map((u) => tauntOf(u));
    const total = weights.reduce((a, b) => a + b, 0);
    if (total <= 0) {
      return pool[Math.min(pool.length - 1, Math.floor(rand01() * pool.length))] as string;
    }
    let r = rand01() * total;
    for (let i = 0; i < pool.length; i += 1) {
      r -= weights[i] as number;
      if (r < 0) return pool[i] as string;
    }
    return pool[pool.length - 1] as string;
  };

  // ===== 花火进战初始化（holderOf 声明后才可调） =====
  if (ids.has('huahuo')) {
    // 行迹夜想曲 point08：我方全体攻击力 +45%（常驻）——「我方全体」→ allHolders（2026-11-02 C3 批次1）
    for (const h of allHolders()) {
      addBuff(h, {
        key: 'atkPct',
        source: 'huahuo',
        labelKey: 'traceHhP08',
        value: TRACE.huahuo.point08AtkPct,
        stacks: 1,
        duration: -1,
        tick: 'permanent',
      });
    }
    // E1：开战时花火速度+15%（2 回合，自身行动递减）
    hh2GrantE1Speed([]);
    // 专武 23021：装备者获得【假面】（开战 #6=3 回合；#1 暴伤=面板词条不进引擎）
    const w21 = members.find((m) => m.lightconeId === '23021' && lcPathOk(m.id, '23021'));
    if (w21) {
      lc21Wear = w21.id;
      const lp = lcParams('23021', w21.refinement ?? 1);
      if (lp) {
        LC23021 = {
          maskCritDmg: lp[1],
          maskTurns: lp[2],
          flameMax: lp[3],
          maskCritRate: lp[4],
          maskInitTurns: lp[5],
        };
      }
      lc21MaskLeft = LC23021.maskInitTurns;
      lc21MaskSkip = true;
      syncLc21Mask();
    }
  }

  // ===== 同谐四人进战初始化（1412/1309/1303/8005；holderOf/tl 已就绪） =====
  if (ids.has('cerdra') && !isDead('cerdra')) {
    // 行迹见者 point07：自身暴击率 +100%（常驻；用户裁定字面）
    addBuff(holderOf('cerdra'), {
      key: 'critRate', source: 'cerdra', labelKey: 'traceCdP07',
      value: TRACE.cerdra.point07SelfCritRate, stacks: 1, duration: -1, tick: 'permanent',
    });
    // 行迹来者 point06：自暴伤随攻击力动态（进战先算一次）
    syncCerdraP06();
  }
  if (ids.has('robin') && !isDead('robin')) {
    // 天赋：我方全体暴伤 +27.5%（常驻）——「我方全体」→ allHolders（2026-11-02 C3 批次1）
    for (const h of allHolders()) {
      addBuff(h, {
        key: 'critDmg', source: 'robin', labelKey: 'robinTalent',
        value: skillParams('130904', levelsOf('robin').talent)[0], stacks: 1, duration: -1, tick: 'permanent',
      });
    }
    // 行迹 point06：战斗开始时自身行动提前 25%
    if (tl.has('robin')) tl.actionAdvance('robin', TRACE.robin.point06ActionAdvance);
  }
  if (ids.has('ruanmei') && !isDead('ruanmei')) {
    // 行迹物体呼吸中 point06：我方全体击破特攻 +20%（常驻）——→ allHolders（2026-11-02 C3 批次1）
    for (const h of allHolders()) {
      addBuff(h, {
        key: 'breakEffect', source: 'ruanmei', labelKey: 'traceRmP06',
        value: TRACE.ruanmei.point06BreakEffect, stacks: 1, duration: -1, tick: 'permanent',
      });
    }
    // 天赋：除自身外全队速度 +11%（常驻；真实速度经 tl.speedChange）
    for (const m of members) {
      if (m.id === 'ruanmei' || isDead(m.id) || !tl.has(m.id)) continue;
      tl.speedChange(m.id, tl.getUnit(m.id).speed * (1 + skillParams('130304', levelsOf('ruanmei').talent)[0]));
    }
  }
  {
    const tb = members.find((m) => isTbShaman(m.id) && !isDead(m.id));
    if (tb) {
      // E2：开战时自身能量恢复效率 +25%（3 回合，自身行动递减）
      if (trailblazerShamanEidolon() >= 2) {
        addBuff(holderOf(tb.id), {
          key: 'energyRegen', source: tb.id, labelKey: 'tbsE2',
          value: TRACE.trailblazerShaman.eidolon2EnergyRegen, stacks: 1,
          duration: TRACE.trailblazerShaman.eidolon2Turns, tick: 'holderEnd',
        });
      }
      // E4：除自外全队 BE += 自BE×15%（进战判定一次；伴舞起落再重算）
      syncTbE4();
    }
  }

  // ===== 佩拉进战初始化（1106） =====
  if (ids.has('pela') && !isDead('pela')) {
    // 行迹 point07 秘策：佩拉在场时我方全体效果命中 +10%（常驻；经 buffSum('effectHit') 被全部概率负面消费）
    for (const h of allHolders()) {
      addBuff(h, {
        key: 'effectHit', source: 'pela', labelKey: 'pelaP07',
        value: TRACE.pela.point07EffectHit, stacks: 1, duration: -1, tick: 'permanent',
      });
    }
  }

  /** 光锥23036织锦：按当前层数刷新 buff——挂阿雅 holder（装备者），忆灵在场时同挂。
   *  忆灵未出场不挂（避免快照行幻影），召唤时由 summonYijiang 调本函数补挂；
   *  destroyYijiang 清忆灵 holder buff → 再召唤重新同步。 */
  const syncZhijin = (): void => {
    if (GEAR.aglaea.zhijinMax <= 0 || zhijinStacks === 0) return;
    const spec = {
      key: 'critDmg' as const,
      source: 'lightcone',
      labelKey: 'lcZhijin',
      value: GEAR.aglaea.zhijinCritDmg,
      stacks: zhijinStacks,
      duration: -1,
      tick: 'permanent' as const,
    };
    addBuff(holderOf('aglaea'), spec);
    if (present.yijiang) addBuff(holderOf('yijiang'), spec);
  };
  /** 光锥23036【织锦】：装备者与忆灵「攻击后」使装备者获得 1 层（上限封顶）。调用点=命中>0。 */
  const gainZhijin = (notes: string[]): void => {
    if (GEAR.aglaea.zhijinMax <= 0) return;
    zhijinStacks = Math.min(GEAR.aglaea.zhijinMax, zhijinStacks + 1);
    notes.push('lcZhijin');
    syncZhijin();
  };
  /** 光锥23036满层加成：每层普攻伤害 +#3%（仅阿雅/其忆灵的普攻段；
   *  孤锋千吻衣匠段是否按普攻计=待核，先含入与文本「造成的普攻伤害」一致） */
  const zhijinBasicExtra = (source: string, kind: string): number =>
    GEAR.aglaea.zhijinMax > 0 &&
    zhijinStacks >= GEAR.aglaea.zhijinMax &&
    (source === 'aglaea' || source === 'yijiang') &&
    kind === 'basic'
      ? GEAR.aglaea.zhijinBasic * zhijinStacks
      : 0;

  const shenjunSpeed = (): number => 30 + 10 * stacks;
  /** 景元 EX：神君段数上限 10→30；满层立即行动 */
  const jingyuanMaxHits = (): number => 10 + (jingyuanExOn ? TRACE.jingyuan.exMaxHits : 0);
  function jingyuanAddStacks(add: number, notes: string[]): void {
    const cap = jingyuanMaxHits();
    const before = stacks;
    stacks = Math.min(cap, stacks + add);
    tl.speedChange('shenjun', shenjunSpeed());
    if (jingyuanExOn && jingyuanExLeft > 0) notes.push('jingyuanEx');
    if (jingyuanExOn && before < cap && stacks >= cap) {
      notes.push('jingyuanExFull');
      if (tl.has('shenjun')) tl.instantAction('shenjun');
    }
  }
  /** 忆灵速度 = 晴歌面板速 × 151204 #2（=180%；数据实读，勿写死）；
   *  星魂4生效后追加 +（20%+当前气氛×0.5%），实时随气氛同步 */
  const memoSpeed = (): number =>
    (skillParams('151204', levelsOf('qingge').talent)[1] ?? 1.8) *
    panelOf('qingge').speed *
    (qgE4Speed
      ? 1 + TRACE.qingge.eidolon4MemoSpeedBase + mood * TRACE.qingge.eidolon4MemoSpeedPerMood
      : 1);
  /** 星魂4：气氛变化/进Fever后同步忆灵速度（timeline speedChange 保持路程不变） */
  const syncMemoSpeed = (): void => {
    if (qgE4Speed && tl.has('memo')) tl.speedChange('memo', memoSpeed());
  };

  // 专武23053 叠影覆写（同类不叠加=槽位序第一件；无 23053 → 维持 R1 默认）
  const lc23053Wearer = members.find((m) => m.lightconeId === '23053' && lcPathOk(m.id, '23053'));
  if (lc23053Wearer) {
    const lp = lcParams('23053', lc23053Wearer.refinement ?? 1);
    if (lp) {
      LC23053 = {
        spCapPer: lp[1],
        spCapMax: lp[2],
        pushDegree: lp[3],
        defIgnoreMax: lp[4],
        defIgnorePer: lp[5],
        pushSp: lp[6],
      };
    }
  }

  // 专武23065/23054 叠影覆写（按光锥 id 激活——任何成员携带都生效，与23053裁定10同口径；
  // 同类不叠加=槽位序第一件；无装备 → 维持 R1 默认、效果门由 wear id 判定）
  const lc23065Wearer = members.find((m) => m.lightconeId === '23065' && lcPathOk(m.id, '23065'));
  if (lc23065Wearer) {
    lc65Wear = lc23065Wearer.id;
    const lp65 = lcParams('23065', lc23065Wearer.refinement ?? 1);
    if (lp65) LC23065 = { laughGain: lp65[1], cdTurns: lp65[2], defIgnore: lp65[3] };
  }
  const lc23054Wearer = members.find((m) => m.lightconeId === '23054' && lcPathOk(m.id, '23054'));
  if (lc23054Wearer) {
    lc54Wear = lc23054Wearer.id;
    const lp54 = lcParams('23054', lc23054Wearer.refinement ?? 1);
    if (lp54) {
      LC23054 = {
        speedPct: lp54[0],
        critRate: lp54[1],
        critDmg: lp54[2],
        signTurns: lp54[3],
        err: lp54[4],
        waveEnergy: lp54[5],
      };
    }
  }

  // ===== 角色模块单场守卫 / 散落备注（2026-10-24 结构层试点）=====
  /** 已接管过免死的模块 id（单场每模块只接管 1 次：模块自己写的次数语义仍留在模块内，此处只防重复接管） */
  const moduleReviveUsed = new Set<string>();
  /** 模块回合开始产生的散落备注（charAction 后并入本次行动事件——tailsPendingNotes 同款） */
  let modulePendingNotes: string[] = [];

  /** 角色模块 ctx 组装：把本闭包里已有的状态/helper 映射成 `CharModuleCtx`。
   *  模块不 import battle.ts（避免循环依赖），所需状态全由这里传入；只做接线，不改任何数值。 */
  const charModuleCtx = (notes: string[]): CharModuleCtx => ({
    ids,
    members,
    memberHp,
    shieldValues,
    shieldTurns,
    energy,
    isDead,
    panelOf: (id) => panelOf(id as CharId),
    energyMaxOf: (id) => ENERGY_MAX[id as CharId] ?? 0,
    skillParams,
    instantAction: (id) => tl.instantAction(id),
    notes,
    addTaunt: (id, value, labelKey, source) =>
      addBuff(holderOf(id), { key: 'taunt', source, labelKey, value, stacks: 1, duration: -1, tick: 'permanent' }),
    addAtkFlat: (id, value, labelKey, source) =>
      addBuff(holderOf(id), { key: 'atkFlat', source, labelKey, value, stacks: 1, duration: -1, tick: 'permanent' }),
    addEffectRes: (id, value, labelKey, source) =>
      addBuff(holderOf(id), { key: 'effectRes', source, labelKey, value, stacks: 1, duration: -1, tick: 'permanent' }),
    /** 全队护盾（覆盖式）：盾量 = 来源防御×defPct + flat；逐成员刷新 point06 支援钩子 */
    applyTeamShield: (defPct, flat, turns, source) => {
      for (const m of members) {
        if (isDead(m.id)) continue;
        shieldValues[m.id] = panelOf(source as CharId).defence * defPct + flat;
        shieldTurns[m.id] = turns;
        dahliaP06OnAllySupport(m.id, source as CombatUnitId);
      }
    },
  });

  members.forEach((m, i) => {
    memberHp[m.id] = Math.max(1, Number.isFinite(m.panel.hp) ? m.panel.hp : 1);
    // 素裳：E4 击破特攻 +40%（常驻）；E6 进战自带 1 层天赋加速（速度同步在行动轴就绪后调用）
    if (m.id === 'sushang') {
      if ((m.eidolonLevel ?? 0) >= 4) {
        addBuff(holderOf('sushang'), {
          key: 'breakEffect',
          value: TRACE.sushang.e4BreakEffect,
          stacks: 1,
          duration: -1,
          tick: 'permanent',
          source: 'sushang',
          labelKey: 'sushangE4',
        });
      }
      if ((m.eidolonLevel ?? 0) >= 6) {
        sushangSpeedStacks = 1;
        sushangSpeedTurns = TRACE.sushang.talentTurns;
      }
    }
    // 阿兰 E4「坚忍」：进战即获得免死，持续到第 2 次自身行动开始
    if (m.id === 'arlan' && (m.eidolonLevel ?? 0) >= 4) arlanE4Turns = TRACE.arlan.e4Turns;
    // 白厄：point06 开战 +1 火种、E6 开战 +6；point08 开战 1 层攻击
    if (m.id === 'phainon') {
      phainonSeed = TRACE.phainon.p06Start + ((m.eidolonLevel ?? 0) >= 6 ? TRACE.phainon.e6Start : 0);
      phainonSyncEnergy();
      phainonP08Stacks = 1;
      phainonSyncP08();
    }
    // 真理医生 E1「思辨」：进战立即获得 4 层归纳（上限同步 +4）
    if (m.id === 'ratio' && (m.eidolonLevel ?? 0) >= 1) {
      ratioStacks = TRACE.ratio.e1Start;
      ratioSyncStacks();
    }
    // 三月七 E2「记忆中的它」：进战为当前生命%最低的我方目标提供护盾 = 防御×24% + 320，3 回合
    if (m.id === 'sanyueqi' && (m.eidolonLevel ?? 0) >= 2) {
      const lowest = members
        .filter((x) => !isDead(x.id))
        .sort(
          (a, b) =>
            (memberHp[a.id] ?? 1) / Math.max(1, a.panel.hp) -
            (memberHp[b.id] ?? 1) / Math.max(1, b.panel.hp),
        )[0];
      if (lowest) {
        shieldValues[lowest.id] = panelOf('sanyueqi').defence * 0.24 + 320;
        shieldTurns[lowest.id] = 3;
        dahliaP06OnAllySupport(lowest.id, 'sanyueqi');
      }
    }
    // 砂金行迹 point07「热手」：战斗开始时为我方全体提供护盾 = 战技护盾量的 #2=100%，持续 #1=3 回合
    if (m.id === 'aventurine') {
      const av7 = skillParams('130402', levelsOf('aventurine').skill);
      const av7Base = panelOf('aventurine').defence * av7[0] + av7[1];
      for (const am of members) {
        if (isDead(am.id)) continue;
        shieldValues[am.id] = av7Base;
        shieldTurns[am.id] = 3;
        dahliaP06OnAllySupport(am.id, 'aventurine');
      }
    }
    // 杰帕德秘技 110407「有情之证」：下一次战斗开始时为我方全体提供护盾
    // = 防御力×#1 + #3，持续 #2 回合
    if (m.id === 'gepard' && techniques) {      const gp7 = skillParams('110407', 1);
      const gp7Shield = panelOf('gepard').defence * gp7[0] + gp7[2];
      for (const gm of members) {
        if (isDead(gm.id)) continue;
        shieldValues[gm.id] = gp7Shield;
        shieldTurns[gm.id] = Math.round(gp7[1] ?? 3);
        dahliaP06OnAllySupport(gm.id, 'gepard');
      }
    }
    // 砂金秘技 130407「红黑之间」：进战为我方全体提供防御力提高 #1/#2/#3，持续 #4 回合
    // 三档按概率抽取：一定概率档 30% / 大概率档 60% / 小概率档 10%（2026-10-24 用户裁定）
    if (m.id === 'aventurine' && techniques) {
      const av7p = skillParams('130407', 1);
      const av7r = rand01();
      const av7tier = av7r < 0.3 ? 0 : av7r < 0.9 ? 1 : 2;
      const av7up = av7p[av7tier] ?? 0;
      const av7turns = Math.round(av7p[3] ?? 3);
      if (av7up !== 0) {
        // 130407「使我方全体提高对应数值的防御力」→ allHolders（2026-11-02 C3 批次9）
        for (const h of allHolders()) {
          addBuff(h, {
            key: 'defPct',
            source: 'aventurine',
            labelKey: 'avenTech',
            value: av7up,
            stacks: 1,
            duration: av7turns,
            tick: 'holderEnd',
          });
        }
      }
    }
    const initialAv =
      m.id === 'qingge' && techniques ? (TRACK_LENGTH / m.panel.speed) * 0.8 : undefined;
    tl.addUnit({
      id: m.id,
      side: 'ally',
      speed: m.panel.speed,
      order: i,
      ...(initialAv !== undefined ? { initialAv } : {}),
    });
  });
  // ===== 托帕&账账 1112：进战召唤账账（独立行动条实体；无生命/不占我方目标池） =====
  if (ids.has('topaz')) {
    tl.addUnit({
      id: 'topazNumby',
      side: 'ally',
      speed: TRACE.topaz.numbySpeed,
      order: members.length,
    });
  }
  // ===== 貊泽 1223：E1 进战恢复 20 能量（固定值，不吃充能效率）；充能/猎物初始 0 =====
