      const p = skillParams('1151201', levelsOf('qingge').memoSkill);
      // 忆灵属性 = 召唤时晴歌面板快照（2026-10 裁定）；生命/速度等文案写明属性不走快照
      const qpanel = ownerPanel('memo');
      const hitSeqs: number[] = [];
      // 1151201 tag=AoEAttack（对敌方全体）→ 三木桩各一段（2026-10 多目标裁定）
      relicFollowupStart('memo');
