      let lowest = members[0]?.id;
      let lowestVal = Number.POSITIVE_INFINITY;
      for (const m of members) {
        const v = shieldValues[m.id] ?? 0;
        if (v < lowestVal) {
          lowestVal = v;
          lowest = m.id;
        }
      }
