        const zhengRongShield =
          (panelOf('tenghuang').attack * TRACE.tenghuang.zhengRongShieldAtk +
            TRACE.tenghuang.zhengRongShieldFlat) *
          relicShieldMult() *
          (enhancedAct && tenghuangEidolon() >= 2 ? TRACE.tenghuang.eidolon2ShieldMult : 1);
        shieldValues[lowest] = lowestVal + zhengRongShield;
